begin;
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:riz au lait', 'Rice pudding', array['en:rice pudding']::text[], 'dish', $r$[{"title":"Rice pudding","intro":"The creamy vanilla rice pudding of our childhood.","minutes":45,"calories":320,"difficulty":"Facile","imageSearch":"rice pudding","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"short-grain rice","plural":"short-grain rice","qty":120,"unit":"g","have":false},{"name":"whole milk","plural":"whole milk","qty":1000,"unit":"ml","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false}],"steps":[{"text":"Rinse the rice and blanch it for 2 min in boiling water.","timer":{"label":"Cooking","min":2}},{"text":"Heat the milk with the split vanilla pod.","timer":null},{"text":"Add the drained rice and cook for 35 min over a low heat, stirring often.","timer":{"label":"Cooking","min":35}},{"text":"Add the sugar at the end and leave to cool slightly.","timer":null}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Coconut rice pudding","intro":"An exotic rice pudding with coconut and mango.","minutes":45,"calories":360,"difficulty":"Facile","imageSearch":"coconut rice pudding mango","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"short-grain rice","plural":"short-grain rice","qty":120,"unit":"g","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"milk","plural":"milk","qty":60,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"mango","plural":"mangoes","qty":1,"unit":"","have":false}],"steps":[{"text":"Heat the milk and coconut milk.","timer":null},{"text":"Add the rinsed rice and cook for 35 min over a low heat, stirring.","timer":{"label":"Cooking","min":35}},{"text":"Add the sugar, leave to cool and serve with the diced mango.","timer":null}],"dessert":true,"variant":"Coconut milk","change":"Coconut milk replaces some of the milk."},{"title":"Caramel rice pudding","intro":"Rice pudding with a salted butter caramel.","minutes":50,"calories":400,"difficulty":"Facile","imageSearch":"rice pudding salted caramel","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"short-grain rice","plural":"short-grain rice","qty":120,"unit":"g","have":false},{"name":"whole milk","plural":"whole milk","qty":1000,"unit":"ml","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"salted butter","plural":"salted butter","qty":30,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Cook the rice in the milk for 35 min over a low heat with 40 g of sugar.","timer":{"label":"Cooking","min":35}},{"text":"Make a caramel with the rest of the sugar, then add the butter and the cream.","timer":{"label":"Caramel","min":5}},{"text":"Serve the rice pudding topped with caramel.","timer":null}],"kids":true,"dessert":true,"variant":"Caramel","change":"A salted butter caramel tops the rice pudding."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:flan patissier', 'Custard flan', array['en:custard flan', 'en:french flan']::text[], 'dish', $r$[{"title":"Custard flan","intro":"The bakery flan: a firm vanilla custard on crisp pastry.","minutes":80,"calories":340,"difficulty":"Moyen","imageSearch":"french custard flan","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":1,"unit":"","have":false},{"name":"whole milk","plural":"whole milk","qty":750,"unit":"ml","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":70,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Roll the pastry out into a deep tin.","timer":null},{"text":"Heat the milk with the vanilla.","timer":null},{"text":"Whisk the eggs, sugar and cornflour, pour in the hot milk and put back on the heat, stirring until thick.","timer":{"label":"Custard","min":4}},{"text":"Pour onto the pastry and bake for 45 min.","timer":{"label":"Oven","min":45}},{"text":"Leave to cool, then chill for 4 h.","timer":{"label":"Chill","min":240}}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Crustless flan","intro":"The creamy flan, baked straight in the dish.","minutes":60,"calories":240,"difficulty":"Facile","imageSearch":"crustless custard flan","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"milk","plural":"milk","qty":750,"unit":"ml","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":60,"unit":"g","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":2,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Make the thick custard as for the custard flan.","timer":null},{"text":"Pour into a buttered dish and bake for 40 min.","timer":{"label":"Oven","min":40}},{"text":"Leave to cool, then chill.","timer":{"label":"Chill","min":180}}],"dessert":true,"variant":"No pastry","change":"No pastry, so lighter."},{"title":"Coconut flan","intro":"A coconut flan, like in the French Caribbean.","minutes":60,"calories":360,"difficulty":"Facile","imageSearch":"coconut flan","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"coconut milk","plural":"coconut milk","qty":25,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"desiccated coconut","plural":"desiccated coconut","qty":60,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":60,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Heat the milks, add the eggs beaten with the sugar and cornflour, and thicken.","timer":{"label":"Custard","min":4}},{"text":"Add the coconut, pour into a dish and bake for 40 min.","timer":{"label":"Oven","min":40}}],"dessert":true,"variant":"Coconut","change":"Desiccated coconut and coconut milk flavour the flan."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:saumon au four', 'Baked salmon', array['en:baked salmon', 'en:salmon fillet', 'en:baked salmon with lemon']::text[], 'dish', $r$[{"title":"Baked salmon fillets","intro":"Tender salmon fillets baked in the oven with lemon, dill and a drizzle of olive oil.","minutes":25,"calories":420,"difficulty":"Facile","imageSearch":"baked salmon fillet lemon dill","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"salmon fillet","plural":"salmon fillets","qty":4,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Place the fillets in a dish, skin-side down.","timer":null},{"text":"Drizzle with oil, add lemon slices, the dill, salt and pepper.","timer":null},{"text":"Bake for 15 min: the middle should still be slightly translucent.","timer":{"label":"Oven","min":15}}],"variant":"The classic","change":""},{"title":"Mustard and honey baked salmon","intro":"A sweet and savoury mustard and honey glazed salmon.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"honey mustard salmon","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"salmon fillet","plural":"salmon fillets","qty":4,"unit":"","have":false},{"name":"wholegrain mustard","plural":"wholegrain mustard","qty":2,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":1,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Mix the mustard, honey and the juice of the lemon.","timer":null},{"text":"Brush over the fillets, then add salt and pepper.","timer":null},{"text":"Bake for 15 min.","timer":{"label":"Oven","min":15}}],"variant":"Mustard and honey","change":"A mustard and honey glaze caramelises on top."},{"title":"Salmon and vegetable traybake","intro":"The full meal on one tray: salmon, broccoli and potatoes.","minutes":40,"calories":520,"difficulty":"Facile","imageSearch":"salmon traybake vegetables","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"salmon fillet","plural":"salmon fillets","qty":4,"unit":"","have":false},{"name":"baby potato","plural":"baby potatoes","qty":600,"unit":"g","have":false},{"name":"broccoli","plural":"broccoli","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Put the halved potatoes on a tray with 2 tbsp of oil, salt and paprika. Bake for 20 min.","timer":{"label":"Oven","min":20}},{"text":"Add the broccoli florets and the salmon fillets, drizzled with oil and lemon.","timer":null},{"text":"Bake for another 15 min.","timer":{"label":"Oven","min":15}}],"variant":"All in one","change":"The vegetables cook on the same tray as the salmon."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:dos de cabillaud', 'Baked cod', array['en:baked cod', 'en:cod fillet', 'en:baked cod with lemon butter']::text[], 'dish', $r$[{"title":"Baked cod with lemon butter","intro":"Flaky cod baked in the oven with a lemon and parsley butter.","minutes":25,"calories":320,"difficulty":"Facile","imageSearch":"baked cod lemon butter","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cod loin","plural":"cod loins","qty":4,"unit":"","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Place the cod in a dish and season with salt and pepper.","timer":null},{"text":"Melt the butter with the garlic, the lemon juice and the parsley, and pour over the fish.","timer":null},{"text":"Bake for 12 min.","timer":{"label":"Oven","min":12}}],"variant":"The classic","change":""},{"title":"Provençal-style cod","intro":"A sunny cod dish with tomato, olives and thyme.","minutes":30,"calories":300,"difficulty":"Facile","imageSearch":"cod provencal tomato olives","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cod loin","plural":"cod loins","qty":4,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"black olive","plural":"black olives","qty":50,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Fry the onion and garlic in the oil, then add the tomatoes, olives and thyme. Cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Pour into a dish, lay the cod on top, and season with salt and pepper.","timer":null},{"text":"Bake for 15 min.","timer":{"label":"Oven","min":15}}],"variant":"Provençal","change":"The fish cooks on a tomato and olive sauce."},{"title":"Parmesan-crusted cod","intro":"Fish that is crunchy on top and tender inside, which kids like.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"parmesan crusted cod","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cod loin","plural":"cod loins","qty":4,"unit":"","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":40,"unit":"g","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":40,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":30,"unit":"g","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Mix the breadcrumbs, parmesan, parsley and melted butter.","timer":null},{"text":"Place the cod in a dish, season with salt and cover with the mixture.","timer":null},{"text":"Bake for 15 min.","timer":{"label":"Oven","min":15}}],"kids":true,"variant":"Crusted","change":"A breadcrumb and parmesan crust makes the top crunchy."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:moule mariniere', 'Moules marinières', array['en:mussel', 'en:moule frite', 'en:mussel in white wine']::text[], 'dish', $r$[{"title":"Mussels marinière","intro":"Mussels steamed open in white wine, with shallots and parsley.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"moules marinieres mussels","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"mussel","plural":"mussels","qty":2000,"unit":"g","have":false},{"name":"white wine","plural":"white wine","qty":20,"unit":"cl","have":false},{"name":"shallot","plural":"shallots","qty":3,"unit":"","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Scrub and rinse the mussels, and throw away any that are open.","timer":null},{"text":"Soften the sliced shallots in the butter in a large pot.","timer":null},{"text":"Add the wine and mussels, cover and cook for 6 min over a high heat, shaking the pot.","timer":{"label":"Cooking","min":6}},{"text":"Sprinkle with parsley and pepper. Serve with chips or bread.","timer":null}],"variant":"The classic","change":""},{"title":"Creamy mussels","intro":"Moules marinières with a creamy sauce.","minutes":25,"calories":460,"difficulty":"Facile","imageSearch":"mussels cream sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"mussel","plural":"mussels","qty":2000,"unit":"g","have":false},{"name":"white wine","plural":"white wine","qty":20,"unit":"cl","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"shallot","plural":"shallots","qty":3,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Prepare the mussels.","timer":null},{"text":"Soften the shallots in the butter, add the wine and mussels, cover and cook for 6 min.","timer":{"label":"Cooking","min":6}},{"text":"Take out the mussels, add the cream to the juices and let it reduce for 3 min.","timer":{"label":"Cooking","min":3}},{"text":"Pour the sauce over the mussels and sprinkle with parsley.","timer":null}],"variant":"Creamy","change":"Crème fraîche thickens the sauce."},{"title":"Curried mussels","intro":"Mussels in a coconut curry sauce.","minutes":25,"calories":440,"difficulty":"Facile","imageSearch":"mussels coconut curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"mussel","plural":"mussels","qty":2000,"unit":"g","have":false},{"name":"coconut milk","plural":"coconut milk","qty":20,"unit":"cl","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tsp","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Prepare the mussels.","timer":null},{"text":"Fry the onion and garlic in the oil with the curry powder for 2 min.","timer":null},{"text":"Add the coconut milk and mussels, cover and cook for 6 min.","timer":{"label":"Cooking","min":6}},{"text":"Sprinkle with coriander.","timer":null}],"variant":"Curried","change":"A coconut curry sauce replaces the wine."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:crevette a l ail', 'Garlic prawns', array['en:garlic prawn', 'en:gamba', 'en:sauteed prawn', 'en:garlic shrimp']::text[], 'dish', $r$[{"title":"Garlic and parsley sautéed prawns","intro":"Prawns pan-fried with garlic and parsley, in 10 minutes.","minutes":10,"calories":220,"difficulty":"Facile","imageSearch":"garlic shrimp","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"raw prawn","plural":"raw prawns","qty":500,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":4,"unit":"clove","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"dried chilli","plural":"dried chillies","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Peel the prawns, keeping the tails on.","timer":null},{"text":"Heat the oil with the chopped garlic and the chilli for 1 min.","timer":null},{"text":"Add the prawns and sauté for 3 min, until pink.","timer":{"label":"Pan","min":3}},{"text":"Add the parsley, the lemon juice and the salt.","timer":null}],"variant":"The classic","change":""},{"title":"Creamy garlic prawns","intro":"Prawns in a creamy garlic sauce, perfect over tagliatelle.","minutes":15,"calories":380,"difficulty":"Facile","imageSearch":"creamy garlic shrimp","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"raw prawn","plural":"raw prawns","qty":500,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":30,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Sauté the prawns in the butter for 3 min. Set aside.","timer":{"label":"Pan","min":3}},{"text":"Fry the garlic for 1 min, add the cream and parmesan, and let it thicken for 3 min.","timer":{"label":"Cooking","min":3}},{"text":"Put the prawns back in and sprinkle with parsley.","timer":null}],"variant":"Creamy","change":"A creamy garlic sauce, to serve with pasta."},{"title":"Prawn curry","intro":"Prawns in a mild coconut curry.","minutes":20,"calories":380,"difficulty":"Facile","imageSearch":"shrimp coconut curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"Indian-inspired dish","serves":4,"items":[{"name":"raw prawn","plural":"raw prawns","qty":500,"unit":"g","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":200,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion, ginger and curry powder in the oil for 3 min.","timer":{"label":"Cooking","min":3}},{"text":"Add the tomatoes and coconut milk, and cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Add the prawns and cook for 4 min.","timer":{"label":"Cooking","min":4}}],"variant":"Curry","change":"A coconut curry sauce, to serve with rice."}]$r$::jsonb, 'claude')
