insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:brandade de morue', 'Brandade', array['en:brandade', 'en:salt cod brandade']::text[], 'dish', $r$[{"title":"Salt cod brandade","intro":"Salt cod mixed into a garlic and olive oil mash, then browned in the oven.","minutes":60,"calories":480,"difficulty":"Moyen","imageSearch":"brandade cod potato gratin","veg":false,"oven":true,"cold":false,"missing":"","origin":"Speciality from Nîmes","serves":4,"items":[{"name":"salt cod","plural":"salt cod","qty":500,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":700,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":30,"unit":"cl","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":8,"unit":"cl","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":2,"unit":"tbsp","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"The day before, soak the cod in cold water, changing the water 3 times.","timer":null},{"text":"Poach the cod for 10 min in the milk, then flake it.","timer":{"label":"Cooking","min":10}},{"text":"Boil the potatoes for 20 min and mash them.","timer":{"label":"Cooking","min":20}},{"text":"Mix the mash, cod, chopped garlic, oil and a little of the cooking milk. Add pepper.","timer":null},{"text":"Pour into a dish, sprinkle with breadcrumbs and bake for 20 min at 200 °C.","timer":{"label":"Oven","min":20}}],"variant":"The classic","change":""},{"title":"Quick cod brandade","intro":"Brandade without waiting a day, made with fresh cod.","minutes":45,"calories":420,"difficulty":"Facile","imageSearch":"quick cod potato brandade","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cod loin","plural":"cod loins","qty":500,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":700,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":30,"unit":"cl","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":6,"unit":"cl","have":false},{"name":"grated emmental","plural":"grated emmental","qty":40,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Poach the cod for 8 min in the milk, then crumble it.","timer":{"label":"Cooking","min":8}},{"text":"Mash the potatoes with the fish, garlic, oil and a little milk. Add salt and pepper.","timer":null},{"text":"Pour into a dish, sprinkle with emmental and bake for 15 min at 200 °C.","timer":{"label":"Oven","min":15}}],"variant":"Quick","change":"Fresh cod replaces the salt cod: no soaking."},{"title":"Salmon brandade","intro":"A mild salmon brandade that everyone likes.","minutes":45,"calories":500,"difficulty":"Facile","imageSearch":"salmon potato brandade","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"salmon fillet","plural":"salmon fillets","qty":3,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":700,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":25,"unit":"cl","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Poach the salmon for 8 min in the milk and flake it.","timer":{"label":"Cooking","min":8}},{"text":"Mash the potatoes with the salmon, cream and dill, then add salt and pepper.","timer":null},{"text":"Pour into a dish, sprinkle with breadcrumbs and bake for 15 min at 200 °C.","timer":{"label":"Oven","min":15}}],"kids":true,"variant":"Salmon","change":"Salmon replaces the cod."}]$r$::jsonb, 'claude')
