insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poisson en papillote', 'Fish en papillote', array['en:fish en papillote', 'en:fish parcel', 'en:salmon en papillote', 'en:cod en papillote', 'en:papillote']::text[], 'dish', $r$[{"title":"Cod and vegetable parcels","intro":"Fish steamed in its parcel, with julienned vegetables and lemon.","minutes":30,"calories":240,"difficulty":"Facile","imageSearch":"fish en papillote vegetables","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cod loin","plural":"cod loins","qty":4,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Cut the vegetables into thin matchsticks and divide them between 4 sheets of baking paper.","timer":null},{"text":"Place the fish on top and add a slice of lemon, the thyme, the oil, salt and pepper.","timer":null},{"text":"Close up the parcels and bake for 18 min.","timer":{"label":"Oven","min":18}}],"variant":"The classic","change":""},{"title":"Salmon parcels","intro":"Tender salmon in a parcel on a bed of leeks.","minutes":30,"calories":400,"difficulty":"Facile","imageSearch":"salmon en papillote leek","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"salmon fillet","plural":"salmon fillets","qty":4,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":2,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"light cream","plural":"light cream","qty":8,"unit":"cl","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Soften the sliced leeks in a pan for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Divide them between 4 parcels, add the salmon, a little cream, the dill, the lemon, salt and pepper.","timer":null},{"text":"Close up and bake for 15 min.","timer":{"label":"Oven","min":15}}],"variant":"Salmon","change":"Salmon replaces the cod, with leeks."},{"title":"Asian pollock parcels","intro":"A parcel flavoured with ginger and soy.","minutes":25,"calories":260,"difficulty":"Facile","imageSearch":"asian fish parcel ginger soy","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pollock fillet","plural":"pollock fillets","qty":4,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false},{"name":"pak choi","plural":"pak choi","qty":2,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Put the sliced pak choi on 4 sheets of paper, then the fish.","timer":null},{"text":"Drizzle with soy sauce, and add the ginger, lime and spring onion.","timer":null},{"text":"Close up and bake for 15 min.","timer":{"label":"Oven","min":15}}],"variant":"Asian-style","change":"Soy sauce, ginger and lime flavour the fish."}]$r$::jsonb, 'claude')
