insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:tartare de saumon', 'Salmon tartare', array['en:salmon tartare', 'en:fish tartare', 'en:salmon tartar']::text[], 'dish', $r$[{"title":"Salmon tartare","intro":"Raw salmon cut by hand, with lime, shallot and herbs.","minutes":20,"calories":300,"difficulty":"Facile","imageSearch":"salmon tartare","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"extra-fresh salmon fillet","plural":"extra-fresh salmon fillets","qty":3,"unit":"","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"chives","plural":"chives","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the salmon into small, even cubes.","timer":null},{"text":"Mix with the chopped shallot, chives, oil, the juice of the limes, salt and pepper.","timer":null},{"text":"Chill for 10 min before serving.","timer":{"label":"Chill","min":10}}],"variant":"The classic","change":""},{"title":"Salmon and avocado tartare","intro":"A fresh, colourful tartare of salmon, avocado and mango.","minutes":20,"calories":380,"difficulty":"Facile","imageSearch":"salmon avocado tartare","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"extra-fresh salmon fillet","plural":"extra-fresh salmon fillets","qty":3,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":2,"unit":"","have":false},{"name":"mango","plural":"mangoes","qty":1,"unit":"","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the salmon, avocado and mango into small cubes.","timer":null},{"text":"Season the salmon with the oil, half the lime juice and the salt, and the avocado with the rest of the lime.","timer":null},{"text":"Build in a ring mould: avocado, mango, then salmon, and sprinkle with coriander.","timer":null}],"variant":"With avocado","change":"A layer of avocado and mango under the salmon."},{"title":"Asian salmon tartare","intro":"A Japanese-style tartare with soy and sesame.","minutes":20,"calories":320,"difficulty":"Facile","imageSearch":"asian salmon tartare sesame","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"extra-fresh salmon fillet","plural":"extra-fresh salmon fillets","qty":3,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false},{"name":"sesame oil","plural":"sesame oil","qty":1,"unit":"tbsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tbsp","have":false},{"name":"spring onion","plural":"spring onions","qty":1,"unit":"","have":false}],"steps":[{"text":"Cut the salmon into small cubes.","timer":null},{"text":"Mix with the soy sauce, sesame oil, ginger, the lime juice and the sliced spring onion.","timer":null},{"text":"Sprinkle with sesame seeds and serve well chilled.","timer":null}],"variant":"Asian-style","change":"Seasoned with soy sauce, sesame and ginger."}]$r$::jsonb, 'claude')
