insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:dorade au four', 'Baked sea bream', array['en:baked sea bream', 'en:sea bream', 'en:dorade', 'en:baked sea bas', 'en:whole baked fish']::text[], 'dish', $r$[{"title":"Baked sea bream","intro":"A whole sea bream roasted in the oven with lemon, fennel and herbs.","minutes":40,"calories":300,"difficulty":"Facile","imageSearch":"baked sea bream","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"gutted sea bream","plural":"gutted sea breams","qty":2,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"fennel","plural":"fennel","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Put the sliced fennel in the bottom of a dish with 2 tbsp of oil.","timer":null},{"text":"Slip lemon slices, garlic and thyme inside the fish, and season with salt and pepper.","timer":null},{"text":"Lay them on the fennel, drizzle with the rest of the oil and bake for 25 min.","timer":{"label":"Oven","min":25}}],"variant":"The classic","change":""},{"title":"Baked sea bream with potatoes","intro":"A full meal: sea bream on a bed of potatoes.","minutes":55,"calories":420,"difficulty":"Facile","imageSearch":"sea bream potatoes oven","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"gutted sea bream","plural":"gutted sea breams","qty":2,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":200,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Put the thinly sliced potatoes in a dish with the oil, salt and thyme. Bake for 20 min.","timer":{"label":"Oven","min":20}},{"text":"Add the sea bream stuffed with lemon, and the cherry tomatoes.","timer":null},{"text":"Bake for another 25 min.","timer":{"label":"Oven","min":25}}],"variant":"With potatoes","change":"Potatoes cook under the fish."},{"title":"Pan-grilled sea bream","intro":"Fillets with crispy skin, in 10 minutes.","minutes":15,"calories":280,"difficulty":"Facile","imageSearch":"grilled sea bream fillet","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sea bream fillet","plural":"sea bream fillets","qty":4,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"fleur de sel","plural":"fleur de sel","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Lightly score the skin of the fillets.","timer":null},{"text":"Cook them skin-side down for 4 min in very hot oil.","timer":{"label":"Pan","min":4}},{"text":"Flip them for 1 min, then serve with the lemon and fleur de sel.","timer":{"label":"Pan","min":1}}],"variant":"Pan-grilled","change":"Sea bream fillets grilled skin-side down."}]$r$::jsonb, 'claude')
