insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:fish and chip', 'Fish and chips', array['en:fish chip', 'en:fried fish']::text[], 'dish', $r$[{"title":"Fish and chips","intro":"White fish in a crispy beer batter, with chips.","minutes":45,"calories":720,"difficulty":"Moyen","imageSearch":"fish and chips","veg":false,"oven":false,"cold":false,"missing":"","origin":"English dish","serves":4,"items":[{"name":"cod fillet","plural":"cod fillets","qty":4,"unit":"","have":false},{"name":"flour","plural":"flour","qty":150,"unit":"g","have":false},{"name":"lager","plural":"lager","qty":25,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the potatoes into chips and fry them for 6 min at 160 °C, then drain.","timer":{"label":"Frying","min":6}},{"text":"Mix the flour, baking powder, salt and cold lager.","timer":null},{"text":"Dip the fish in a little flour and then in the batter, and fry for 5 min at 180 °C.","timer":{"label":"Frying","min":5}},{"text":"Fry the chips again for 3 min at 180 °C until golden.","timer":{"label":"Frying","min":3}},{"text":"Serve with lemon.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Oven-baked fish and chips","intro":"A lighter fish and chips, all in the oven.","minutes":45,"calories":520,"difficulty":"Facile","imageSearch":"oven baked fish and chips","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cod fillet","plural":"cod fillets","qty":4,"unit":"","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"flour","plural":"flour","qty":3,"unit":"tbsp","have":false},{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 220 °C. Cut the potatoes into chips, toss with 3 tbsp of oil and some salt, and bake for 20 min.","timer":{"label":"Oven","min":20}},{"text":"Dip the fish in the flour, the beaten egg and then the breadcrumbs.","timer":null},{"text":"Put it on another tray, drizzle with oil and bake everything for 15 min.","timer":{"label":"Oven","min":15}}],"kids":true,"variant":"Oven-baked","change":"The fish is breaded and the chips are baked, with no deep-frying."},{"title":"Homemade pollock fish fingers","intro":"Homemade fish fingers, crunchy and golden.","minutes":25,"calories":420,"difficulty":"Facile","imageSearch":"homemade fish fingers","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pollock fillet","plural":"pollock fillets","qty":500,"unit":"g","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"flour","plural":"flour","qty":4,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the fish into sticks and add salt.","timer":null},{"text":"Dip them in the flour, the beaten egg and then the breadcrumbs.","timer":null},{"text":"Brown them in the oil for 3 min on each side.","timer":{"label":"Pan","min":6}},{"text":"Serve with lemon.","timer":null}],"kids":true,"variant":"Breaded","change":"Breaded pan-fried fish sticks, for kids."}]$r$::jsonb, 'claude')
