insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:steak frite', 'Steak frites', array['en:steak and chip']::text[], 'dish', $r$[{"title":"Steak frites","intro":"A steak seared to your liking with crispy homemade chips.","minutes":40,"calories":750,"difficulty":"Facile","imageSearch":"steak frites","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"beef steak","plural":"beef steaks","qty":4,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the potatoes into chips, rinse them and dry them well.","timer":null},{"text":"Fry them for 6 min at 160 °C, then drain.","timer":{"label":"Frying","min":6}},{"text":"Cook the steaks in the butter for 2 to 3 min on each side, depending on how you like them.","timer":{"label":"Pan","min":5}},{"text":"Fry the chips again for 3 min at 180 °C, add salt and serve.","timer":{"label":"Frying","min":3}}],"kids":true,"variant":"The classic","change":""},{"title":"Pepper steak","intro":"The bistro classic, with its creamy pepper sauce.","minutes":30,"calories":680,"difficulty":"Facile","imageSearch":"pepper steak sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"beef steak","plural":"beef steaks","qty":4,"unit":"","have":false},{"name":"crushed peppercorn","plural":"crushed peppercorns","qty":2,"unit":"tbsp","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"cognac","plural":"cognac","qty":3,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Coat the steaks in the crushed peppercorns.","timer":null},{"text":"Cook them in the butter for 2 to 3 min on each side. Keep warm.","timer":{"label":"Pan","min":5}},{"text":"Fry the shallot, pour in the cognac, then the cream, and let it reduce for 3 min.","timer":{"label":"Sauce","min":3}},{"text":"Add salt and pour over the steaks.","timer":null}],"variant":"Peppercorn","change":"A creamy pepper sauce coats the steak."},{"title":"Steak and oven chips","intro":"Steak and chips without a deep fryer.","minutes":45,"calories":600,"difficulty":"Facile","imageSearch":"steak oven fries","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"beef steak","plural":"beef steaks","qty":4,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 220 °C.","timer":null},{"text":"Cut the potatoes into chips, toss them with the oil, paprika and salt, and spread them on a tray.","timer":null},{"text":"Bake for 35 min, turning halfway through.","timer":{"label":"Oven","min":35}},{"text":"Cook the steaks in a pan for 2 to 3 min on each side.","timer":{"label":"Pan","min":5}}],"kids":true,"variant":"Oven chips","change":"The chips are baked in the oven with a drizzle of oil."}]$r$::jsonb, 'claude')
