insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:boeuf saute aux legume', 'Beef stir-fry', array['en:beef stir fry', 'en:beef and onion', 'en:beef with broccoli', 'en:stir fried beef']::text[], 'dish', $r$[{"title":"Beef and onion stir-fry","intro":"Strips of beef seared in a wok with onions and soy sauce.","minutes":20,"calories":480,"difficulty":"Facile","imageSearch":"beef onion stir fry","veg":false,"oven":false,"cold":false,"missing":"","origin":"Chinese dish","serves":4,"items":[{"name":"frying steak","plural":"frying steak","qty":500,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":3,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tsp","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Cut the beef into thin strips and mix with the cornflour and 1 tbsp of soy sauce.","timer":null},{"text":"Sear it for 2 min over a very high heat in the oil. Set aside.","timer":{"label":"Wok","min":2}},{"text":"Stir-fry the sliced onions and garlic for 4 min.","timer":{"label":"Wok","min":4}},{"text":"Put the beef back in with the rest of the soy sauce and the sugar for 1 min. Serve with rice.","timer":{"label":"Wok","min":1}}],"variant":"The classic","change":""},{"title":"Beef and broccoli stir-fry","intro":"The takeaway beef stir-fry, with crunchy broccoli.","minutes":20,"calories":420,"difficulty":"Facile","imageSearch":"beef broccoli stir fry","veg":false,"oven":false,"cold":false,"missing":"","origin":"Chinese dish","serves":4,"items":[{"name":"frying steak","plural":"frying steak","qty":500,"unit":"g","have":false},{"name":"broccoli","plural":"broccoli","qty":1,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Blanch the broccoli florets for 2 min.","timer":{"label":"Cooking","min":2}},{"text":"Sear the beef strips for 2 min. Set aside.","timer":{"label":"Wok","min":2}},{"text":"Stir-fry the garlic, ginger and broccoli for 3 min.","timer":{"label":"Wok","min":3}},{"text":"Put the beef back in with the soy sauce mixed with the cornflour and 5 cl of water, for 1 min.","timer":{"label":"Wok","min":1}}],"variant":"With broccoli","change":"Broccoli replaces some of the onions."},{"title":"Beef and pepper stir-fry","intro":"A colourful stir-fry of peppers and beef.","minutes":20,"calories":440,"difficulty":"Facile","imageSearch":"beef pepper stir fry","veg":false,"oven":false,"cold":false,"missing":"","origin":"Chinese dish","serves":4,"items":[{"name":"frying steak","plural":"frying steak","qty":500,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"oyster sauce","plural":"oyster sauce","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Sear the beef strips for 2 min. Set aside.","timer":{"label":"Wok","min":2}},{"text":"Stir-fry the peppers and onion for 4 min.","timer":{"label":"Wok","min":4}},{"text":"Put the beef back in with the sauces for 1 min.","timer":{"label":"Wok","min":1}}],"variant":"With peppers","change":"Colourful peppers and an oyster sauce."}]$