nit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Brown the whole tenderloins in the oil on all sides.","timer":null},{"text":"Brush them with honey, add the garlic and rosemary, and season with salt and pepper.","timer":null},{"text":"Roast for 20 min, then rest for 5 min before slicing.","timer":{"label":"Oven","min":20}}],"variant":"Honey and rosemary","change":"Roasted whole in the oven and glazed with honey."},{"title":"Pork tenderloin with mushrooms","intro":"Pork tenderloin in a creamy mushroom sauce.","minutes":30,"calories":480,"difficulty":"Facile","imageSearch":"pork tenderloin mushroom sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pork tenderloin","plural":"pork tenderloins","qty":2,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":300,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the medallions in the butter for 3 min on each side. Set aside.","timer":{"label":"Pan","min":6}},{"text":"Fry the shallot and mushrooms for 6 min.","timer":{"label":"Pan","min":6}},{"text":"Add the cream and the meat, and simmer for 6 min.","timer":{"label":"Simmer","min":6}}],"variant":"With mushrooms","change":"A mushroom sauce replaces the mustard."}]$r$::jsonb, 'claude')
