"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":20,"unit":"cl","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 150 °C.","timer":null},{"text":"Brown the shoulder in a casserole dish with the oil.","timer":null},{"text":"Add the onions, the unpeeled garlic, the thyme, the wine, salt and pepper.","timer":null},{"text":"Cover and bake for 4 h, basting from time to time.","timer":{"label":"Oven","min":240}}],"variant":"Slow-cooked","change":"A shoulder cooked slowly for 4 h, so the meat falls apart."},{"title":"Lamb navarin","intro":"The lamb stew with carrots, turnips and peas.","minutes":120,"calories":580,"difficulty":"Moyen","imageSearch":"lamb navarin stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"diced lamb shoulder","plural":"diced lamb shoulder","qty":1000,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":4,"unit":"","have":false},{"name":"turnip","plural":"turnips","qty":4,"unit":"","have":false},{"name":"pea","plural":"peas","qty":200,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":6,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":200,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"bouquet garni","plural":"bouquet garni","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the lamb in the oil with the onions, and sprinkle with flour.","timer":null},{"text":"Add the to