insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:cordon bleu', 'Cordon bleu', array['en:homemade cordon bleu', 'en:chicken cordon bleu']::text[], 'dish', $r$[{"title":"Homemade cordon bleu","intro":"A turkey escalope stuffed with ham and cheese, breaded and golden.","minutes":30,"calories":520,"difficulty":"Facile","imageSearch":"homemade cordon bleu","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"turkey escalope","plural":"turkey escalopes","qty":4,"unit":"","have":false},{"name":"ham","plural":"ham","qty":4,"unit":"slices","have":false},{"name":"emmental","plural":"emmental","qty":4,"unit":"slices","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"flour","plural":"flour","qty":4,"unit":"tbsp","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":100,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Flatten the escalopes and slice them in half through the thickness without cutting all the way.","timer":null},{"text":"Fill with ham and emmental, then close.","timer":null},{"text":"Dip them in the flour, the beaten egg and then the breadcrumbs.","timer":null},{"text":"Brown them in the oil for 5 min on each side.","timer":{"label":"Pan","min":10}}],"kids":true,"variant":"The classic","change":""},{"title":"Oven-baked cordon bleu","intro":"Lighter cordon bleus, baked in the oven.","minutes":35,"calories":440,"difficulty":"Facile","imageSearch":"baked cordon bleu","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"turkey escalope","plural":"turkey escalopes","qty":4,"unit":"","have":false},{"name":"ham","plural":"ham","qty":4,"unit":"slices","have":false},{"name":"emmental","plural":"emmental","qty":4,"unit":"slices","have":false},{"name":"egg","plural":"eggs","qty