insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:escalope milanaise', 'Veal escalope', array['en:veal escalope', 'en:schnitzel', 'en:breaded escalope']::text[], 'dish', $r$[{"title":"Veal escalope milanese","intro":"A breaded, golden veal escalope, served with lemon and tomato spaghetti.","minutes":30,"calories":560,"difficulty":"Facile","imageSearch":"veal milanese cutlet","veg":false,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"veal escalope","plural":"veal escalopes","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":100,"unit":"g","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":40,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":4,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Flatten the escalopes.","timer":null},{"text":"Mix the breadcrumbs and parmesan.","timer":null},{"text":"Dip the escalopes in the flour, the beaten egg and then the breadcrumbs.","timer":null},{"text":"Brown them in the butter for 3 min on each side and serve with lemon.","timer":{"label":"Pan","min":6}}],"kids":true,"variant":"The classic","change":""},{"title":"Breaded chicken escalope","intro":"The breaded chicken escalope, crunchy and good value.","minutes":25,"calories":480,"difficulty":"Facile","imageSearch":"breaded chicken cutlet","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":100,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":4,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Slice the breasts in half through the thickness and flatten them.","timer":null},{"text":"Coat them: flour, egg, breadcrumbs.","timer":null},{"text":"Brown them for 4 min on each side.","timer":{"label":"Pan","min":8}}],"kids":true,"variant":"Chicken","change":"Chicken replaces the veal."},{"title":"Creamy veal escalope","intro":"The Normandy-style escalope, with cream and mushrooms.","minutes":25,"calories":520,"difficulty":"Facile","imageSearch":"veal escalope cream mushroom","veg":false,"oven":false,"cold":false,"missing":"","origin":"Norman speciality","serves":4,"items":[{"name":"veal escalope","plural":"veal escalopes","qty":4,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":200,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Lightly flour the escalopes and brown them in the butter for 2 min on each side. Set aside.","timer":{"label":"Pan","min":4}},{"text":"Fry the mushrooms for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Add the cream, salt and pepper, put the escalopes back and simmer for 3 min.","timer":{"label":"Simmer","min":3}}],"variant":"Creamy","change":"A pan-fried escalope coated in a creamy mushroom sauce."}]$r$::jsonb, 'claude')
