insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:petit sale aux lentille', 'Petit salé with lentils', array['en:petit sale with lentil', 'en:petit sale', 'en:sausage and lentil', 'en:lentil and sausage']::text[], 'dish', $r$[{"title":"Petit salé with lentils","intro":"Salted pork and sausages simmered with green lentils and carrots.","minutes":90,"calories":680,"difficulty":"Facile","imageSearch":"pork lentils stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"salted pork","plural":"salted pork","qty":800,"unit":"g","have":false},{"name":"morteau sausage","plural":"Morteau sausages","qty":1,"unit":"","have":false},{"name":"green lentil","plural":"green lentils","qty":400,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"clove","plural":"cloves","qty":2,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquet garni","qty":1,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Soak the salted pork for 1 h in cold water, or blanch it for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Put it in a casserole dish with the onion studded with the cloves and the bouquet garni, cover with water and cook for 45 min.","timer":{"label":"Cooking","min":45}},{"text":"Add the lentils, the sliced carrots and the pricked sausage, and cook for 30 min.","timer":{"label":"Cooking","min":30}},{"text":"Season with pepper and serve piping hot.","timer":null}],"variant":"The classic","change":""},{"title":"Sausages and lentils","intro":"Lentils simmered with smoked sausages.","minutes":45,"calories":620,"difficulty":"Facile","imageSearch":"sausages lentils","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"smoked sausage","plural":"smoked sausages","qty":4,"unit":"","have":false},{"name":"green lentil","plural":"green lentils","qty":300,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":100,"unit":"g","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":1,"unit":"","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the bacon lardons and onion in a casserole dish.","timer":null},{"text":"Add the lentils, carrots, stock cube, thyme and 80 cl of water.","timer":null},{"text":"Add the sausages and cook for 30 min.","timer":{"label":"Cooking","min":30}}],"kids":true,"variant":"With sausages","change":"Just sausages, so it is quicker."},{"title":"Vegetarian stewed lentils","intro":"Soft lentils with vegetables, smoked with paprika.","minutes":40,"calories":380,"difficulty":"Facile","imageSearch":"vegetarian lentil stew","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"green lentil","plural":"green lentils","qty":300,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":200,"unit":"g","have":false},{"name":"smoked paprika","plural":"smoked paprika","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion, leek and carrots in the oil for 5 min.","timer":{"label":"Cooking","min":5}},{"text":"Add the lentils, tomatoes, paprika and 80 cl of water.","timer":null},{"text":"Simmer for 30 min and add salt at the end.","timer":{"label":"Simmer","min":30}}],"variant":"Vegetarian","change":"No meat, with more vegetables and smoked paprika."}]$r$::jsonb, 'claude')
