insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:kebab maison', 'Homemade kebab', array['en:homemade kebab', 'en:kebab', 'en:doner kebab', 'en:gyro']::text[], 'dish', $r$[{"title":"Homemade chicken kebab","intro":"Spice-marinated chicken, grilled and stuffed into a pitta with salad and white sauce.","minutes":35,"calories":620,"difficulty":"Facile","imageSearch":"chicken kebab pita","veg":false,"oven":false,"cold":false,"missing":"","origin":"Turkish dish","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":6,"unit":"","have":false},{"name":"pitta bread","plural":"pitta breads","qty":4,"unit":"","have":false},{"name":"greek yogurt","plural":"greek yogurts","qty":2,"unit":"","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false},{"name":"lettuce","plural":"lettuce","qty":4,"unit":"leaves","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix one yogurt with the spices, garlic, lemon juice and salt, and marinate the chicken for 15 min.","timer":{"label":"Marinade","min":15}},{"text":"Grill the chicken in the oil for 10 min, then cut it into thin strips.","timer":{"label":"Pan","min":10}},{"text":"Mix the other yogurt with a little garlic and salt for the white sauce.","timer":null},{"text":"Fill the warm pittas with chicken, lettuce, tomato, onion and sauce.","timer":null}],"kids":true,"makes":{"n":4,"one":"pita","many":"pitas"},"variant":"The classic","change":""},{"title":"Gyros","intro":"The Greek sandwich, with pork and tzatziki.","minutes":35,"calories":640,"difficulty":"Facile","imageSearch":"pork gyros pita tzatziki","veg":false,"oven":false,"cold":false,"missing":"","origin":"Greek dish","serves":4,"items":[{"name":"pork shoulder","plural":"pork shoulder","qty":600,"unit":"g","have":false},{"name":"pitta bread","plural":"pitta breads","qty":4,"unit":"","have":false},{"name":"oregano","plural":"oregano","qty":1,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"greek yogurt","plural":"greek yogurts","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the pork into thin strips and mix with the oil, oregano, paprika and salt.","timer":null},{"text":"Grill it for 8 min over a high heat.","timer":{"label":"Pan","min":8}},{"text":"Grate the cucumber, squeeze it dry and mix with the yogurt and garlic.","timer":null},{"text":"Fill the pittas with meat, tomato, onion and tzatziki.","timer":null}],"makes":{"n":4,"one":"pita","many":"pitas"},"variant":"Greek gyros","change":"Pork marinated in oregano, with tzatziki."},{"title":"Vegetarian falafel kebab","intro":"The veggie kebab, with falafels and hummus.","minutes":25,"calories":560,"difficulty":"Facile","imageSearch":"falafel pita","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"falafel","plural":"falafels","qty":16,"unit":"","have":false},{"name":"pitta bread","plural":"pitta breads","qty":4,"unit":"","have":false},{"name":"hummus","plural":"hummus","qty":4,"unit":"tbsp","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"lettuce","plural":"lettuce","qty":4,"unit":"leaves","have":false},{"name":"greek yogurt","plural":"greek yogurts","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false}],"steps":[{"text":"Reheat the falafels for 10 min in the oven.","timer":{"label":"Oven","min":10}},{"text":"Mix the yogurt with the lemon juice.","timer":null},{"text":"Spread the pittas with hummus and fill with vegetables, falafels and sauce.","timer":null}],"makes":{"n":4,"one":"pita","many":"pitas"},"variant":"Vegetarian","change":"Falafels replace the meat."}]$r$::jsonb, 'claude')
