insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poulet pane', 'Breaded chicken', array['en:breaded chicken', 'en:chicken nugget', 'en:homemade nugget', 'en:chicken tender']::text[], 'dish', $r$[{"title":"Homemade chicken nuggets","intro":"Crispy breaded chicken pieces, far better than shop-bought ones.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"homemade chicken nuggets","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":100,"unit":"g","have":false},{"name":"cornflake","plural":"cornflakes","qty":50,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"flour","plural":"flour","qty":4,"unit":"tbsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the chicken into pieces.","timer":null},{"text":"Crush the cornflakes and mix them with the breadcrumbs and paprika.","timer":null},{"text":"Dip the chicken in the salted flour, the beaten egg and then the crumb mix.","timer":null},{"text":"Brown them in the oil for 3 min on each side.","timer":{"label":"Pan","min":6}}],"kids":true,"makes":{"n":24,"one":"nugget","many":"nuggets"},"variant":"The classic","change":""},{"title":"Oven-baked chicken nuggets","intro":"Lighter nuggets, with no frying.","minutes":30,"calories":360,"difficulty":"Facile","imageSearch":"baked chicken nuggets","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":30,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 210 °C.","timer":null},{"text":"Cut the chicken into pieces, dip them in the beaten egg and then in the breadcrumbs mixed with the parmesan.","timer":null},{"text":"Spread them on a tray, drizzle with oil and bake for 18 min, turning them over.","timer":{"label":"Oven","min":18}}],"kids":true,"makes":{"n":24,"one":"nugget","many":"nuggets"},"variant":"Oven-baked","change":"Baked in the oven with a drizzle of oil."},{"title":"Spicy chicken tenders","intro":"Crunchy, spicy chicken strips, fast-food style.","minutes":25,"calories":480,"difficulty":"Facile","imageSearch":"spicy chicken tenders","veg":false,"oven":false,"cold":false,"missing":"","origin":"American dish","serves":4,"items":[{"name":"chicken mini fillet","plural":"chicken mini fillets","qty":600,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":80,"unit":"g","have":false},{"name":"smoked paprika","plural":"smoked paprika","qty":1,"unit":"tsp","have":false},{"name":"chilli powder","plural":"chilli powder","qty":0.5,"unit":"tsp","have":false},{"name":"garlic powder","plural":"garlic powder","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":5,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the flour with the spices and salt.","timer":null},{"text":"Dip the chicken strips in the flour, the egg and then the breadcrumbs.","timer":null},{"text":"Brown them in the oil for 3 min on each side.","timer":{"label":"Pan","min":6}}],"variant":"Spicy","change":"The coating is spiced up with chilli and garlic."}]$r$::jsonb, 'claude')
