insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:omelette', 'Omelette', array['en:mushroom omelette', 'en:cheese omelette', 'en:plain omelette']::text[], 'dish', $r$[{"title":"French omelette with herbs","intro":"A soft, runny omelette with fresh herbs.","minutes":10,"calories":260,"difficulty":"Facile","imageSearch":"french omelette herbs","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":8,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"chive","plural":"chives","qty":null,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Beat the eggs with the chopped herbs, salt and pepper.","timer":null},{"text":"Melt the butter in a frying pan over a medium heat.","timer":null},{"text":"Pour in the eggs and push the edges towards the centre with a spatula for 2 min.","timer":{"label":"Pan","min":2}},{"text":"Fold the omelette while the top is still runny.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Mushroom and cheese omelette","intro":"A filled omelette, perfect for a quick dinner.","minutes":15,"calories":340,"difficulty":"Facile","imageSearch":"mushroom cheese omelette","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":8,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":200,"unit":"g","have":false},{"name":"grated gruyère","plural":"grated gruyère","qty":60,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the sliced mushrooms in the butter until golden, about 5 min.","timer":{"label":"Pan","min":5}},{"text":"Pour in the beaten eggs, seasoned with salt and pepper.","timer":null},{"text":"Add the gruyère and cook for 3 min, then fold the omelette.","timer":{"label":"Pan","min":3}}],"kids":true,"variant":"Mushroom and cheese","change":"Fried mushrooms and gruyère."},{"title":"Spanish omelette","intro":"The Spanish tortilla, thick and soft.","minutes":40,"calories":380,"difficulty":"Facile","imageSearch":"spanish tortilla potato omelette","veg":true,"oven":false,"cold":true,"missing":"","origin":"Spanish dish","serves":4,"items":[{"name":"egg","plural":"eggs","qty":6,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":10,"unit":"cl","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the potatoes into thin slices and the onion into rings.","timer":null},{"text":"Cook them gently in the oil for 20 min without browning, then drain.","timer":{"label":"Pan","min":20}},{"text":"Mix with the beaten eggs and the salt.","timer":null},{"text":"Pour into an oiled frying pan and cook for 5 min, flip onto a plate and cook for another 4 min.","timer":{"label":"Pan","min":9}}],"kids":true,"variant":"Tortilla","change":"Soft potatoes and onions, cooked on both sides."}]$r$::jsonb, 'claude')
