insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:oeuf brouille', 'Scrambled eggs', array['en:scrambled egg', 'en:creamy scrambled egg']::text[], 'dish', $r$[{"title":"Creamy scrambled eggs","intro":"Gently scrambled eggs, creamy and soft.","minutes":10,"calories":240,"difficulty":"Facile","imageSearch":"creamy scrambled eggs","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":8,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":2,"unit":"tbsp","have":false},{"name":"chive","plural":"chives","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Lightly beat the eggs.","timer":null},{"text":"Cook them over a low heat with the butter, stirring all the time, for 4 min.","timer":{"label":"Pan","min":4}},{"text":"Take off the heat while they are still a little runny and add the cream, salt, pepper and chives.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Scrambled eggs with smoked salmon","intro":"The smart brunch: scrambled eggs and smoked salmon.","minutes":10,"calories":320,"difficulty":"Facile","imageSearch":"scrambled eggs smoked salmon toast","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":8,"unit":"","have":false},{"name":"smoked salmon","plural":"smoked salmon","qty":120,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false},{"name":"country bread","plural":"country bread","qty":4,"unit":"slices","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Toast the bread.","timer":null},{"text":"Scramble the eggs over a low heat with the butter for 4 min.","timer":{"label":"Pan","min":4}},{"text":"Serve on the bread with the salmon in strips and the dill.","timer":null}],"variant":"With smoked salmon","change":"Smoked salmon and dill, on toast."},{"title":"Mexican scrambled eggs","intro":"Huevos a la mexicana, colourful and a little spicy.","minutes":15,"calories":300,"difficulty":"Facile","imageSearch":"mexican scrambled eggs","veg":true,"oven":false,"cold":false,"missing":"","origin":"Mexican dish","serves":4,"items":[{"name":"egg","plural":"eggs","qty":8,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"green chilli","plural":"green chillies","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"tortilla","plural":"tortillas","qty":4,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the diced onion, tomato and chilli in the oil for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Add the beaten eggs and stir gently for 3 min.","timer":{"label":"Pan","min":3}},{"text":"Add salt and serve with warm tortillas.","timer":null}],"variant":"Mexican style","change":"Tomato, onion and chilli, served with tortillas."}]$r$::jsonb, 'claude')
