insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:buddha bowl', 'Buddha bowl', array['en:vegetarian bowl', 'en:grain bowl', 'en:bowl']::text[], 'dish', $r$[{"title":"Buddha bowl","intro":"A colourful, filling bowl: quinoa, roasted chickpeas, vegetables, avocado and tahini sauce.","minutes":35,"calories":560,"difficulty":"Facile","imageSearch":"buddha bowl","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"chickpea","plural":"chickpeas","qty":250,"unit":"g","have":false},{"name":"sweet potato","plural":"sweet potatoes","qty":1,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"red cabbage","plural":"red cabbages","qty":0.25,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"tahini","plural":"tahini","qty":3,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Put the diced sweet potato and the chickpeas on a baking tray with the oil, paprika and salt. Bake for 25 min.","timer":{"label":"Oven","min":25}},{"text":"Cook the quinoa for 12 min.","timer":{"label":"Cooking","min":12}},{"text":"Mix the tahini, the lemon juice and a little water to make the sauce.","timer":null},{"text":"Build the bowls with the quinoa, grated vegetables, avocado, chickpeas and sweet potato, then add the sauce.","timer":null}],"variant":"The classic","change":""},{"title":"Chicken buddha bowl","intro":"A filling, high-protein bowl with chicken.","minutes":30,"calories":580,"difficulty":"Facile","imageSearch":"chicken buddha bowl","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"brown rice","plural":"brown rice","qty":200,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"broccoli","plural":"broccoli","qty":1,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"edamame","plural":"edamame","qty":100,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":25}},{"text":"Grill the sliced chicken for 10 min.","timer":{"label":"Pan","min":10}},{"text":"Steam the broccoli for 6 min.","timer":{"label":"Steam","min":6}},{"text":"Build the bowls and drizzle with soy sauce and sesame seeds.","timer":null}],"variant":"With chicken","change":"Grilled chicken replaces the chickpeas."},{"title":"Salmon buddha bowl","intro":"A fresh bowl with salmon, avocado and cucumber.","minutes":30,"calories":600,"difficulty":"Facile","imageSearch":"salmon buddha bowl","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"rice","plural":"rice","qty":200,"unit":"g","have":false},{"name":"salmon fillet","plural":"salmon fillets","qty":2,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"edamame","plural":"edamame","qty":100,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Pan-