insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:courgette farcie', 'Stuffed courgettes', array['en:stuffed courgette', 'en:stuffed zucchini']::text[], 'dish', $r$[{"title":"Meat-stuffed courgettes","intro":"Courgettes filled with seasoned minced meat and browned with cheese.","minutes":50,"calories":420,"difficulty":"Facile","imageSearch":"stuffed zucchini meat","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"minced beef","plural":"minced beef","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":200,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":60,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cut the courgettes in half and scoop them out.","timer":null},{"text":"Fry the onion, garlic, chopped courgette flesh and meat for 8 min, then add the tomatoes.","timer":{"label":"Pan","min":8}},{"text":"Fill the courgettes and sprinkle with emmental.","timer":null},{"text":"Bake for 30 min.","timer":{"label":"Oven","min":30}}],"kids":true,"variant":"The classic","change":""},{"title":"Goat's cheese stuffed courgettes","intro":"Soft courgettes with goat's cheese and thyme.","minutes":45,"calories":320,"difficulty":"Facile","imageSearch":"zucchini stuffed goat cheese","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"fresh goat's cheese","plural":"fresh goat's cheeses","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":3,"unit":"tbsp","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cut the courgettes in half and scoop them out.","timer":null},{"text":"Mix the chopped flesh with the goat's cheese, egg, thyme, salt and pepper.","timer":null},{"text":"Fill the courgettes, sprinkle with breadcrumbs and drizzle with oil.","timer":null},{"text":"Bake for 30 min.","timer":{"label":"Oven","min":30}}],"variant":"With goat's cheese","change":"A goat's cheese and herb stuffing, vegetarian."},{"title":"Tuna stuffed courgettes","intro":"Budget-friendly stuffed courgettes with tuna.","minutes":45,"calories":340,"difficulty":"Facile","imageSearch":"zucchini stuffed tuna","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"tuna in water","plural":"tuna in water","qty":200,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"grated emmental","plural":"grated emmental","qty":50,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cut the courgettes in half and scoop them out.","timer":null},{"text":"Mix the chopped flesh, the tuna, the diced tomatoes and onion, and the egg.","timer":null},{"text":"Fill the courgettes and sprinkle with emmental.","timer":null},{"text":"Bake for 30 min.","timer":{"label":"Oven","min":30}}],"variant":"With tuna","change":"A tuna and tomato stuffing."}]$r$::jsonb, 'claude')
