insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:puree maison', 'Mashed potatoes', array['en:mashed potatoe', 'en:mash', 'en:mashed potato', 'en:crushed potatoe']::text[], 'dish', $r$[{"title":"Homemade mashed potatoes","intro":"A smooth, creamy mash with butter and milk.","minutes":30,"calories":280,"difficulty":"Facile","imageSearch":"mashed potatoes","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":25,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":60,"unit":"g","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Peel the potatoes and cook them for 20 min in salted water.","timer":{"label":"Cooking","min":20}},{"text":"Drain them and mash them with a potato masher.","timer":null},{"text":"Add the butter, then the hot milk little by little, stirring.","timer":null},{"text":"Add salt and pepper and a little nutmeg.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Crushed potatoes with olive oil","intro":"Rustic crushed potatoes with olive oil and chives.","minutes":30,"calories":240,"difficulty":"Facile","imageSearch":"crushed potatoes olive oil","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":6,"unit":"tbsp","have":false},{"name":"chive","plural":"chives","qty":null,"unit":"","have":false},{"name":"fleur de sel","plural":"fleur de sel","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the potatoes with their skins on for 25 min.","timer":{"label":"Cooking","min":25}},{"text":"Crush them roughly with a fork and the oil.","timer":null},{"text":"Add the chives, fleur de sel and pepper.","timer":null}],"variant":"Crushed","change":"Roughly crushed, with olive oil and herbs."},{"title":"Sweet potato mash","intro":"A sweet, colourful mash.","minutes":30,"calories":250,"difficulty":"Facile","imageSearch":"sweet potato mash","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sweet potato","plural":"sweet potatoes","qty":600,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":400,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":15,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the peeled vegetables for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Mash them with the butter and hot milk.","timer":null},{"text":"Add salt.","timer":null}],"kids":true,"variant":"Sweet potato","change":"Half sweet potato for an orange mash."}]$r$::jsonb, 'claude')
