insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pizza', 'Pizza', array['en:homemade pizza', 'en:pizza margherita', 'en:pizza dough']::text[], 'dish', $r$[{"title":"Homemade pizza margherita","intro":"Homemade dough, tomato sauce, mozzarella and basil.","minutes":100,"calories":620,"difficulty":"Moyen","imageSearch":"pizza margherita","veg":true,"oven":true,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"flour","plural":"flour","qty":300,"unit":"g","have":false},{"name":"baker's yeast","plural":"baker's yeast","qty":7,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"passata","plural":"passata","qty":20,"unit":"cl","have":false},{"name":"mozzarella","plural":"mozzarella","qty":2,"unit":"","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"oregano","plural":"oregano","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the flour, yeast, 1 tsp of salt, 2 tbsp of oil and 18 cl of warm water. Knead for 5 min.","timer":null},{"text":"Leave to rise for 1 h under a tea towel.","timer":{"label":"Rise","min":60}},{"text":"Preheat the oven to 250 °C. Roll the dough out thinly on an oiled baking tray.","timer":null},{"text":"Spread on the passata seasoned with oregano and add the torn mozzarella.","timer":null},{"text":"Bake for 12 min, then add the basil.","timer":{"label":"Oven","min":12}}],"kids":true,"makes":{"n":2,"one":"pizza","many":"pizzas"},"variant":"The classic","change":""},{"title":"Ham and mushroom pizza","intro":"The ham and mushroom pizza, a favourite with kids.","minutes":100,"calories":680,"difficulty":"Moyen","imageSearch":"ham mushroom pizza","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":300,"unit":"g","have":false},{"name":"baker's yeast","plural":"baker's yeast","qty":7,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"passata","plural":"passata","qty":20,"unit":"cl","have":false},{"name":"mozzarella","plural":"mozzarella","qty":2,"unit":"","have":false},{"name":"cooked ham","plural":"cooked ham","qty":3,"unit":"slices","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":150,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Make the dough and leave it to rise for 1 h.","timer":{"label":"Rise","min":60}},{"text":"Preheat the oven to 250 °C and roll out the dough.","timer":null},{"text":"Top with the passata, mozzarella, ham and sliced mushrooms.","timer":null},{"text":"Bake for 12 min.","timer":{"label":"Oven","min":12}}],"kids":true,"makes":{"n":2,"one":"pizza","many":"pizzas"},"variant":"Reine","change":"With ham and mushrooms."},{"title":"Quick no-rise pizza","intro":"A homemade pizza in 30 minutes, with no waiting for the dough to rise.","minutes":30,"calories":600,"difficulty":"Facile","imageSearch":"quick yogurt dough pizza","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"passata","plural":"passata","qty":15,"unit":"cl","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":150,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 240 °C.","timer":null},{"text":"Mix the flour, yoghurt, baking powder, oil and salt until you have a ball of dough.","timer":null},{"text":"Roll out the dough and top with the passata, mozzarella and cherry tomatoes.","timer":null},{"text":"Bake for 15 min.","timer":{"label":"Oven","min":15}}],"kids":true,"makes":{"n":1,"one":"pizza","many":"pizzas"},"variant":"Quick","change":"A yoghurt dough, with no rising time."}]$r$::jsonb, 'claude')
