insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:calzone', 'Calzone', array['en:pizza calzone']::text[], 'dish', $r$[{"title":"Calzone","intro":"A pizza folded into a turnover, filled with ham, mozzarella, mushrooms and egg.","minutes":100,"calories":700,"difficulty":"Moyen","imageSearch":"calzone","veg":false,"oven":true,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"flour","plural":"flour","qty":300,"unit":"g","have":false},{"name":"baker's yeast","plural":"baker's yeast","qty":7,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"passata","plural":"passata","qty":15,"unit":"cl","have":false},{"name":"mozzarella","plural":"mozzarella","qty":2,"unit":"","have":false},{"name":"cooked ham","plural":"cooked ham","qty":3,"unit":"slices","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Make the pizza dough and leave it to rise for 1 h.","timer":{"label":"Rise","min":60}},{"text":"Preheat the oven to 240 °C. Divide the dough into 2 discs.","timer":null},{"text":"Spread half of each disc with passata, ham, mushrooms and mozzarella, and crack in an egg.","timer":null},{"text":"Fold over and seal the edges.","timer":null},{"text":"Bake for 18 min.","timer":{"label":"Oven","min":18}}],"kids":true,"variant":"The classic","change":""},{"title":"Vegetarian calzone","intro":"A soft calzone with spinach and ricotta.","minutes":100,"calories":640,"difficulty":"Moyen","imageSearch":"spinach ricotta calzone","veg":true,"oven":true,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"flour","plural":"flour","qty":300,"unit":"g","have":false},{"name":"baker's yeast","plural":"baker's yeast","qty":7,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"spinach","plural":"spinach","qty":200,"unit":"g","have":false},{"name":"ricotta","plural":"ricotta","qty":200,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Make the dough and leave it to rise for 1 h.","timer":{"label":"Rise","min":60}},{"text":"Wilt the spinach with the garlic and mix with the ricotta.","timer":null},{"text":"Spread over half of each disc, add the mozzarella and fold over.","timer":null},{"text":"Bake for 18 min at 240 °C.","timer":{"label":"Oven","min":18}}],"variant":"Vegetarian","change":"Spinach, ricotta and mozzarella."},{"title":"Quick puff pastry turnovers","intro":"Little calzone-style turnovers, ready in 25 minutes.","minutes":25,"calories":560,"difficulty":"Facile","imageSearch":"puff pastry turnovers ham cheese","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"puff pastry","plural":"puff pastries","qty":2,"unit":"","have":false},{"name":"passata","plural":"passata","qty":10,"unit":"cl","have":false},{"name":"cooked ham","plural":"cooked ham","qty":3,"unit":"slices","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Cut out discs of pastry and top half of each with passata, ham and mozzarella.","timer":null},{"text":"Fold over, seal the edges and brush with beaten egg.","timer":null},{"text":"Bake for 18 min.","timer":{"label":"Oven","min":18}}],"kids":true,"makes":{"n":8,"one":"turnover","many":"turnovers"},"variant":"Quick","change":"With ready-made puff pastry."}]$r$::jsonb, 'claude')
