insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:focaccia', 'Focaccia', array['en:homemade focaccia', 'en:fougasse']::text[], 'dish', $r$[{"title":"Rosemary focaccia","intro":"Soft Italian bread with olive oil, rosemary and fleur de sel.","minutes":150,"calories":320,"difficulty":"Moyen","imageSearch":"rosemary focaccia","veg":true,"oven":true,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"flour","plural":"flour","qty":500,"unit":"g","have":false},{"name":"baker's yeast","plural":"baker's yeast","qty":7,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":8,"unit":"cl","have":false},{"name":"rosemary","plural":"rosemary","qty":null,"unit":"","have":false},{"name":"fleur de sel","plural":"fleur de sel","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the flour, yeast, 2 tsp of salt, 3 tbsp of oil and 35 cl of warm water. Knead for 5 min.","timer":null},{"text":"Leave to rise for 1 h 30.","timer":{"label":"Rise","min":90}},{"text":"Spread the dough in an oiled dish, press your fingers in to make dimples and drizzle with the rest of the oil.","timer":null},{"text":"Sprinkle with rosemary and fleur de sel, and leave to rise for another 20 min.","timer":{"label":"Rise","min":20}},{"text":"Bake for 25 min at 220 °C.","timer":{"label":"Oven","min":25}}],"variant":"The classic","change":""},{"title":"Cherry tomato and olive focaccia","intro":"A colourful focaccia with tomatoes and olives.","minutes":150,"calories":340,"difficulty":"Moyen","imageSearch":"tomato olive focaccia","veg":true,"oven":true,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"flour","plural":"flour","qty":500,"unit":"g","have":false},{"name":"baker's yeast","plural":"baker's yeast","qty":7,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":8,"unit":"cl","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":200,"unit":"g","have":false},{"name":"black olive","plural":"black olives","qty":60,"unit":"g","have":false},{"name":"oregano","plural":"oregano","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Make the dough and leave it to rise for 1 h 30.","timer":{"label":"Rise","min":90}},{"text":"Spread it in an oiled dish and press in the tomatoes and olives.","timer":null},{"text":"Drizzle with oil, sprinkle with oregano and leave to rise for 20 min.","timer":{"label":"Rise","min":20}},{"text":"Bake for 25 min at 220 °C.","timer":{"label":"Oven","min":25}}],"variant":"Tomatoes and olives","change":"Topped with cherry tomatoes and olives."},{"title":"Bacon fougasse","intro":"A golden fougasse with bacon, for nibbles.","minutes":120,"calories":360,"difficulty":"Moyen","imageSearch":"bacon fougasse bread","veg":false,"oven":true,"cold":false,"missing":"","origin":"Provençal speciality","serves":4,"items":[{"name":"flour","plural":"flour","qty":500,"unit":"g","have":false},{"name":"baker's yeast","plural":"baker's yeast","qty":7,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":150,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the bacon lardons for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Mix the flour, yeast, salt, oil, 30 cl of warm water and the bacon lardons. Knead.","timer":null},{"text":"Leave to rise for 1 h.","timer":{"label":"Rise","min":60}},{"text":"Shape into a leaf, cut slits and bake for 20 min at 220 °C.","timer":{"label":"Oven","min":20}}],"variant":"Fougasse","change":"The Provençal fougasse with bacon."}]$r$::jsonb, 'claude')
