insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:bruschetta', 'Bruschetta', array['en:tomato toast']::text[], 'dish', $r$[{"title":"Tomato and basil bruschetta","intro":"Toasted bread rubbed with garlic, topped with fresh tomatoes and basil.","minutes":15,"calories":220,"difficulty":"Facile","imageSearch":"tomato bruschetta","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"country bread","plural":"country bread","qty":8,"unit":"slices","have":false},{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the tomatoes into small dice and mix with the basil, 3 tbsp of oil, salt and pepper.","timer":null},{"text":"Toast the bread and rub it with the garlic.","timer":null},{"text":"Top with the tomatoes and drizzle with a little oil.","timer":null}],"makes":{"n":8,"one":"bruschetta","many":"bruschettas"},"variant":"The classic","change":""},{"title":"Mozzarella and cured ham bruschetta","intro":"Tasty Italian toasts.","minutes":15,"calories":320,"difficulty":"Facile","imageSearch":"bruschetta prosciutto mozzarella","veg":false,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"country bread","plural":"country bread","qty":8,"unit":"slices","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"cured ham","plural":"cured ham","qty":4,"unit":"slices","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":150,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false}],"steps":[{"text":"Toast the bread.","timer":null},{"text":"Top with mozzarella, halved cherry tomatoes and cured ham.","timer":null},{"text":"Drizzle with oil and add the basil.","timer":null}],"makes":{"n":8,"one":"bruschetta","many":"bruschettas"},"variant":"Mozzarella and cured ham","change":"Mozzarella and cured ham on toasted bread."},{"title":"Avocado and egg bruschetta","intro":"Avocado and egg toasts, perfect for brunch.","minutes":20,"calories":320,"difficulty":"Facile","imageSearch":"avocado egg toast","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"country bread","plural":"country bread","qty":4,"unit":"slices","have":false},{"name":"avocado","plural":"avocados","qty":2,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false},{"name":"piment d'espelette","plural":"piment d'espelette","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Toast the bread.","timer":null},{"text":"Mash the avocados with the lemon juice and the salt.","timer":null},{"text":"Poach the eggs for 3 min in simmering water with a splash of vinegar.","timer":{"label":"Cooking","min":3}},{"text":"Spread on the avocado, add the egg and sprinkle with chilli.","timer":null}],"makes":{"n":4,"one":"bruschetta","many":"bruschettas"},"variant":"Avocado and egg","change":"A brunch version, with mashed avocado and a poached egg."}]$r$::jsonb, 'claude')
