"unit":"","have":false}],"steps":[{"text":"Toast the bread and spread it with avocado mashed with lemon.","timer":null},{"text":"Poach the eggs for 3 min in simmering water with the vinegar.","timer":{"label":"Cooking","min":3}},{"text":"Put an egg on each slice, then add salt and pepper.","timer":null}],"makes":{"n":4,"one":"open sandwich","many":"open sandwiches"},"variant":"With an egg","change":"A poached egg on the avocado."},{"title":"Smoked salmon avocado toast","intro":"The smart avocado toast, with smoked salmon.","minutes":10,"calories":340,"difficulty":"Facile","imageSearch":"avocado toast smoked salmon","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"wholemeal bread","plural":"wholemeal bread","qty":4,"unit":"slices","have":false},{"name":"avocado","plural":"avocados","qty":2,"unit":"","have":false},{"name":"smoked salmon","plural":"smoked salmon","qty":100,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Toast the bread.","timer":null},{"text":"Mash the avocados with the lemon juice and spread them on the bread.","timer":null},{"text":"Add the smoked salmon and dill, then pepper.","timer":null}],"makes":{"n":4,"one":"open sandwich","many":"open sandwiches"},"variant":"With smoked salmon","change":"Smoked salmon and dill."}]$r$::jsonb, 'claude')
