insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:madeleine', 'Madeleines', array['en:homemade madeleine']::text[], 'dish', $r$[{"title":"Madeleines","intro":"Little golden madeleines with their characteristic bump, flavoured with butter and lemon.","minutes":80,"calories":110,"difficulty":"Facile","imageSearch":"french madeleines","veg":true,"oven":true,"cold":false,"missing":"","origin":"Speciality of Lorraine","serves":4,"items":[{"name":"flour","plural":"flour","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":130,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":120,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Whisk the eggs and sugar until the mixture turns pale.","timer":null},{"text":"Add the lemon zest, flour, baking powder and a pinch of salt, then the melted butter.","timer":null},{"text":"Chill the batter for 1 h. This is the secret of the bump.","timer":{"label":"Rest","min":60}},{"text":"Preheat the oven to 220 °C. Fill the buttered moulds three-quarters full.","timer":null},{"text":"Bake for 5 min, turn the oven down to 180 °C and bake for another 5 min.","timer":{"label":"Oven","min":10}}],"kids":true,"dessert":true,"makes":{"n":24,"one":"madeleine","many":"madeleines"},"variant":"The classic","change":""},{"title":"Chocolate madeleines","intro":"Cocoa madeleines, with a chocolate shell at the bottom of the mould.","minutes":90,"calories":140,"difficulty":"Moyen","imageSearch":"chocolate madeleines","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":130,"unit":"g","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":20,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":120,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":100,"unit":"g","have":false}],"steps":[{"text":"Whisk the eggs and sugar, then add the flour, cocoa, baking powder and melted butter.","timer":null},{"text":"Chill for 1 h.","timer":{"label":"Rest","min":60}},{"text":"Preheat the oven to 220 °C. Fill the buttered moulds and bake for 5 min, then 5 min at 180 °C.","timer":{"label":"Oven","min":10}},{"text":"Melt the chocolate, pour a little into each clean mould and set the madeleines on top.","timer":null},{"text":"Leave to set in the fridge for 20 min before turning out.","timer":{"label":"Rest","min":20}}],"kids":true,"dessert":true,"makes":{"n":24,"one":"madeleine","many":"madeleines"},"variant":"Chocolate","change":"With cocoa in the batter and a chocolate base."},{"title":"Honey madeleines","intro":"Softer madeleines with a lovely honey flavour.","minutes":80,"calories":115,"difficulty":"Facile","imageSearch":"honey madeleines","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":90,"unit":"g","have":false},{"name":"honey","plural":"honey","qty":40,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":120,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Whisk the eggs and sugar, then add the honey.","timer":null},{"text":"Add the flour and baking powder, then the lukewarm melted butter.","timer":null},{"text":"Chill for 1 h.","timer":{"label":"Rest","min":60}},{"text":"Preheat the oven to 220 °C, fill the buttered moulds and bake for 5 min, then 5 min at 180 °C.","timer":{"label":"Oven","min":10}}],"kids":true,"dessert":true,"makes":{"n":24,"one":"madeleine","many":"madeleines"},"variant":"With honey","change":"Some of the sugar is replaced with honey."}]$r$::jsonb, 'claude')
