insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:quatre quart', 'Pound cake', array['en:pound cake', 'en:breton cake']::text[], 'dish', $r$[{"title":"Quatre-quarts pound cake","intro":"The Breton cake made with four ingredients in equal weights: eggs, sugar, flour and butter.","minutes":60,"calories":330,"difficulty":"Facile","imageSearch":"pound cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"Breton speciality","serves":4,"items":[{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":200,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":200,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C and butter a loaf tin.","timer":null},{"text":"Whisk the eggs and sugar until pale.","timer":null},{"text":"Add the flour, baking powder and a pinch of salt, then the melted butter.","timer":null},{"text":"Pour into the tin and bake for 40 min. A knife blade should come out dry.","timer":{"label":"Oven","min":40}}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Apple pound cake","intro":"A soft pound cake with pieces of tender apple.","minutes":70,"calories":320,"difficulty":"Facile","imageSearch":"apple pound cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":150,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":150,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"apple","plural":"apples","qty":3,"unit":"","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Peel and dice the apples.","timer":null},{"text":"Whisk the eggs and sugar, add the flour, baking powder and cinnamon, then the melted butter.","timer":null},{"text":"Fold in the apples and pour into a buttered tin.","timer":null},{"text":"Bake for 45 min.","timer":{"label":"Oven","min":45}}],"kids":true,"dessert":true,"variant":"With apples","change":"With diced apples in the batter."},{"title":"Orange pound cake","intro":"A very gentle pound cake with an orange scent.","minutes":60,"calories":330,"difficulty":"Facile","imageSearch":"orange pound cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":200,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":180,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Whisk the eggs and sugar, then add the orange zest and juice.","timer":null},{"text":"Add the flour and baking powder, then the melted butter.","timer":null},{"text":"Pour into a buttered loaf tin and bake for 40 min.","timer":{"label":"Oven","min":40}}],"kids":true,"dessert":true,"variant":"Orange","change":"Flavoured with orange zest and juice."}]$r$::jsonb, 'claude')
