insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gateau marbre', 'Marble cake', array['en:marble cake', 'en:marbled cake', 'en:chocolate and vanilla marble cake', 'en:marbre']::text[], 'dish', $r$[{"title":"Marble cake","intro":"The vanilla and chocolate loaf cake with pretty swirls, just like the one from tea time.","minutes":75,"calories":340,"difficulty":"Facile","imageSearch":"marble cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"melted butter","plural":"melted butter","qty":180,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":180,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"flour","plural":"flour","qty":220,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"milk","plural":"milk","qty":5,"unit":"cl","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":25,"unit":"g","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C and butter a loaf tin.","timer":null},{"text":"Whisk the melted butter, sugar and vanilla sugar, then add the eggs one by one.","timer":null},{"text":"Add the flour, baking powder and milk.","timer":null},{"text":"Split the batter in two and add the cocoa to one half.","timer":null},{"text":"Pour the batters into the tin in alternating layers and run a fork through to marble.","timer":null},{"text":"Bake for 45 min.","timer":{"label":"Oven","min":45}}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Yoghurt marble cake","intro":"A lighter marble cake that is just as soft.","minutes":70,"calories":260,"difficulty":"Facile","imageSearch":"marble cake slice","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":140,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"flour","plural":"flour","qty":220,"unit":"g","have":false},{"name":"sunflower oil","plural":"sunflower oil","qty":5,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":20,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix the yoghurt, sugar and eggs, then the flour, baking powder and oil.","timer":null},{"text":"Split the batter in two and add the cocoa to one half.","timer":null},{"text":"Pour in alternating layers into an oiled tin and marble with a fork.","timer":null},{"text":"Bake for 40 min.","timer":{"label":"Oven","min":40}}],"kids":true,"dessert":true,"variant":"Lighter","change":"Less butter: a yoghurt keeps it soft."},{"title":"Orange and cocoa marble cake","intro":"The chocolate and orange duo in a very simple marble cake.","minutes":75,"calories":340,"difficulty":"Facile","imageSearch":"orange chocolate marble cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"melted butter","plural":"melted butter","qty":180,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":180,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"flour","plural":"flour","qty":220,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":25,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Whisk the melted butter and sugar, add the eggs, then the flour and baking powder.","timer":null},{"text":"Split the batter: orange zest and juice in one half, cocoa in the other.","timer":null},{"text":"Pour in alternating layers into a buttered tin and marble with a fork.","timer":null},{"text":"Bake for 45 min.","timer":{"label":"Oven","min":45}}],"kids":true,"dessert":true,"variant":"Orange","change":"The pale part is flavoured with orange."}]$r$::jsonb, 'claude')
