insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:banana bread', 'Banana bread', array['en:banana cake', 'en:banana loaf']::text[], 'dish', $r$[{"title":"Banana bread","intro":"The American loaf cake made with very ripe bananas, soft and fragrant.","minutes":70,"calories":290,"difficulty":"Facile","imageSearch":"banana bread","veg":true,"oven":true,"cold":false,"missing":"","origin":"American recipe","serves":4,"items":[{"name":"banana","plural":"bananas","qty":3,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"brown sugar","plural":"brown sugar","qty":100,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":220,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mash the bananas with a fork.","timer":null},{"text":"Mix them with the eggs, sugar and melted butter.","timer":null},{"text":"Add the flour, baking powder and cinnamon without mixing too much.","timer":null},{"text":"Pour into a buttered loaf tin and bake for 50 min.","timer":{"label":"Oven","min":50}}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Chocolate chip banana bread","intro":"The indulgent banana bread, full of melting chocolate chips.","minutes":70,"calories":340,"difficulty":"Facile","imageSearch":"chocolate chip banana bread","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"banana","plural":"bananas","qty":3,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"brown sugar","plural":"brown sugar","qty":90,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":220,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"chocolate chip","plural":"chocolate chips","qty":100,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mash the bananas and mix them with the eggs, sugar and melted butter.","timer":null},{"text":"Add the flour and baking powder, then the chocolate chips.","timer":null},{"text":"Pour into a loaf tin and bake for 50 min.","timer":{"label":"Oven","min":50}}],"kids":true,"dessert":true,"variant":"Chocolate","change":"With chocolate chips."},{"title":"No added sugar banana bread","intro":"A soft, light cake sweetened only by the fruit.","minutes":70,"calories":210,"difficulty":"Facile","imageSearch":"healthy banana bread oats","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"banana","plural":"bananas","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"coconut oil","plural":"coconut oil","qty":4,"unit":"tbsp","have":false},{"name":"wholemeal flour","plural":"wholemeal flour","qty":150,"unit":"g","have":false},{"name":"rolled oats","plural":"rolled oats","qty":60,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mash the bananas and mix them with the eggs and melted oil.","timer":null},{"text":"Add the flour, oats, baking powder and cinnamon.","timer":null},{"text":"Pour into a loaf tin and bake for 45 min.","timer":{"label":"Oven","min":45}}],"kids":true,"dessert":true,"variant":"No added sugar","change":"Very ripe bananas are enough to sweeten it."}]$r$::jsonb, 'claude')
