insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:cheesecake', 'Cheesecake', array['en:cheese cake', 'en:new york cheesecake', 'en:homemade cheesecake']::text[], 'dish', $r$[{"title":"New York cheesecake","intro":"The creamy cheesecake on a biscuit base, baked gently in the oven.","minutes":90,"calories":480,"difficulty":"Moyen","imageSearch":"new york cheesecake","veg":true,"oven":true,"cold":false,"missing":"","origin":"New York recipe","serves":4,"items":[{"name":"plain biscuit","plural":"plain biscuits","qty":200,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"cream cheese","plural":"cream cheese","qty":600,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 160 °C. Crush the biscuits and mix them with the melted butter.","timer":null},{"text":"Press this mixture into the bottom of a springform tin.","timer":null},{"text":"Whisk the cream cheese, sugar, cream and lemon zest, then the eggs one by one.","timer":null},{"text":"Pour over the base and bake for 1 h.","timer":{"label":"Oven","min":60}},{"text":"Leave to cool in the oven with the door ajar, then chill for at least 4 h.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"No-bake cheesecake","intro":"A fresh, light cheesecake you make the day before.","minutes":30,"calories":420,"difficulty":"Facile","imageSearch":"no bake cheesecake","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"plain biscuit","plural":"plain biscuits","qty":200,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"cream cheese","plural":"cream cheese","qty":400,"unit":"g","have":false},{"name":"whole liquid cream","plural":"whole liquid cream","qty":25,"unit":"cl","have":false},{"name":"icing sugar","plural":"icing sugar","qty":80,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Crush the biscuits, mix with the melted butter and press into the bottom of a springform tin.","timer":null},{"text":"Whip the very cold cream until thick.","timer":null},{"text":"Mix the cream cheese, icing sugar and lemon juice, then fold in the whipped cream.","timer":null},{"text":"Spread over the base and leave to set in the fridge for at least 6 h.","timer":null}],"dessert":true,"variant":"No oven","change":"Set in the fridge, with no oven."},{"title":"Berry cheesecake","intro":"The creamy cheesecake, covered with a berry sauce.","minutes":100,"calories":500,"difficulty":"Moyen","imageSearch":"berry cheesecake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"plain biscuit","plural":"plain biscuits","qty":200,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"cream cheese","plural":"cream cheese","qty":600,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":180,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"frozen mixed berries","plural":"frozen mixed berries","qty":300,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 160 °C. Press the crushed biscuits and butter into the bottom of a tin.","timer":null},{"text":"Whisk the cream cheese, 150 g of sugar and the cream, then the eggs.","timer":null},{"text":"Pour over the base and bake for 1 h. Leave to cool, then chill for 4 h.","timer":{"label":"Oven","min":60}},{"text":"Cook the berries for 10 min with the rest of the sugar, then leave to cool.","timer":{"label":"Cooking","min":10}},{"text":"Cover the cheesecake with the sauce just before serving.","timer":null}],"dessert":true,"variant":"Berries","change":"With a berry sauce on top."}]$r$::jsonb, 'claude')
