insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:sable', 'Shortbread', array['en:shortbread', 'en:butter biscuit', 'en:shortbread biscuit']::text[], 'dish', $r$[{"title":"Butter shortbread","intro":"Little pure butter shortbread biscuits, cut out with a cutter.","minutes":50,"calories":90,"difficulty":"Facile","imageSearch":"butter shortbread cookies","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":125,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the soft butter, sugar, vanilla sugar and a pinch of salt.","timer":null},{"text":"Add the egg, then the flour, and shape into a ball without overworking it.","timer":null},{"text":"Chill for 30 min.","timer":{"label":"Rest","min":30}},{"text":"Preheat the oven to 180 °C. Roll out the dough and cut out the biscuits.","timer":null},{"text":"Bake for 10 min. They should stay pale.","timer":{"label":"Oven","min":10}}],"kids":true,"dessert":true,"makes":{"n":25,"one":"shortbread biscuit","many":"shortbread biscuits"},"variant":"The classic","change":""},{"title":"Lemon shortbread","intro":"Fresh shortbread flavoured with lemon.","minutes":50,"calories":90,"difficulty":"Facile","imageSearch":"lemon shortbread cookies","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":125,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Mix the soft butter, sugar and lemon zest.","timer":null},{"text":"Add the egg, then the flour, and shape into a ball.","timer":null},{"text":"Chill for 30 min.","timer":{"label":"Rest","min":30}},{"text":"Preheat the oven to 180 °C, roll out the dough and cut out the biscuits.","timer":null},{"text":"Bake for 10 min.","timer":{"label":"Oven","min":10}}],"kids":true,"dessert":true,"makes":{"n":25,"one":"shortbread biscuit","many":"shortbread biscuits"},"variant":"Lemon","change":"With the zest of a lemon in the dough."},{"title":"Chocolate shortbread","intro":"Cocoa shortbread with chips, for chocolate lovers.","minutes":50,"calories":105,"difficulty":"Facile","imageSearch":"chocolate shortbread cookies","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":220,"unit":"g","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":30,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":125,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"chocolate chip","plural":"chocolate chips","qty":60,"unit":"g","have":false}],"steps":[{"text":"Mix the soft butter and sugar, then the egg.","timer":null},{"text":"Add the flour, cocoa and chocolate chips, and shape into a ball.","timer":null},{"text":"Chill for 30 min.","timer":{"label":"Rest","min":30}},{"text":"Preheat the oven to 180 °C, roll out the dough and cut out the biscuits.","timer":null},{"text":"Bake for 10 min.","timer":{"label":"Oven","min":10}}],"kids":true,"dessert":true,"makes":{"n":25,"one":"shortbread biscuit","many":"shortbread biscuits"},"variant":"Chocolate","change":"With cocoa and chocolate chips."}]$r$::jsonb, 'claude')
