insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:brioche', 'Brioche', array['en:homemade brioche', 'en:soft brioche']::text[], 'dish', $r$[{"title":"Homemade brioche","intro":"A soft, stringy brioche for weekend breakfast.","minutes":180,"calories":320,"difficulty":"Moyen","imageSearch":"homemade brioche","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":500,"unit":"g","have":false},{"name":"baker's yeast","plural":"baker's yeast","qty":10,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":150,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Dissolve the yeast in the lukewarm milk.","timer":null},{"text":"Mix the flour, sugar, 1 tsp of salt, 3 eggs and the milk, then knead for 10 min.","timer":{"label":"Kneading","min":10}},{"text":"Add the soft butter in pieces and keep kneading until the dough is smooth.","timer":null},{"text":"Leave to rise for 1 h 30 under a tea towel.","timer":{"label":"Rise","min":90}},{"text":"Shape 6 balls into a loaf tin and leave to rise for another 45 min.","timer":{"label":"Rise","min":45}},{"text":"Preheat the oven to 180 °C, brush with the last beaten egg and bake for 30 min.","timer":{"label":"Oven","min":30}}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Chocolate chip brioche","intro":"The soft tea-time brioche, full of chocolate chips.","minutes":180,"calories":360,"difficulty":"Moyen","imageSearch":"chocolate chip brioche","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":500,"unit":"g","have":false},{"name":"baker's yeast","plural":"baker's yeast","qty":10,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":150,"unit":"g","have":false},{"name":"chocolate chip","plural":"chocolate chips","qty":120,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Dissolve the yeast in the lukewarm milk, then knead with the flour, sugar, salt and 3 eggs.","timer":{"label":"Kneading","min":10}},{"text":"Add the soft butter, then the chocolate chips, while kneading.","timer":null},{"text":"Leave to rise for 1 h 30.","timer":{"label":"Rise","min":90}},{"text":"Shape into a loaf tin and leave to rise for 45 min.","timer":{"label":"Rise","min":45}},{"text":"Brush with the last egg and bake for 30 min at 180 °C.","timer":{"label":"Oven","min":30}}],"kids":true,"dessert":true,"variant":"Chocolate","change":"With chocolate chips in the dough."},{"title":"Braided brioche","intro":"A beautiful braided brioche for the middle of the table.","minutes":180,"calories":330,"difficulty":"Difficile","imageSearch":"braided brioche","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":500,"unit":"g","have":false},{"name":"baker's yeast","plural":"baker's yeast","qty":10,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":150,"unit":"g","have":false},{"name":"pearl sugar","plural":"pearl sugar","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Dissolve the yeast in the lukewarm milk, then knead with the flour, sugar, salt and 3 eggs.","timer":{"label":"Kneading","min":10}},{"text":"Add the soft butter and knead until the dough is smooth.","timer":null},{"text":"Leave to rise for 1 h 30.","timer":{"label":"Rise","min":90}},{"text":"Divide the dough into 3 ropes and braid them on a baking tray. Leave to rise for 45 min.","timer":{"label":"Rise","min":45}},{"text":"Brush with beaten egg, sprinkle with pearl sugar and bake for 25 min at 180 °C.","timer":{"label":"Oven","min":25}}],"kids":true,"dessert":true,"variant":"Braided","change":"Shaped into a braid and sprinkled with pearl sugar."}]$r$::jsonb, 'claude')
