insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:beignet', 'Beignets', array['en:sugar doughnut', 'en:fritter']::text[], 'dish', $r$[{"title":"Sugar doughnuts","intro":"Soft doughnuts, deep-fried until golden and rolled in sugar.","minutes":150,"calories":280,"difficulty":"Moyen","imageSearch":"sugar donuts","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":400,"unit":"g","have":false},{"name":"baker's yeast","plural":"baker's yeast","qty":10,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":50,"unit":"g","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Dissolve the yeast in the lukewarm milk.","timer":null},{"text":"Mix the flour, 50 g of sugar, a pinch of salt, the eggs, the milk and the melted butter, and knead for 5 min.","timer":null},{"text":"Leave to rise for 1 h 30.","timer":{"label":"Rise","min":90}},{"text":"Roll out the dough to 1 cm, cut out rounds and leave to rise for 30 min.","timer":{"label":"Rise","min":30}},{"text":"Fry the doughnuts for 2 min on each side in the hot oil.","timer":{"label":"Frying","min":4}},{"text":"Drain them and roll them in the rest of the sugar.","timer":null}],"kids":true,"dessert":true,"makes":{"n":16,"one":"beignet","many":"beignets"},"variant":"The classic","change":""},{"title":"Apple fritters","intro":"Carnival apple fritters, crisp and soft.","minutes":40,"calories":250,"difficulty":"Facile","imageSearch":"apple fritters","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":4,"unit":"","have":