on kitchen paper and serve warm.","timer":null}],"kids":true,"dessert":true,"makes":{"n":16,"one":"beignet","many":"beignets"},"variant":"Banana","change":"Pieces of banana in a light batter."}]$r$::jsonb, 'claude')
