insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:panna cotta', 'Panna cotta', array['en:pannacotta', 'en:panna cotta with berry couli']::text[], 'dish', $r$[{"title":"Panna cotta with berry coulis","intro":"The wobbly Italian cream, flavoured with vanilla, with a berry coulis.","minutes":20,"calories":330,"difficulty":"Facile","imageSearch":"panna cotta berry coulis","veg":true,"oven":false,"cold":true,"missing":"","origin":"Italian dessert","serves":4,"items":[{"name":"whole liquid cream","plural":"whole liquid cream","qty":50,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"gelatine","plural":"gelatine","qty":3,"unit":"leaves","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false},{"name":"frozen mixed berries","plural":"frozen mixed berries","qty":250,"unit":"g","have":false}],"steps":[{"text":"Soften the gelatine in cold water.","timer":null},{"text":"Heat the cream with 60 g of sugar and the split vanilla pod, without boiling.","timer":{"label":"Cooking","min":5}},{"text":"Take off the heat, add the squeezed gelatine and stir.","timer":null},{"text":"Pour into glasses and leave to set in the fridge for 4 h.","timer":null},{"text":"Blend the berries with the rest of the sugar and pour over just before serving.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"Mango panna cotta","intro":"A very gentle panna cotta under an exotic mango coulis.","minutes":20,"calories":320,"difficulty":"Facile","imageSearch":"mango panna cotta","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"whole liquid cream","plural":"whole liquid cream","qty":50,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"gelatine","plural":"gelatine","qty":3,"unit":"leaves","have":false},{"name":"mango","plural":"mangoes","qty":1,"unit":"","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false}],"steps":[{"text":"Soften the gelatine in cold water.","timer":null},{"text":"Heat the cream with the sugar without boiling, then add the squeezed gelatine.","timer":{"label":"Cooking","min":5}},{"text":"Pour into glasses and leave to set in the fridge for 4 h.","timer":null},{"text":"Blend the mango with the lime juice and pour over the panna cottas.","timer":null}],"dessert":true,"variant":"Mango","change":"With a fresh mango coulis."},{"title":"Coconut milk panna cotta","intro":"A lighter panna cotta with a coconut flavour.","minutes":20,"calories":260,"difficulty":"Facile","imageSearch":"coconut panna cotta","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"whole liquid cream","plural":"whole liquid cream","qty":10,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"gelatine","plural":"gelatine","qty":3,"unit":"leaves","have":false},{"name":"pineapple","plural":"pineapples","qty":1,"unit":"","have":false}],"steps":[{"text":"Soften the gelatine in cold water.","timer":null},{"text":"Heat the coconut milk, cream and sugar, then add the squeezed gelatine.","timer":{"label":"Cooking","min":5}},{"text":"Pour into glasses and leave to set in the fridge for 4 h.","timer":null},{"text":"Serve with the pineapple cut into small dice.","timer":null}],"dessert":true,"variant":"With coconut milk","change":"Coconut milk replaces some of the cream."}]$r$::jsonb, 'claude')
