insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:ile flottante', 'Floating island', array['en:floating island', 'en:oeuf a la neige']::text[], 'dish', $r$[{"title":"Floating island","intro":"Poached meringues on a custard, with a drizzle of caramel.","minutes":45,"calories":300,"difficulty":"Moyen","imageSearch":"floating island dessert","veg":true,"oven":false,"cold":true,"missing":"","origin":"French dessert","serves":4,"items":[{"name":"egg","plural":"eggs","qty":6,"unit":"","have":false},{"name":"milk","plural":"milk","qty":75,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":180,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Heat the milk with the split vanilla pod. Whisk the yolks with 80 g of sugar.","timer":null},{"text":"Pour the hot milk over the yolks, then thicken over a low heat without boiling, stirring. It is ready when the custard coats the spoon.","timer":{"label":"Cooking","min":10}},{"text":"Whisk the whites to stiff peaks with a pinch of salt and 40 g of sugar.","timer":null},{"text":"Poach spoonfuls of the whites for 1 min on each side in simmering water.","timer":{"label":"Cooking","min":2}},{"text":"Make a caramel with the rest of the sugar and 2 tbsp of water.","timer":null},{"text":"Put the meringues on the cold custard and drizzle with caramel.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"Microwave floating islands","intro":"The quick version, with shop-bought custard.","minutes":15,"calories":250,"difficulty":"Facile","imageSearch":"floating island bowl","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"egg white","plural":"egg whites","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"custard","plural":"custard","qty":50,"unit":"cl","have":false},{"name":"liquid caramel","plural":"liquid caramel","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Whisk the whites to stiff peaks, adding the sugar at the end.","timer":null},{"text":"Spoon 4 mounds of whites into lightly oiled cups.","timer":null},{"text":"Cook them in the microwave for 30 seconds.","timer":null},{"text":"Turn out onto the custard and drizzle with caramel.","timer":null}],"kids":true,"dessert":true,"variant":"Quick","change":"The whites cook in the microwave in a few seconds."},{"title":"Floating island with pink pralines","intro":"The floating island from Lyon, crunchy and pink.","minutes":45,"calories":330,"difficulty":"Moyen","imageSearch":"floating island pink pralines","veg":true,"oven":false,"cold":true,"missing":"","origin":"Lyon-inspired","serves":4,"items":[{"name":"egg","plural":"eggs","qty":6,"unit":"","have":false},{"name":"milk","plural":"milk","qty":75,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":130,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false},{"name":"pink praline","plural":"pink pralines","qty":60,"unit":"g","have":false}],"steps":[{"text":"Make the custard: pour the hot vanilla milk over the yolks whisked with 80 g of sugar, then thicken over a low heat.","timer":{"label":"Cooking","min":10}},{"text":"Leave to cool in the fridge.","timer":null},{"text":"Whisk the whites with the rest of the sugar.","timer":null},{"text":"Poach the whites for 1 min on each side in simmering water.","timer":{"label":"Cooking","min":2}},{"text":"Put them on the custard and sprinkle with crushed pralines.","timer":null}],"dessert":true,"variant":"Pink pralines","change":"Sprinkled with crushed pink pralines."}]$r$::jsonb, 'claude')
