insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:profiterole', 'Profiteroles', array['en:cream puff', 'en:chou pastry']::text[], 'dish', $r$[{"title":"Chocolate profiteroles","intro":"Choux buns filled with vanilla ice cream, covered with hot chocolate sauce.","minutes":75,"calories":450,"difficulty":"Difficile","imageSearch":"profiteroles chocolate sauce","veg":true,"oven":true,"cold":false,"missing":"","origin":"French dessert","serves":4,"items":[{"name":"flour","plural":"flour","qty":75,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":60,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"vanilla ice cream","plural":"vanilla ice cream","qty":50,"unit":"cl","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":150,"unit":"g","have":false},{"name":"liquid cream","plural":"liquid cream","qty":15,"unit":"cl","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Bring 12 cl of water, the butter and a pinch of salt to the boil.","timer":null},{"text":"Tip in the flour all at once and stir until the dough comes away from the pan.","timer":null},{"text":"Off the heat, beat in the eggs one by one.","timer":null},{"text":"Pipe small mounds on a baking tray and bake for 25 min without opening the oven.","timer":{"label":"Oven","min":25}},{"text":"Melt the chocolate in the hot cream.","timer":null},{"text":"Cut the cold buns open, fill them with ice cream and cover with the hot sauce.","timer":null}],"dessert":true,"makes":{"n":20,"one":"choux bun","many":"choux buns"},"variant":"The classic","change":""},{"title":"Whipped cream choux buns","intro":"Light choux buns filled with homemade whipped cream.","minutes":70,"calories":350,"difficulty":"Difficile","imageSearch":"cream puffs","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":75,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":60,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"whole liquid cream","plural":"whole liquid cream","qty":30,"unit":"cl","have":false},{"name":"icing sugar","plural":"icing sugar","qty":40,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Make the choux pastry: bring water, butter and salt to the boil, add the flour all at once, then beat in the eggs one by one.","timer":null},{"text":"Pipe small mounds on a baking tray and bake for 25 min at 200 °C.","timer":{"label":"Oven","min":25}},{"text":"Whip the very cold cream with the icing sugar.","timer":null},{"text":"Fill the cold buns and dust with icing sugar.","timer":null}],"dessert":true,"makes":{"n":20,"one":"choux bun","many":"choux buns"},"variant":"With whipped cream","change":"Filled with whipped cream, no ice cream."},{"title":"Caramel profiteroles","intro":"Profiteroles with a salted butter caramel instead of chocolate.","minutes":75,"calories":470,"difficulty":"Difficile","imageSearch":"caramel profiteroles","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":75,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":60,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"vanilla ice cream","plural":"vanilla ice cream","qty":50,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"liquid cream","plural":"liquid cream","qty":10,"unit":"cl","have":false},{"name":"salted butter","plural":"salted butter","qty":30,"unit":"g","have":false}],"steps":[{"text":"Make the choux pastry and bake the buns for 25 min at 200 °C.","timer":{"label":"Oven","min":25}},{"text":"Melt the sugar on its own until it is a light caramel.","timer":null},{"text":"Off the heat, add the hot cream, then the salted butter.","timer":null},{"text":"Fill the buns with ice cream and cover with the warm caramel.","timer":null}],"dessert":true,"makes":{"n":20,"one":"choux bun","many":"choux buns"},"variant":"Caramel","change":"Covered with a salted butter caramel sauce."}]$r$::jsonb, 'claude')
