insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:salade de fruit', 'Fruit salad', array['en:fruit salad', 'en:fresh fruit salad', 'en:macedoine']::text[], 'dish', $r$[{"title":"Fresh fruit salad","intro":"Chopped seasonal fruit with a light lemon syrup.","minutes":20,"calories":150,"difficulty":"Facile","imageSearch":"fresh fruit salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":2,"unit":"","have":false},{"name":"pear","plural":"pears","qty":2,"unit":"","have":false},{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"orange","plural":"oranges","qty":2,"unit":"","have":false},{"name":"grape","plural":"grapes","qty":200,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Squeeze the lemon and mix the juice with the sugar.","timer":null},{"text":"Peel the oranges, removing all the pith, and cut into pieces.","timer":null},{"text":"Dice the apples, pears and bananas.","timer":null},{"text":"Mix all the fruit with the grapes and the sweet juice.","timer":null},{"text":"Chill for 30 min before serving.","timer":null}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Tropical fruit salad","intro":"A sunny fruit salad with tropical fruit.","minutes":20,"calories":160,"difficulty":"Facile","imageSearch":"tropical fruit salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"mango","plural":"mangoes","qty":1,"unit":"","have":false},{"name":"pineapple","plural":"pineapples","qty":1,"unit":"","have":false},{"name":"kiwi","plural":"kiwis","qty":3,"unit":"","have":false},{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"passion fruit","plural":"passion fruits","qty":2,"unit":"","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false}],"steps":[{"text":"Peel the mango, pineapple and kiwis, and cut into dice.","timer":null},{"text":"Add the sliced bananas.","timer":null},{"text":"Pour over the lime juice and the passion fruit pulp.","timer":null},{"text":"Mix and chill for 30 min.","timer":null}],"kids":true,"dessert":true,"variant":"Tropical","change":"Mango, pineapple and passion fruit."},{"title":"Berry and mint fruit salad","intro":"A summer salad with strawberries, raspberries and mint.","minutes":15,"calories":120,"difficulty":"Facile","imageSearch":"berry salad mint","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"strawberry","plural":"strawberries","qty":500,"unit":"g","have":false},{"name":"raspberry","plural":"raspberries","qty":125,"unit":"g","have":false},{"name":"blueberry","plural":"blueberries","qty":125,"unit":"g","have":false},{"name":"fresh mint","plural":"fresh mint","qty":null,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Wash and hull the strawberries, then cut them in half.","timer":null},{"text":"Mix them with the raspberries and blueberries.","timer":null},{"text":"Pour over the lemon juice mixed with the sugar.","timer":null},{"text":"Add the chopped mint and chill for 15 min.","timer":null}],"kids":true,"dessert":true,"variant":"Berries","change":"Berries with fresh mint."}]$r$::jsonb, 'claude')
