insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:compote de pomme', 'Apple compote', array['en:apple compote', 'en:stewed apple', 'en:applesauce', 'en:compote']::text[], 'dish', $r$[{"title":"Apple compote","intro":"Very simple homemade compote, with just apples and a little cinnamon.","minutes":30,"calories":120,"difficulty":"Facile","imageSearch":"applesauce bowl","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":8,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":2,"unit":"tbsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Peel and core the apples and cut them into pieces.","timer":null},{"text":"Put them in a pan with 10 cl of water, the sugar and the cinnamon.","timer":null},{"text":"Cook for 20 min with the lid on, stirring from time to time.","timer":{"label":"Cooking","min":20}},{"text":"Mash with a fork or blend, depending on the texture you like.","timer":null}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Apple and pear compote","intro":"A gentle compote, sweetened only by the fruit.","minutes":30,"calories":100,"difficulty":"Facile","imageSearch":"apple pear compote","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":4,"unit":"","have":false},{"name":"pear","plural":"pears","qty":4,"unit":"","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Peel and core the fruit and cut into pieces.","timer":null},{"text":"Put it in a pan with 5 cl of water and the cinnamon.","timer":null},{"text":"Cook for 20 min with the lid on.","timer":{"label":"Cooking","min":20}},{"text":"Mash or blend, then leave to cool.","timer":null}],"kids":true,"dessert":true,"variant":"Apples and pears","change":"Half apples, half pears, with no added sugar."},{"title":"Apple and strawberry compote","intro":"A pink, fruity compote that kids love.","minutes":30,"calories":110,"difficulty":"Facile","imageSearch":"apple strawberry compote","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":6,"unit":"","have":false},{"name":"strawberry","plural":"strawberries","qty":250,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Peel the apples and cut them into pieces.","timer":null},{"text":"Cook them for 15 min with the lid on, with 5 cl of water and the sugar.","timer":{"label":"Cooking","min":15}},{"text":"Add the hulled strawberries and cook for 5 min.","timer":{"label":"Cooking","min":5}},{"text":"Blend and leave to cool.","timer":null}],"kids":true,"dessert":true,"variant":"Apples and strawberries","change":"With strawberries added at the end of cooking."}]$r$::jsonb, 'claude')
