insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:creme caramel', 'Crème caramel', array['en:caramel custard', 'en:flan', 'en:creme renversee']::text[], 'dish', $r$[{"title":"Crème caramel","intro":"The vanilla set custard, covered with its light caramel.","minutes":70,"calories":250,"difficulty":"Moyen","imageSearch":"creme caramel","veg":true,"oven":true,"cold":false,"missing":"","origin":"French dessert","serves":4,"items":[{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":180,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 160 °C.","timer":null},{"text":"Make a caramel with 100 g of sugar and 3 tbsp of water, and pour it into the bottom of the ramekins.","timer":null},{"text":"Heat the milk with the split vanilla pod.","timer":null},{"text":"Whisk the eggs and the rest of the sugar, then pour the hot milk over them.","timer":null},{"text":"Fill the ramekins and bake in a bain-marie for 40 min.","timer":{"label":"Oven","min":40}},{"text":"Leave to cool, then chill for 2 h before turning out.","timer":null}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Coconut crème caramel","intro":"A set custard with the taste of the islands.","minutes":70,"calories":280,"difficulty":"Moyen","imageSearch":"coconut flan","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":170,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 160 °C and make a caramel with 100 g of sugar and a little water.","timer":null},{"text":"Pour it into the bottom of the ramekins.","timer":null},{"text":"Whisk the eggs with the rest of the sugar, then add the coconut milk and the milk.","timer":null},{"text":"Fill the ramekins and bake in a bain-marie for 40 min.","timer":{"label":"Oven","min":40}},{"text":"Chill for 2 h before turning out.","timer":null}],"kids":true,"dessert":true,"variant":"Coconut","change":"Coconut milk replaces some of the milk."},{"title":"Pressure cooker crème caramel","intro":"Crème caramel without turning on the oven.","minutes":40,"calories":250,"difficulty":"Moyen","imageSearch":"creme caramel ramekin","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":180,"unit":"g","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false}],"steps":[{"text":"Make a caramel with 100 g of sugar and a little water, and pour it into ramekins.","timer":null},{"text":"Whisk the eggs, the rest of the sugar and the vanilla sugar, then add the hot milk.","timer":null},{"text":"Fill the ramekins and cover them with foil.","timer":null},{"text":"Put them in the pressure cooker with 2 cm of water and cook for 6 min after it starts to whistle.","timer":{"label":"Cooking","min":6}},{"text":"Leave to cool, then chill for 2 h.","timer":null}],"kids":true,"dessert":true,"variant":"No oven","change":"Steamed in a pressure cooker."}]$r$::jsonb, 'claude')
