insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poire belle helene', 'Pears belle Hélène', array['en:pear belle helene', 'en:chocolate pear', 'en:poached pear']::text[], 'dish', $r$[{"title":"Pears belle Hélène","intro":"Pears poached in vanilla syrup, covered with hot chocolate.","minutes":40,"calories":330,"difficulty":"Facile","imageSearch":"poire belle helene","veg":true,"oven":false,"cold":true,"missing":"","origin":"French dessert","serves":4,"items":[{"name":"pear","plural":"pears","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":150,"unit":"g","have":false},{"name":"liquid cream","plural":"liquid cream","qty":15,"unit":"cl","have":false},{"name":"vanilla ice cream","plural":"vanilla ice cream","qty":50,"unit":"cl","have":false}],"steps":[{"text":"Bring 1 litre of water to the boil with the sugar and the split vanilla pod.","timer":null},{"text":"Peel the pears, leaving the stalk on, and poach them in the syrup for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Leave them to cool in the syrup.","timer":null},{"text":"Melt the chocolate in the hot cream.","timer":null},{"text":"Serve each pear with a scoop of ice cream and the chocolate sauce.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"Pears poached in red wine","intro":"Red, fragrant pears for a winter dessert.","minutes":50,"calories":250,"difficulty":"Facile","imageSearch":"poached pears red wine","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pear","plural":"pears","qty":4,"unit":"","have":false},{"name":"red wine","plural":"red wine","qty":75,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"cinnamon stick","plural":"cinnamon sticks","qty":1,"unit":"","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false}],"steps":[{"text":"Bring the wine to the boil with the sugar, cinnamon and orange zest.","timer":null},{"text":"Peel the pears, leaving the stalk on.","timer":null},{"text":"Poach them for 30 min in the simmering wine, turning them over.","timer":{"label":"Cooking","min":30}},{"text":"Remove the pears and boil the wine down to a syrup.","timer":{"label":"Cooking","min":10}},{"text":"Serve warm or cold, covered with syrup.","timer":null}],"dessert":true,"variant":"In wine","change":"Poached in spiced red wine."},{"title":"Honey roast pears","intro":"Soft pears caramelised with honey.","minutes":35,"calories":180,"difficulty":"Facile","imageSearch":"roasted pears honey","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pear","plural":"pears","qty":4,"unit":"","have":false},{"name":"honey","plural":"honey","qty":3,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Cut the pears in half and remove the cores.","timer":null},{"text":"Put them in a dish, drizzle with honey and dot with butter and cinnamon.","timer":null},{"text":"Bake for 25 min, basting halfway through.","timer":{"label":"Oven","min":25}}],"kids":true,"dessert":true,"variant":"Roasted","change":"Roasted in the oven with honey, with no syrup."}]$r$::jsonb, 'claude')
