insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:charlotte aux fraise', 'Strawberry charlotte', array['en:strawberry charlotte', 'en:charlotte']::text[], 'dish', $r$[{"title":"Strawberry charlotte","intro":"Sponge fingers around a light strawberry mousse.","minutes":40,"calories":350,"difficulty":"Moyen","imageSearch":"strawberry charlotte","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"sponge finger","plural":"sponge fingers","qty":24,"unit":"","have":false},{"name":"strawberry","plural":"strawberries","qty":500,"unit":"g","have":false},{"name":"whole liquid cream","plural":"whole liquid cream","qty":30,"unit":"cl","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":250,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"gelatine","plural":"gelatine","qty":4,"unit":"leaves","have":false}],"steps":[{"text":"Soften the gelatine in cold water. Blend half the strawberries with the sugar.","timer":null},{"text":"Warm a little of this coulis and melt the gelatine in it, then mix with the rest.","timer":null},{"text":"Whip the cream and fold it into the fromage blanc and the coulis.","timer":null},{"text":"Quickly dip the sponge fingers in sugar water and line a tin.","timer":null},{"text":"Layer the mousse and chopped strawberries, then cover with sponge fingers.","timer":null},{"text":"Leave to set in the fridge for 6 h before turning out.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"Raspberry charlotte","intro":"The tangy raspberry charlotte.","minutes":40,"calories":350,"difficulty":"Moyen","imageSearch":"raspberry charlotte","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"sponge finger","plural":"sponge fingers","qty":24,"unit":"","have":false},{"name":"raspberry","plural":"raspberries","qty":400,"unit":"g","have":false},{"name":"whole liquid cream","plural":"whole liquid cream","qty":30,"unit":"cl","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":250,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"gelatine","plural":"gelatine","qty":4,"unit":"leaves","have":false}],"steps":[{"text":"Soften the gelatine. Blend half the raspberries with the sugar and melt the gelatine in a little warm coulis.","timer":null},{"text":"Whip the cream and fold it into the fromage blanc and the coulis.","timer":null},{"text":"Line a tin with sponge fingers dipped in sugar water.","timer":null},{"text":"Layer the mousse and whole raspberries, then cover with sponge fingers.","timer":null},{"text":"Leave to set in the fridge for 6 h.","timer":null}],"dessert":true,"variant":"Raspberries","change":"With raspberries instead of strawberries."},{"title":"Chocolate charlotte","intro":"The charlotte for those with a sweet tooth, filled with chocolate mousse.","minutes":40,"calories":420,"difficulty":"Moyen","imageSearch":"chocolate charlotte","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"sponge finger","plural":"sponge fingers","qty":24,"unit":"","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":5,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":40,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Melt the chocolate and leave to cool slightly, then add the egg yolks.","timer":null},{"text":"Whisk the whites to stiff peaks with the sugar and gently fold them into the chocolate.","timer":null},{"text":"Quickly dip the sponge fingers in the milk and line a tin.","timer":null},{"text":"Pour in the mousse and cover with sponge fingers.","timer":null},{"text":"Leave to set in the fridge for 6 h before turning out.","timer":null}],"dessert":true,"variant":"Chocolate","change":"With a chocolate mousse."}]$r$::jsonb, 'claude')
