insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pavlova', 'Pavlova', array['en:fruit pavlova', 'en:meringue with fruit']::text[], 'dish', $r$[{"title":"Berry pavlova","intro":"A meringue that is crisp outside and soft inside, with whipped cream and berries.","minutes":150,"calories":300,"difficulty":"Moyen","imageSearch":"berry pavlova","veg":true,"oven":true,"cold":false,"missing":"","origin":"Australian dessert","serves":4,"items":[{"name":"egg white","plural":"egg whites","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":200,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tsp","have":false},{"name":"white vinegar","plural":"white vinegar","qty":1,"unit":"tsp","have":false},{"name":"whole liquid cream","plural":"whole liquid cream","qty":30,"unit":"cl","have":false},{"name":"mixed berries","plural":"mixed berries","qty":300,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 120 °C.","timer":null},{"text":"Whisk the whites to stiff peaks, then add the sugar little by little until you have a glossy meringue.","timer":null},{"text":"Add the cornflour and vinegar, and shape into a big disc on a baking tray.","timer":null},{"text":"Bake for 1 h 30, then leave to cool in the switched-off oven.","timer":{"label":"Oven","min":90}},{"text":"Whip the cream, spread it over the meringue and top with the berries.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"Tropical pavlova","intro":"The pavlova with tropical fruit, fresh and tangy.","minutes":150,"calories":300,"difficulty":"Moyen","imageSearch":"tropical pavlova","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg white","plural":"egg whites","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":200,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tsp","have":false},{"name":"whole liquid cream","plural":"whole liquid cream","qty":30,"unit":"cl","have":false},{"name":"mango","plural":"mangoes","qty":1,"unit":"","have":false},{"name":"kiwi","plural":"kiwis","qty":2,"unit":"","have":false},{"name":"passion fruit","plural":"passion fruits","qty":2,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 120 °C. Whisk the whites with the sugar into a glossy meringue, then add the cornflour.","timer":null},{"text":"Shape into a disc on a baking tray and bake for 1 h 30.","timer":{"label":"Oven","min":90}},{"text":"Leave to cool in the switched-off oven.","timer":null},{"text":"Cover with whipped cream, diced mango and kiwi, then the passion fruit pulp.","timer":null}],"dessert":true,"variant":"Tropical","change":"With mango, kiwi and passion fruit."},{"title":"Mini strawberry pavlovas","intro":"Little strawberry pavlovas, to serve on plates.","minutes":110,"calories":280,"difficulty":"Moyen","imageSearch":"mini strawberry pavlovas","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg white","plural":"egg whites","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tsp","have":false},{"name":"whole liquid cream","plural":"whole liquid cream","qty":25,"unit":"cl","have":false},{"name":"strawberry","plural":"strawberries","qty":300,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 120 °C. Whisk the whites with the sugar into a meringue, then add the cornflour.","timer":null},{"text":"Shape 6 little nests on a baking tray.","timer":null},{"text":"Bake for 1 h and leave to cool in the oven.","timer":{"label":"Oven","min":60}},{"text":"Fill with whipped cream and sliced strawberries.","timer":null}],"dessert":true,"makes":{"n":8,"one":"mini pavlova","many":"mini pavlovas"},"variant":"Individual","change":"As small individual meringues."}]$r$::jsonb, 'claude')
