insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:galette des roi', 'Galette des rois', array['en:frangipane galette', 'en:king cake', 'en:almond cream tart']::text[], 'dish', $r$[{"title":"Frangipane galette des rois","intro":"The puff pastry galette filled with frangipane, with the charm hidden inside.","minutes":60,"calories":480,"difficulty":"Moyen","imageSearch":"galette des rois","veg":true,"oven":true,"cold":false,"missing":"","origin":"French tradition","serves":4,"items":[{"name":"puff pastry","plural":"puff pastries","qty":2,"unit":"","have":false},{"name":"ground almond","plural":"ground almonds","qty":125,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Mix the ground almonds, sugar, soft butter and 2 eggs.","timer":null},{"text":"Roll out one pastry on a baking tray, spread with frangipane leaving a 2 cm border, and place the charm.","timer":null},{"text":"Cover with the second pastry and seal the edges well.","timer":null},{"text":"Brush with the last beaten egg and draw patterns with the tip of a knife.","timer":null},{"text":"Bake for 30 min.","timer":{"label":"Oven","min":30}}],"dessert":true,"variant":"The classic","change":""},{"title":"Apple galette des rois","intro":"A lighter galette, filled with apples.","minutes":60,"calories":380,"difficulty":"Moyen","imageSearch":"apple galette des rois","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"puff pastry","plural":"puff pastries","qty":2,"unit":"","have":false},{"name":"apple","plural":"apples","qty":3,"unit":"","have":false},{"name":"apple compote","plural":"apple compote","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":30,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Roll out one pastry, spread with compote, then add thin apple slices sprinkled with sugar, and place the charm.","timer":null},{"text":"Cover with the second pastry and seal the edges.","timer":null},{"text":"Brush with beaten egg and bake for 30 min.","timer":{"label":"Oven","min":30}}],"dessert":true,"variant":"With apples","change":"Compote and apples instead of frangipane."},{"title":"Chocolate and pear galette des rois","intro":"The chocolate and pear duo, in a galette des rois.","minutes":60,"calories":520,"difficulty":"Moyen","imageSearch":"chocolate pear galette","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"puff pastry","plural":"puff pastries","qty":2,"unit":"","have":false},{"name":"ground almond","plural":"ground almonds","qty":100,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":80,"unit":"g","have":false},{"name":"pear","plural":"pears","qty":2,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Melt the chocolate.","timer":null},{"text":"Mix the ground almonds, sugar, butter, 2 eggs and the melted chocolate.","timer":null},{"text":"Roll out one pastry, spread with frangipane and diced pears, and place the charm.","timer":null},{"text":"Cover with the second pastry, seal the edges and brush with the last egg.","timer":null},{"text":"Bake for 30 min.","timer":{"label":"Oven","min":30}}],"dessert":true,"variant":"Chocolate and pear","change":"Chocolate frangipane and pieces of pear."}]$r$::jsonb, 'claude')
