insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:salade caprese', 'Caprese salad', array['en:caprese salad', 'en:caprese', 'en:tomato mozzarella salad']::text[], 'dish', $r$[{"title":"Caprese salad","intro":"Tomatoes, mozzarella and basil with a drizzle of olive oil: Italy in 10 minutes.","minutes":10,"calories":280,"difficulty":"Facile","imageSearch":"caprese salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"Italian salad","serves":4,"items":[{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"mozzarella","plural":"mozzarella","qty":2,"unit":"","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Slice the tomatoes and the mozzarella.","timer":null},{"text":"Arrange them in alternating layers on a plate.","timer":null},{"text":"Scatter over the basil leaves.","timer":null},{"text":"Drizzle with olive oil and season with salt and pepper just before serving.","timer":null}],"variant":"The classic","change":""},{"title":"Burrata caprese","intro":"The caprese made even softer and creamier with burrata.","minutes":10,"calories":340,"difficulty":"Facile","imageSearch":"burrata tomato salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"burrata","plural":"burratas","qty":2,"unit":"","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"balsamic vinegar","plural":"balsamic vinegar","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the tomatoes into wedges and put them in a dish.","timer":null},{"text":"Place the burratas in the middle.","timer":null},{"text":"Scatter over the basil and drizzle with olive oil and balsamic vinegar.","timer":null},{"text":"Season with salt and pepper just before serving.","timer":null}],"variant":"Burrata","change":"With a creamy burrata in the middle."},{"title":"Peach caprese","intro":"A sweet and savoury summer salad with peaches and mozzarella.","minutes":10,"calories":270,"difficulty":"Facile","imageSearch":"peach mozzarella salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"peach","plural":"peaches","qty":2,"unit":"","have":false},{"name":"mozzarella","plural":"mozzarella","qty":2,"unit":"","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Slice the tomatoes, peaches and mozzarella.","timer":null},{"text":"Arrange them in alternating layers on a plate.","timer":null},{"text":"Scatter over the basil and drizzle with olive oil.","timer":null},{"text":"Season with salt and pepper.","timer":null}],"variant":"With peaches","change":"Peaches replace some of the tomatoes."}]$r$::jsonb, 'claude')
