insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:salade grecque', 'Greek salad', array['en:greek salad', 'en:horiatiki']::text[], 'dish', $r$[{"title":"Greek salad","intro":"Tomatoes, cucumber, red onion, black olives and a nice big piece of feta.","minutes":15,"calories":320,"difficulty":"Facile","imageSearch":"greek salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"Greek salad","serves":4,"items":[{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false},{"name":"feta","plural":"feta","qty":200,"unit":"g","have":false},{"name":"black olive","plural":"black olives","qty":80,"unit":"g","have":false},{"name":"oregano","plural":"oregano","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the tomatoes into wedges and the cucumber into slices.","timer":null},{"text":"Thinly slice the red onion.","timer":null},{"text":"Toss the vegetables with the olives, a little salt and the olive oil.","timer":null},{"text":"Put the feta on top in chunks and sprinkle with oregano.","timer":null}],"variant":"The classic","change":""},{"title":"Greek chickpea salad","intro":"The filling Greek salad, with chickpeas.","minutes":15,"calories":420,"difficulty":"Facile","imageSearch":"greek chickpea salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"tomato","plural":"tomatoes","qty":3,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"chickpea","plural":"chickpeas","qty":400,"unit":"g","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false},{"name":"feta","plural":"feta","qty":150,"unit":"g","have":false},{"name":"black olive","plural":"black olives","qty":60,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Rinse and drain the chickpeas.","timer":null},{"text":"Chop the tomatoes, cucumber and onion.","timer":null},{"text":"Toss with the chickpeas, olives, olive oil and the lemon juice.","timer":null},{"text":"Crumble over the feta.","timer":null}],"variant":"More filling","change":"With chickpeas to make it a meal."},{"title":"Greek chicken salad","intro":"The Greek salad as a full meal, with chicken.","minutes":25,"calories":430,"difficulty":"Facile","imageSearch":"greek chicken salad","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":3,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false},{"name":"feta","plural":"feta","qty":150,"unit":"g","have":false},{"name":"black olive","plural":"black olives","qty":60,"unit":"g","have":false},{"name":"oregano","plural":"oregano","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Season the chicken with oregano and a drizzle of oil.","timer":null},{"text":"Grill it for 6 minutes on each side, then cut into strips.","timer":{"label":"Pan","min":12}},{"text":"Chop the tomatoes, cucumber and onion.","timer":null},{"text":"Toss with the olives and olive oil, then add the chicken and feta.","timer":null}],"variant":"With chicken","change":"With oregano grilled chicken."}]$r$::jsonb, 'claude')
