insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:salade de pate', 'Pasta salad', array['en:pasta salad', 'en:cold pasta salad']::text[], 'dish', $r$[{"title":"Pasta salad","intro":"Cold pasta with cherry tomatoes, mozzarella, ham and basil.","minutes":25,"calories":480,"difficulty":"Facile","imageSearch":"pasta salad","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"short pasta","plural":"short pasta","qty":300,"unit":"g","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":250,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"balsamic vinegar","plural":"balsamic vinegar","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the pasta, then rinse it under cold water.","timer":{"label":"Cooking","min":10}},{"text":"Halve the cherry tomatoes and dice the mozzarella and ham.","timer":null},{"text":"Mix the oil and vinegar, then season with salt and pepper.","timer":null},{"text":"Toss everything together with the basil and keep in the fridge.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Tuna pasta salad","intro":"The picnic pasta salad, with tuna and sweetcorn.","minutes":25,"calories":500,"difficulty":"Facile","imageSearch":"tuna pasta salad","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"short pasta","plural":"short pasta","qty":300,"unit":"g","have":false},{"name":"tuna in brine","plural":"tuna in brine","qty":280,"unit":"g","have":false},{"name":"sweetcorn","plural":"sweetcorn","qty":140,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the pasta and rinse it under cold water.","timer":{"label":"Cooking","min":10}},{"text":"Boil the eggs for 10 minutes, peel them and chop.","timer":{"label":"Cooking","min":10}},{"text":"Dice the tomatoes and flake the tuna.","timer":null},{"text":"Toss everything together with the sweetcorn and mayonnaise.","timer":null}],"kids":true,"variant":"With tuna","change":"With tuna, sweetcorn and hard-boiled eggs."},{"title":"Pesto pasta salad","intro":"A vegetarian pasta salad, green with pesto.","minutes":20,"calories":470,"difficulty":"Facile","imageSearch":"pesto pasta salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"short pasta","plural":"short pasta","qty":300,"unit":"g","have":false},{"name":"pesto","plural":"pesto","qty":4,"unit":"tbsp","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":250,"unit":"g","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false},{"name":"rocket","plural":"rocket","qty":50,"unit":"g","have":false}],"steps":[{"text":"Cook the pasta and rinse it under cold water.","timer":{"label":"Cooking","min":10}},{"text":"Halve the cherry tomatoes.","timer":null},{"text":"Toss the pasta with the pesto and tomatoes.","timer":null},{"text":"Add the rocket and a few Parmesan shavings.","timer":null}],"kids":true,"variant":"Pesto","change":"With pesto, cherry tomatoes and Parmesan."}]$r$::jsonb, 'claude')
