insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:salade de riz', 'Rice salad', array['en:rice salad', 'en:cold rice salad', 'en:tuna rice salad']::text[], 'dish', $r$[{"title":"Tuna rice salad","intro":"Cold rice with tuna, tomatoes, sweetcorn, pepper and hard-boiled eggs.","minutes":30,"calories":450,"difficulty":"Facile","imageSearch":"rice salad tuna","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false},{"name":"tuna in brine","plural":"tuna in brine","qty":280,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"sweetcorn","plural":"sweetcorn","qty":140,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"oil","plural":"oil","qty":3,"unit":"tbsp","have":false},{"name":"vinegar","plural":"vinegar","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the rice, then rinse it under cold water.","timer":{"label":"Cooking","min":12}},{"text":"Boil the eggs for 10 minutes and cut into quarters.","timer":{"label":"Cooking","min":10}},{"text":"Dice the tomatoes and pepper, and flake the tuna.","timer":null},{"text":"Toss everything with the sweetcorn, oil and vinegar, then season with salt and pepper.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Vegetarian rice salad","intro":"A colourful rice salad, with no meat or fish.","minutes":30,"calories":400,"difficulty":"Facile","imageSearch":"vegetarian rice salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"yellow pepper","plural":"yellow peppers","qty":1,"unit":"","have":false},{"name":"feta","plural":"feta","qty":150,"unit":"g","have":false},{"name":"black olive","plural":"black olives","qty":50,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Cook the rice, then rinse it under cold water.","timer":{"label":"Cooking","min":12}},{"text":"Dice the tomatoes, cucumber and pepper.","timer":null},{"text":"Toss the rice with the vegetables, olives and crumbled feta.","timer":null},{"text":"Dress with olive oil and lemon juice.","timer":null}],"kids":true,"variant":"No fish","change":"With vegetables, feta and herbs."},{"title":"Curried chicken rice salad","intro":"A fragrant rice salad with chicken and curry.","minutes":30,"calories":480,"difficulty":"Facile","imageSearch":"curry chicken rice salad","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tsp","have":false},{"name":"raisin","plural":"raisins","qty":40,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Cook the rice, then rinse it under cold water.","timer":{"label":"Cooking","min":12}},{"text":"Fry the diced chicken in a pan for 8 minutes with 1 tsp of curry powder.","timer":{"label":"Pan","min":8}},{"text":"Mix the yoghurt with the rest of the curry powder and the lemon juice.","timer":null},{"text":"Toss the rice, chicken, diced pepper, raisins and sauce together.","timer":null}],"variant":"Curried chicken","change":"With chicken and a light curry sauce."}]$r$::jsonb, 'claude')
