insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:salade de chevre chaud', 'Warm goat''s cheese salad', array['en:warm goat s cheese salad', 'en:chevre chaud', 'en:goat s cheese toast']::text[], 'dish', $r$[{"title":"Warm goat's cheese salad","intro":"Grilled goat's cheese toasts on a green salad, with a honey dressing.","minutes":20,"calories":420,"difficulty":"Facile","imageSearch":"warm goat cheese salad","veg":true,"oven":true,"cold":false,"missing":"","origin":"French bistro dish","serves":4,"items":[{"name":"goat's cheese log","plural":"goat's cheese logs","qty":1,"unit":"","have":false},{"name":"baguette","plural":"baguettes","qty":1,"unit":"","have":false},{"name":"green salad","plural":"green salad","qty":1,"unit":"","have":false},{"name":"honey","plural":"honey","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"balsamic vinegar","plural":"balsamic vinegar","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the grill.","timer":null},{"text":"Cut the baguette into 8 slices and put a round of goat's cheese on each.","timer":null},{"text":"Grill for 5 minutes.","timer":{"label":"Oven","min":5}},{"text":"Mix the oil, vinegar and honey.","timer":null},{"text":"Serve the hot toasts on the dressed salad.","timer":null}],"variant":"The classic","change":""},{"title":"Goat's cheese with honey and walnuts","intro":"The warm goat's cheese salad made more indulgent, with honey and walnuts.","minutes":20,"calories":480,"difficulty":"Facile","imageSearch":"goat cheese toast honey walnuts","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"goat's cheese log","plural":"goat's cheese logs","qty":1,"unit":"","have":false},{"name":"baguette","plural":"baguettes","qty":1,"unit":"","have":false},{"name":"green salad","plural":"green salad","qty":1,"unit":"","have":false},{"name":"honey","plural":"honey","qty":3,"unit":"tbsp","have":false},{"name":"walnut kernel","plural":"walnut kernels","qty":50,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the grill.","timer":null},{"text":"Put rounds of goat's cheese on slices of baguette and drizzle with a little honey.","timer":null},{"text":"Grill for 5 minutes.","timer":{"label":"Oven","min":5}},{"text":"Serve on the dressed salad, sprinkle with walnuts and drizzle with the rest of the honey.","timer":null}],"variant":"Honey and walnuts","change":"The toasts are drizzled with honey and sprinkled with walnuts."},{"title":"Goat's cheese with bacon","intro":"The warm goat's cheese salad as a main course, with bacon.","minutes":25,"calories":560,"difficulty":"Facile","imageSearch":"goat cheese salad bacon","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"goat's cheese log","plural":"goat's cheese logs","qty":1,"unit":"","have":false},{"name":"baguette","plural":"baguettes","qty":1,"unit":"","have":false},{"name":"green salad","plural":"green salad","qty":1,"unit":"","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":150,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"balsamic vinegar","plural":"balsamic vinegar","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the grill.","timer":null},{"text":"Fry the bacon lardons until golden.","timer":{"label":"Pan","min":5}},{"text":"Put rounds of goat's cheese on the baguette and grill for 5 minutes.","timer":{"label":"Oven","min":5}},{"text":"Serve the toasts on the dressed salad, with the hot bacon.","timer":null}],"variant":"With bacon","change":"With fried bacon lardons on the salad."}]$r$::jsonb, 'claude')
