insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:carotte rapee', 'Grated carrot salad', array['en:grated carrot salad', 'en:carrot salad']::text[], 'dish', $r$[{"title":"Grated carrot salad","intro":"The everyday starter: grated carrots with a lemon dressing and parsley.","minutes":15,"calories":110,"difficulty":"Facile","imageSearch":"grated carrot salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"carrot","plural":"carrots","qty":6,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Peel and finely grate the carrots.","timer":null},{"text":"Mix the lemon juice, mustard, oil and a little salt.","timer":null},{"text":"Pour this dressing over the carrots.","timer":null},{"text":"Add the chopped parsley and keep in the fridge.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Orange grated carrot salad","intro":"A sweet, fruity grated carrot salad that kids love.","minutes":15,"calories":120,"difficulty":"Facile","imageSearch":"carrot orange salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"carrot","plural":"carrots","qty":6,"unit":"","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Peel and grate the carrots.","timer":null},{"text":"Squeeze the orange and mix its juice with the oil and a little salt.","timer":null},{"text":"Pour over the carrots and toss.","timer":null},{"text":"Leave in the fridge for 15 minutes before serving.","timer":null}],"kids":true,"variant":"With orange","change":"With orange juice in the dressing."},{"title":"Cumin grated carrot salad","intro":"Grated carrots flavoured with cumin, Moroccan style.","minutes":15,"calories":150,"difficulty":"Facile","imageSearch":"moroccan carrot salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"Moroccan-inspired","serves":4,"items":[{"name":"carrot","plural":"carrots","qty":6,"unit":"","have":false},{"name":"raisin","plural":"raisins","qty":40,"unit":"g","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Peel and grate the carrots.","timer":null},{"text":"Mix the lemon juice, oil and cumin.","timer":null},{"text":"Add the raisins and the chopped coriander.","timer":null},{"text":"Toss and leave in the fridge for 15 minutes.","timer":null}],"variant":"Moroccan-style","change":"With cumin and raisins."}]$r$::jsonb, 'claude')
