insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:celeri remoulade', 'Celeriac remoulade', array['en:celeriac remoulade', 'en:celery root remoulade']::text[], 'dish', $r$[{"title":"Celeriac remoulade","intro":"Grated celeriac in a punchy mustardy remoulade sauce.","minutes":15,"calories":180,"difficulty":"Facile","imageSearch":"celeriac remoulade","veg":true,"oven":false,"cold":true,"missing":"","origin":"French starter","serves":4,"items":[{"name":"celeriac","plural":"celeriacs","qty":1,"unit":"","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":4,"unit":"tbsp","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Peel the celeriac and grate it finely.","timer":null},{"text":"Sprinkle it straight away with the lemon juice so it does not go brown.","timer":null},{"text":"Mix the mayonnaise and mustard, then season with salt and pepper.","timer":null},{"text":"Toss the celeriac with the sauce and keep in the fridge.","timer":null}],"variant":"The classic","change":""},{"title":"Apple celeriac remoulade","intro":"A fresher celeriac remoulade, with apple.","minutes":15,"calories":170,"difficulty":"Facile","imageSearch":"celeriac apple slaw","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"celeriac","plural":"celeriacs","qty":1,"unit":"","have":false},{"name":"green apple","plural":"green apples","qty":1,"unit":"","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":4,"unit":"tbsp","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Peel and grate the celeriac and apple, then sprinkle with the lemon juice.","timer":null},{"text":"Mix the mayonnaise and mustard.","timer":null},{"text":"Toss everything together, then season with salt and pepper.","timer":null},{"text":"Keep in the fridge.","timer":null}],"variant":"With apple","change":"With a grated green apple."},{"title":"Yoghurt celeriac remoulade","intro":"A lighter celeriac remoulade that is still just as creamy.","minutes":15,"calories":110,"difficulty":"Facile","imageSearch":"light celeriac remoulade","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"celeriac","plural":"celeriacs","qty":1,"unit":"","have":false},{"name":"greek yoghurt","plural":"greek yoghurts","qty":1,"unit":"","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":2,"unit":"tbsp","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Peel and grate the celeriac, then sprinkle with the lemon juice.","timer":null},{"text":"Mix the yoghurt, mayonnaise and mustard.","timer":null},{"text":"Toss with the celeriac, then season with salt and pepper.","timer":null},{"text":"Keep in the fridge.","timer":null}],"variant":"Lighter","change":"Yoghurt replaces half the mayonnaise."}]$r$::jsonb, 'claude')
