insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:salade de pomme de terre', 'Potato salad', array['en:potato salad', 'en:piemontaise', 'en:german potato salad']::text[], 'dish', $r$[{"title":"Potato salad","intro":"Warm potatoes, a shallot dressing and lots of chives.","minutes":30,"calories":280,"difficulty":"Facile","imageSearch":"potato salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"chives","plural":"chives","qty":null,"unit":"","have":false},{"name":"oil","plural":"oil","qty":4,"unit":"tbsp","have":false},{"name":"vinegar","plural":"vinegar","qty":2,"unit":"tbsp","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Boil the potatoes in salted water for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Peel them while still warm and cut into slices.","timer":null},{"text":"Mix the mustard, vinegar, oil and chopped shallot.","timer":null},{"text":"Pour over the potatoes while still warm and sprinkle with chives.","timer":null}],"variant":"The classic","change":""},{"title":"Piedmontese potato salad","intro":"The complete potato salad of summer meals.","minutes":35,"calories":420,"difficulty":"Facile","imageSearch":"piemontaise potato salad","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"gherkin","plural":"gherkins","qty":8,"unit":"","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Boil the potatoes in salted water for 20 minutes, then dice them.","timer":{"label":"Cooking","min":20}},{"text":"Boil the eggs for 10 minutes and chop them.","timer":{"label":"Cooking","min":10}},{"text":"Dice the ham, tomatoes and gherkins.","timer":null},{"text":"Toss everything with the mayonnaise and keep in the fridge.","timer":null}],"kids":true,"variant":"Piémontaise","change":"With ham, eggs, tomatoes, gherkins and mayonnaise."},{"title":"Bacon potato salad","intro":"A warm potato salad, German style.","minutes":30,"calories":420,"difficulty":"Facile","imageSearch":"german potato salad bacon","veg":false,"oven":false,"cold":false,"missing":"","origin":"German-inspired","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":150,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vinegar","plural":"vinegar","qty":3,"unit":"tbsp","have":false},{"name":"oil","plural":"oil","qty":2,"unit":"tbsp","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false},{"name":"chives","plural":"chives","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes in salted water for 20 minutes, then cut into slices.","timer":{"label":"Cooking","min":20}},{"text":"Fry the bacon lardons and sliced onion until golden.","timer":{"label":"Pan","min":6}},{"text":"Deglaze the pan with the vinegar, then add the oil and mustard.","timer":null},{"text":"Pour over the warm potatoes and sprinkle with chives.","timer":null}],"variant":"With bacon","change":"With fried bacon lardons and onions."}]$r$::jsonb, 'claude')
