insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:salade de quinoa', 'Quinoa salad', array['en:quinoa salad', 'en:quinoa bowl', 'en:quinoa tabbouleh']::text[], 'dish', $r$[{"title":"Quinoa salad","intro":"Quinoa with cucumber, tomatoes, feta and herbs, a bit like a tabbouleh.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"quinoa salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":250,"unit":"g","have":false},{"name":"feta","plural":"feta","qty":150,"unit":"g","have":false},{"name":"fresh mint","plural":"fresh mint","qty":null,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Rinse the quinoa, then cook it in salted water for 12 minutes. Drain and leave to cool.","timer":{"label":"Cooking","min":12}},{"text":"Dice the cucumber and halve the tomatoes.","timer":null},{"text":"Toss with the quinoa, the crumbled feta and the chopped mint.","timer":null},{"text":"Dress with lemon juice and olive oil.","timer":null}],"variant":"The classic","change":""},{"title":"Avocado quinoa salad","intro":"A Mexican-style quinoa salad, filling and vegan.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"quinoa avocado black bean salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"Mexican-inspired","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"avocado","plural":"avocados","qty":2,"unit":"","have":false},{"name":"kidney bean","plural":"kidney beans","qty":250,"unit":"g","have":false},{"name":"sweetcorn","plural":"sweetcorn","qty":140,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the quinoa for 12 minutes, drain and leave to cool.","timer":{"label":"Cooking","min":12}},{"text":"Rinse the kidney beans and sweetcorn.","timer":null},{"text":"Dice the avocados and sprinkle with lime juice.","timer":null},{"text":"Toss everything together with the coriander, oil and the rest of the juice.","timer":null}],"variant":"Avocado","change":"With avocado, sweetcorn and kidney beans."},{"title":"Chicken quinoa salad","intro":"The quinoa salad as a full meal, with chicken.","minutes":30,"calories":470,"difficulty":"Facile","imageSearch":"quinoa chicken salad","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":250,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the quinoa for 12 minutes, drain and leave to cool.","timer":{"label":"Cooking","min":12}},{"text":"Grill the chicken for 6 minutes on each side and cut into strips.","timer":{"label":"Pan","min":12}},{"text":"Chop the cucumber and tomatoes.","timer":null},{"text":"Toss everything with the lemon juice and oil.","timer":null}],"variant":"With chicken","change":"With grilled chicken and raw vegetables."}]$r$::jsonb, 'claude')
