insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:coleslaw', 'Coleslaw', array['en:cabbage salad', 'en:cole slaw']::text[], 'dish', $r$[{"title":"Coleslaw","intro":"The American salad of white cabbage and carrots in a creamy dressing.","minutes":15,"calories":190,"difficulty":"Facile","imageSearch":"coleslaw","veg":true,"oven":false,"cold":true,"missing":"","origin":"American recipe","serves":4,"items":[{"name":"white cabbage","plural":"white cabbages","qty":0.5,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":4,"unit":"tbsp","have":false},{"name":"cider vinegar","plural":"cider vinegar","qty":1,"unit":"tbsp","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Slice the cabbage very finely.","timer":null},{"text":"Grate the carrots.","timer":null},{"text":"Mix the mayonnaise, vinegar, sugar and a little salt.","timer":null},{"text":"Toss everything together and leave in the fridge for 30 minutes.","timer":null}],"variant":"The classic","change":""},{"title":"Yoghurt coleslaw","intro":"A light, crunchy coleslaw.","minutes":15,"calories":100,"difficulty":"Facile","imageSearch":"yogurt coleslaw","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"white cabbage","plural":"white cabbages","qty":0.5,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"greek yoghurt","plural":"greek yoghurts","qty":1,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Finely slice the cabbage and grate the carrots.","timer":null},{"text":"Mix the yoghurt, mustard and the lemon juice.","timer":null},{"text":"Toss everything together, then season with salt and pepper.","timer":null},{"text":"Leave in the fridge for 15 minutes.","timer":null}],"variant":"Lighter","change":"The dressing is made with yoghurt."},{"title":"Asian-style cabbage salad","intro":"A crunchy cabbage salad with Asian flavours.","minutes":15,"calories":150,"difficulty":"Facile","imageSearch":"asian cabbage slaw","veg":true,"oven":false,"cold":true,"missing":"","origin":"Asian-inspired","serves":4,"items":[{"name":"red cabbage","plural":"red cabbages","qty":0.5,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false},{"name":"sesame oil","plural":"sesame oil","qty":1,"unit":"tbsp","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Finely slice the cabbage and grate the carrots.","timer":null},{"text":"Mix the soy sauce, sesame oil and the lime juice.","timer":null},{"text":"Toss everything with the dressing.","timer":null},{"text":"Sprinkle with sesame seeds.","timer":null}],"variant":"Asian","change":"With a soy, sesame and lime dressing."}]$r$::jsonb, 'claude')
