 with the lime juice.","timer":null},{"text":"Add the finely diced mango and the chopped onion.","timer":null},{"text":"Add the chopped coriander and season with salt.","timer":null},{"text":"Mix and serve cold.","timer":null}],"variant":"Mango","change":"With diced mango."},{"title":"Pea guacamole","intro":"A lighter guacamole that is just as green.","minutes":15,"calories":120,"difficulty":"Facile","imageSearch":"pea guacamole","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"frozen pea","plural":"frozen peas","qty":200,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":0.5,"unit":"","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the peas for 5 minutes and cool them under cold water.","timer":{"label":"Cooking","min":5}},{"text":"Roughly blend them with the avocado and the lime juice.","timer":null},{"text":"Add the chopped onion and the coriander.","timer":null},{"text":"Season with salt and serve cold.","timer":null}],"variant":"Lighter","change":"Half the avocados are replaced with peas."}]$r$::jsonb, 'claude')
