"have":false}],"steps":[{"text":"Grate the cucumber, salt it and squeeze out the water.","timer":null},{"text":"Mix it with the yoghurt and crushed garlic.","timer":null},{"text":"Add the chopped mint and the lemon juice.","timer":null},{"text":"Keep in the fridge until serving.","timer":null}],"variant":"Mint","change":"Mint replaces the dill."},{"title":"Beetroot tzatziki","intro":"A colourful version of tzatziki, with beetroot.","minutes":15,"calories":120,"difficulty":"Facile","imageSearch":"beet tzatziki","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"greek yoghurt","plural":"greek yoghurts","qty":2,"unit":"","have":false},{"name":"cooked beetroot","plural":"cooked beetroots","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Grate the beetroot.","timer":null},{"text":"Mix it into the yoghurt with the crushed garlic.","timer":null},{"text":"Add the chopped dill and the lemon juice, then season with salt.","timer":null},{"text":"Keep in the fridge.","timer":null}],"variant":"Beetroot","change":"With grated beetroot, for a pink dip."}]$r$::jsonb, 'claude')
