insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:nem', 'Nems', array['en:pork spring roll', 'en:vietnamese spring roll', 'en:fried spring roll']::text[], 'dish', $r$[{"title":"Pork nems","intro":"Crispy fried rolls filled with pork, vermicelli and wood ear mushrooms.","minutes":60,"calories":350,"difficulty":"Difficile","imageSearch":"vietnamese spring rolls nem","veg":false,"oven":false,"cold":false,"missing":"","origin":"Vietnamese recipe","serves":4,"items":[{"name":"rice paper sheet","plural":"rice paper sheets","qty":16,"unit":"","have":false},{"name":"minced pork","plural":"minced pork","qty":300,"unit":"g","have":false},{"name":"rice vermicelli","plural":"rice vermicelli","qty":50,"unit":"g","have":false},{"name":"dried wood ear mushroom","plural":"dried wood ear mushrooms","qty":10,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"fish sauce","plural":"fish sauce","qty":2,"unit":"tbsp","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false},{"name":"green salad","plural":"green salad","qty":1,"unit":"","have":false}],"steps":[{"text":"Soak the vermicelli and mushrooms in hot water for 10 minutes, then chop them.","timer":null},{"text":"Mix the pork, vermicelli, mushrooms, grated carrot, egg and fish sauce.","timer":null},{"text":"Dampen a rice paper sheet, put a spoonful of filling on it, fold in the edges and roll up tightly.","timer":null},{"text":"Fry the nems in hot oil for 6 minutes, until golden.","timer":{"label":"Frying","min":6}},{"text":"Serve with lettuce leaves, mint and fish sauce.","timer":null}],"makes":{"n":16,"one":"spring roll","many":"spring rolls"},"variant":"The classic","change":""},{"title":"Chicken nems","intro":"Crispy nems filled with chicken.","minutes":60,"calories":330,"difficulty":"Difficile","imageSearch":"chicken spring rolls","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rice paper sheet","plural":"rice paper sheets","qty":16,"unit":"","have":false},{"name":"minced chicken","plural":"minced chicken","qty":300,"unit":"g","have":false},{"name":"rice vermicelli","plural":"rice vermicelli","qty":50,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Soak the vermicelli in hot water for 10 minutes, then chop them.","timer":null},{"text":"Mix the chicken, vermicelli, grated carrot, chopped onion, egg and soy sauce.","timer":null},{"text":"Roll the filling up in the dampened rice paper sheets.","timer":null},{"text":"Fry for 6 minutes in hot oil.","timer":{"label":"Frying","min":6}}],"makes":{"n":16,"one":"spring roll","many":"spring rolls"},"variant":"With chicken","change":"Chicken replaces the pork."},{"title":"Baked vegetable nems","intro":"Lighter nems with vegetables and no frying.","minutes":50,"calories":220,"difficulty":"Moyen","imageSearch":"baked vegetable spring rolls","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rice paper sheet","plural":"rice paper sheets","qty":16,"unit":"","have":false},{"name":"rice vermicelli","plural":"rice vermicelli","qty":50,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"chinese cabbage","plural":"chinese cabbages","qty":0.25,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":150,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"oil","plural":"oil","qty":2,"unit":"tbsp","have":false}],"steps"