insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:rouleau de printemp', 'Spring rolls', array['en:spring roll', 'en:fresh spring roll', 'en:summer roll', 'en:rice paper roll']::text[], 'dish', $r$[{"title":"Prawn spring rolls","intro":"Rice paper rolled up with prawns, vermicelli, lettuce and mint, with no cooking.","minutes":30,"calories":220,"difficulty":"Moyen","imageSearch":"fresh spring rolls shrimp","veg":false,"oven":false,"cold":true,"missing":"","origin":"Vietnamese recipe","serves":4,"items":[{"name":"rice paper sheet","plural":"rice paper sheets","qty":8,"unit":"","have":false},{"name":"cooked prawn","plural":"cooked prawns","qty":16,"unit":"","have":false},{"name":"rice vermicelli","plural":"rice vermicelli","qty":80,"unit":"g","have":false},{"name":"green salad","plural":"green salad","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"fresh mint","plural":"fresh mint","qty":null,"unit":"","have":false},{"name":"hoisin sauce","plural":"hoisin sauce","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Soak the vermicelli in hot water for 5 minutes and drain them.","timer":null},{"text":"Grate the carrot and peel the prawns.","timer":null},{"text":"Dip a rice paper sheet in lukewarm water for a few seconds and lay it flat.","timer":null},{"text":"Fill with lettuce, vermicelli, carrot and mint, then 2 prawns cut in half.","timer":null},{"text":"Fold in the sides and roll up tightly. Serve with the hoisin sauce.","timer":null}],"makes":{"n":8,"one":"roll","many":"rolls"},"variant":"The classic","change":""},{"title":"Tofu spring rolls","intro":"Vegetarian fresh rolls, with golden tofu.","minutes":30,"calories":210,"difficulty":"Moyen","imageSearch":"tofu fresh spring rolls","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"rice paper sheet","plural":"rice paper sheets","qty":8,"unit":"","have":false},{"name":"firm tofu","plural":"firm tofu","qty":200,"unit":"g","have":false},{"name":"rice vermicelli","plural":"rice vermicelli","qty":80,"unit":"g","have":false},{"name":"green salad","plural":"green salad","qty":1,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"fresh mint","plural":"fresh mint","qty":null,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Cut the tofu into sticks and brown them with 1 tbsp of soy sauce.","timer":{"label":"Pan","min":6}},{"text":"Soak the vermicelli and cut the cucumber into sticks.","timer":null},{"text":"Dip a rice paper sheet in lukewarm water and fill with lettuce, vermicelli, cucumber, mint and tofu.","timer":null},{"text":"Roll up tightly and serve with the rest of the soy sauce.","timer":null}],"makes":{"n":8,"one":"roll","many":"rolls"},"variant":"Vegetarian","change":"With grilled tofu instead of prawns."},{"title":"Chicken spring rolls","intro":"Fresh chicken rolls, with a peanut sauce.","minutes":35,"calories":280,"difficulty":"Moyen","imageSearch":"chicken fresh spring rolls peanut sauce","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"rice paper sheet","plural":"rice paper sheets","qty":8,"unit":"","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"rice vermicelli","plural":"rice vermicelli","qty":80,"unit":"g","have":false},{"name":"green salad","plural":"green salad","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"peanut butter","plural":"peanut butter","qty":3,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the chicken in a pan for 10 minutes and cut it into strips.","timer":{"label":"Pan","min":10}},{"text":"Soak the vermicelli and grate the carrot.","timer":null},{"text":"Roll up the lettuce, vermicelli, carrot and chicken in the dampened rice paper sheets.","timer":null},{"text":"Mix the peanut butter, soy sauce and 3 tbsp of hot water to make the sauce.","timer":null}],"makes":{"n":8,"one":"roll","many":"rolls"},"variant":"With chicken","change":"With chicken and a peanut sauce."}]$r$::jsonb, 'claude')
