insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:samoussa', 'Samosas', array['en:samosa', 'en:beef samosa']::text[], 'dish', $r$[{"title":"Beef samosas","intro":"Crispy triangles filled with spiced minced beef and peas.","minutes":50,"calories":300,"difficulty":"Moyen","imageSearch":"beef samosas","veg":false,"oven":true,"cold":false,"missing":"","origin":"Indian and Réunion-inspired","serves":4,"items":[{"name":"brik pastry sheet","plural":"brik pastry sheets","qty":8,"unit":"","have":false},{"name":"minced beef","plural":"minced beef","qty":300,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"frozen pea","plural":"frozen peas","qty":100,"unit":"g","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"oil","plural":"oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Fry the onion, then the beef and curry powder for 8 minutes. Add the peas and coriander.","timer":{"label":"Pan","min":8}},{"text":"Cut the brik sheets in half and fold each strip into a triangle around a spoonful of filling.","timer":null},{"text":"Brush with oil and bake for 15 minutes.","timer":{"label":"Oven","min":15}}],"makes":{"n":16,"one":"samosa","many":"samosas"},"variant":"The classic","change":""},{"title":"Vegetable samosas","intro":"Vegetarian samosas with a spicy filling.","minutes":50,"calories":240,"difficulty":"Moyen","imageSearch":"vegetable samosas","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"brik pastry sheet","plural":"brik pastry sheets","qty":8,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":3,"unit":"","have":false},{"name":"frozen pea","plural":"frozen peas","qty":150,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"uni