l},{"text":"Season with salt and pepper.","timer":null},{"text":"Fry small spoonfuls of batter for 3 minutes.","timer":{"label":"Frying","min":3}}],"makes":{"n":20,"one":"saltfish fritter","many":"saltfish fritters"},"variant":"Vegetarian","change":"With grated vegetables instead of fish."}]$r$::jsonb, 'claude')
