insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gougere', 'Gougères', array['en:cheese puff', 'en:french cheese puff']::text[], 'dish', $r$[{"title":"Comté gougères","intro":"Little golden, fluffy cheese puffs for nibbles.","minutes":50,"calories":180,"difficulty":"Moyen","imageSearch":"gougeres cheese puffs","veg":true,"oven":true,"cold":false,"missing":"","origin":"Burgundy speciality","serves":4,"items":[{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":70,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"grated comté","plural":"grated comté","qty":100,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Bring 15 cl of water, the butter and a pinch of salt to the boil.","timer":null},{"text":"Add the flour all at once and stir until the dough comes away from the pan.","timer":null},{"text":"Off the heat, beat in the eggs one at a time, then three quarters of the comté and some pepper.","timer":null},{"text":"Spoon small mounds onto a baking tray and sprinkle with the rest of the comté.","timer":null},{"text":"Bake for 20 minutes without opening the oven.","timer":{"label":"Oven","min":20}}],"makes":{"n":30,"one":"gougère","many":"gougères"},"variant":"The classic","change":""},{"title":"Ham gougères","intro":"Richer gougères, with cheese and ham.","minutes":50,"calories":200,"difficulty":"Moyen","imageSearch":"ham cheese puffs","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":70,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false},{"name":"cooked ham","plural":"cooked ham","qty":2,"unit":"slices","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C and make the choux pastry: bring the water, butter and salt to the boil, then add the flour and the eggs one at a time.","timer":null},{"text":"Add the emmental and the finely diced ham.","timer":null},{"text":"Spoon small mounds onto a baking tray.","timer":null},{"text":"Bake for 20 minutes.","timer":{"label":"Oven","min":20}}],"makes":{"n":30,"one":"gougère","many":"gougères"},"variant":"With ham","change":"With finely diced ham in the dough."},{"title":"Herb gougères","intro":"Gougères flavoured with fresh herbs.","minutes":50,"calories":175,"difficulty":"Moyen","imageSearch":"herb cheese puffs","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":70,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":60,"unit":"g","have":false},{"name":"chives","plural":"chives","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C and make the choux pastry.","timer":null},{"text":"Add the grated Parmesan and the chopped chives.","timer":null},{"text":"Spoon small mounds onto a baking tray.","timer":null},{"text":"Bake for 20 minutes.","timer":{"label":"Oven","min":20}}],"makes":{"n":30,"one":"gougère","many":"gougères"},"variant":"With herbs","change":"With chives and Parmesan."}]$r$::jsonb, 'claude')
