insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:soupe miso', 'Miso soup', array['en:miso soup', 'en:tofu miso soup']::text[], 'dish', $r$[{"title":"Tofu miso soup","intro":"The Japanese miso broth, with tofu, seaweed and spring onion.","minutes":15,"calories":120,"difficulty":"Facile","imageSearch":"miso soup tofu","veg":true,"oven":false,"cold":false,"missing":"","origin":"Japanese recipe","serves":4,"items":[{"name":"miso paste","plural":"miso paste","qty":4,"unit":"tbsp","have":false},{"name":"silken tofu","plural":"silken tofu","qty":200,"unit":"g","have":false},{"name":"wakame seaweed","plural":"wakame seaweed","qty":5,"unit":"g","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false}],"steps":[{"text":"Soak the seaweed in cold water for 5 minutes.","timer":null},{"text":"Bring 1 litre of water to a simmer, without letting it boil.","timer":null},{"text":"Dissolve the miso in a ladle of hot water and pour it into the pan.","timer":null},{"text":"Add the diced tofu, the drained seaweed and the sliced spring onion.","timer":null},{"text":"Serve straight away, without letting the miso boil.","timer":null}],"variant":"The classic","change":""},{"title":"Miso noodle soup","intro":"A filling miso soup, with udon noodles.","minutes":20,"calories":350,"difficulty":"Facile","imageSearch":"miso noodle soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"miso paste","plural":"miso paste","qty":4,"unit":"tbsp","have":false},{"name":"udon noodle","plural":"udon noodles","qty":400,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":150,"unit":"g","have":false},{"name":"baby spinach","plural":"baby spinach","qty":100,"unit":"g","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false}],"steps":[{"text":"Bring 1.2 litres of water to a simmer with the sliced mushrooms.","timer":{"label":"Cooking","min":5}},{"text":"Add the noodles and cook following the packet instructions.","timer":null},{"text":"Dissolve the miso in a ladle of broth and stir it in.","timer":null},{"text":"Add the spinach and sliced spring onion, and serve at once.","timer":null}],"variant":"With noodles","change":"With noodles and mushrooms to make it a meal."},{"title":"Salmon miso soup","intro":"A heartier miso soup, with salmon.","minutes":20,"calories":230,"difficulty":"Facile","imageSearch":"salmon miso soup","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"miso paste","plural":"miso paste","qty":4,"unit":"tbsp","have":false},{"name":"salmon fillet","plural":"salmon fillets","qty":2,"unit":"","have":false},{"name":"silken tofu","plural":"silken tofu","qty":150,"unit":"g","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false},{"name":"wakame seaweed","plural":"wakame seaweed","qty":5,"unit":"g","have":false}],"steps":[{"text":"Soak the seaweed for 5 minutes.","timer":null},{"text":"Bring 1 litre of water to a simmer and poach the diced salmon for 4 minutes.","timer":{"label":"Cooking","min":4}},{"text":"Dissolve the miso in a ladle of broth and stir it in.","timer":null},{"text":"Add the tofu, seaweed and spring onion, then serve.","timer":null}],"variant":"With salmon","change":"With diced salmon poached in the broth."}]$r$::jsonb, 'claude')
