insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:veloute de brocoli', 'Broccoli soup', array['en:broccoli soup', 'en:cream of broccoli soup', 'en:broccoli veloute']::text[], 'dish', $r$[{"title":"Broccoli soup","intro":"A smooth, mild green soup, with a potato to make it creamy.","minutes":30,"calories":150,"difficulty":"Facile","imageSearch":"broccoli soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"broccoli","plural":"broccolis","qty":1,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the sliced onion in a saucepan.","timer":null},{"text":"Add the broccoli florets, the diced potato, the stock cube and 80 cl of water.","timer":null},{"text":"Simmer for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Blend with the crème fraîche, then season with salt and pepper.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Cheesy broccoli soup","intro":"The creamy broccoli soup with cheddar that kids love.","minutes":30,"calories":250,"difficulty":"Facile","imageSearch":"broccoli cheddar soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"broccoli","plural":"broccolis","qty":1,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"grated cheddar","plural":"grated cheddar","qty":100,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false}],"steps":[{"text":"Fry the onion, then add the broccoli, potato, stock cube and 60 cl of water.","timer":null},{"text":"Simmer for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Blend with the milk.","timer":null},{"text":"Add the cheddar and stir until it melts.","timer":null}],"kids":true,"variant":"With cheese","change":"With melted cheddar."},{"title":"Coconut broccoli soup","intro":"A vegan soup flavoured with ginger and coconut milk.","minutes":30,"calories":200,"difficulty":"Facile","imageSearch":"broccoli coconut soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"broccoli","plural":"broccolis","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"coconut milk","plural":"coconut milk","qty":20,"unit":"cl","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false}],"steps":[{"text":"Fry the onion and ginger.","timer":null},{"text":"Add the broccoli, the stock cube and 70 cl of water, and simmer for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Blend with the coconut milk.","timer":null},{"text":"Season with salt and pepper.","timer":null}],"variant":"Coconut","change":"With coconut milk and ginger."}]$r$::jsonb, 'claude')
