insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:soupe de poi casse', 'Split pea soup', array['en:split pea soup', 'en:pea soup', 'en:yellow split pea soup']::text[], 'dish', $r$[{"title":"Split pea soup","intro":"The thick, comforting winter soup, with golden bacon lardons.","minutes":70,"calories":380,"difficulty":"Facile","imageSearch":"split pea soup","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"split pea","plural":"split peas","qty":300,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":150,"unit":"g","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Rinse the split peas.","timer":null},{"text":"Fry the onion and the sliced carrots.","timer":null},{"text":"Add the peas, the stock cube and 1.2 litres of water, and simmer for 50 minutes.","timer":{"label":"Cooking","min":50}},{"text":"Blend with the crème fraîche.","timer":null},{"text":"Fry the bacon lardons until golden and scatter them over the soup.","timer":{"label":"Pan","min":5}}],"variant":"The classic","change":""},{"title":"Vegetarian split pea soup","intro":"A vegan split pea soup flavoured with cumin.","minutes":65,"calories":300,"difficulty":"Facile","imageSearch":"vegan split pea soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"split pea","plural":"split peas","qty":300,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the onion and carrots in the oil with the cumin.","timer":null},{"text":"Add the rinsed split peas, the stock cube and 1.2 litres of water.","timer":null},{"text":"Simmer for 50 minutes.","timer":{"label":"Cooking","min":50}},{"text":"Blend, then season with salt and pepper.","timer":null}],"variant":"Vegetarian","change":"No bacon, with cumin."},{"title":"Ham split pea soup","intro":"The split pea soup as a full meal.","minutes":70,"calories":400,"difficulty":"Facile","imageSearch":"split pea ham soup","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"split pea","plural":"split peas","qty":300,"unit":"g","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"sliced white bread","plural":"sliced white bread","qty":2,"unit":"slices","have":false}],"steps":[{"text":"Fry the onion and carrots, add the rinsed peas, the stock cube and 1.2 litres of water.","timer":null},{"text":"Simmer for 50 minutes, then blend.","timer":{"label":"Cooking","min":50}},{"text":"Toast the bread and cut it into small croutons.","timer":null},{"text":"Serve with the diced ham and the croutons.","timer":null}],"variant":"With ham","change":"With diced ham and croutons."}]$r$::jsonb, 'claude')
