insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:osso buco', 'Osso buco', array['en:ossobuco', 'en:osso bucco', 'en:braised veal shank']::text[], 'dish', $r$[{"title":"Osso buco alla milanese","intro":"Slices of veal shank simmered in tomato, with a lemon gremolata.","minutes":135,"calories":480,"difficulty":"Moyen","imageSearch":"osso buco","veg":false,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"veal shank","plural":"veal shanks","qty":4,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"celery stick","plural":"celery sticks","qty":1,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":15,"unit":"cl","have":false},{"name":"flour","plural":"flour","qty":2,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false}],"steps":[{"text":"Lightly flour the slices of veal and brown them in an oiled casserole dish.","timer":{"label":"Cooking","min":8}},{"text":"Take them out and fry the diced onion, carrots and celery.","timer":null},{"text":"Put the meat back, then add the wine, tomatoes and 20 cl of water.","timer":null},{"text":"Cover and simmer gently for 1 hour 45 minutes.","timer":{"label":"Cooking","min":105}},{"text":"Chop the parsley with the garlic and the lemon zest: this is the gremolata.","timer":null},{"text":"Sprinkle the gremolata over the osso buco just before serving.","timer":null}],"variant":"The classic","change":""},{"title":"Turkey osso buco","intro":"The osso buco made with turkey, simmered in tomato.","minutes":85,"calories":380,"difficulty":"Facile","imageSearch":"turkey osso buco","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"turkey osso buco","plural":"turkey osso buco","qty":4,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the turkey in an oiled casserole dish.","timer":{"label":"Cooking","min":8}},{"text":"Add the diced onion and carrots and fry for 3 minutes.","timer":null},{"text":"Add the wine, tomatoes and 15 cl of water.","timer":null},{"text":"Cover and simmer for 1 hour.","timer":{"label":"Cooking","min":60}},{"text":"Sprinkle with chopped parsley and lemon zest.","timer":null}],"variant":"With turkey","change":"With turkey osso buco, which is quicker and cheaper."},{"title":"White osso buco","intro":"The old-fashioned osso buco, in a white lemon sauce.","minutes":135,"calories":450,"difficulty":"Moyen","imageSearch":"osso buco bianco","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"veal shank","plural":"veal shanks","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":25,"unit":"cl","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":1,"unit":"","have":false},{"name":"flour","plural":"flour","qty":2,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Flour the veal and brown it in a casserole dish.","timer":{"label":"Cooking","min":8}},{"text":"Add the onion and carrots, then the wine, stock cube and 20 cl of water.","timer":null},{"text":"Cover and simmer for 1 hour 45 minutes.","timer":{"label":"Cooking","min":105}},{"text":"Add the lemon zest and juice and the chopped parsley before serving.","timer":null}],"variant":"No tomato","change":"Simmered in white wine and stock, with no tomato."}]$r$::jsonb, 'claude')
