insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:parmentier de canard', 'Duck parmentier', array['en:duck parmentier', 'en:duck confit shepherd s pie', 'en:duck hachi parmentier']::text[], 'dish', $r$[{"title":"Duck parmentier","intro":"Shredded duck confit under homemade mash, baked until golden.","minutes":75,"calories":620,"difficulty":"Moyen","imageSearch":"duck parmentier","veg":false,"oven":true,"cold":false,"missing":"","origin":"South-West French dish","serves":4,"items":[{"name":"duck confit leg","plural":"duck confit legs","qty":3,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Boil the potatoes in salted water for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Warm the duck legs, remove the skin and shred the meat.","timer":null},{"text":"Fry the shallots in 1 tbsp of duck fat, then add the duck and parsley.","timer":null},{"text":"Mash the potatoes with the milk and butter.","timer":null},{"text":"Preheat the oven to 200 °C. Put the duck in a dish and cover with the mash and breadcrumbs.","timer":null},{"text":"Bake for 20 minutes.","timer":{"label":"Oven","min":20}}],"variant":"The classic","change":""},{"title":"Sweet potato duck parmentier","intro":"A sweet and savoury parmentier, with orange mash.","minutes":75,"calories":600,"difficulty":"Moyen","imageSearch":"duck sweet potato parmentier","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"duck confit leg","plural":"duck confit legs","qty":3,"unit":"","have":false},{"name":"sweet potato","plural":"sweet potatoes","qty":2,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":500,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the sweet potatoes and potatoes, cut into pieces, for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Shred the duck without the skin and fry it with the shallots and parsley.","timer":null},{"text":"Mash the vegetables with the butter.","timer":null},{"text":"Layer the parmentier in a dish and bake for 20 minutes at 200 °C.","timer":{"label":"Oven","min":20}}],"variant":"Sweet potato","change":"The mash is half sweet potato."},{"title":"Chicken parmentier","intro":"The chicken parmentier, great for using up a roast chicken.","minutes":60,"calories":450,"difficulty":"Facile","imageSearch":"chicken parmentier","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cooked chicken","plural":"cooked chicken","qty":400,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"grated emmental","plural":"grated emmental","qty":60,"unit":"g","have":false}],"steps":[{"text":"Boil the potatoes for 20 minutes and mash them with the milk and butter.","timer":{"label":"Cooking","min":20}},{"text":"Shred the chicken and fry it with the onion.","timer":null},{"text":"Layer in a dish: the chicken first, then the mash and emmental.","timer":null},{"text":"Bake for 20 minutes at 200 °C.","timer":{"label":"Oven","min":20}}],"kids":true,"variant":"With chicken","change":"Roast chicken replaces the duck, for a lighter dish."}]$r$::jsonb, 'claude')
