insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:magret de canard', 'Duck breast', array['en:duck breast', 'en:pan fried duck breast', 'en:magret']::text[], 'dish', $r$[{"title":"Pan-fried duck breast","intro":"Duck breast seared skin-side down and pink in the middle, with potatoes sautéed in its fat.","minutes":40,"calories":650,"difficulty":"Moyen","imageSearch":"seared duck breast","veg":false,"oven":false,"cold":false,"missing":"","origin":"South-West French dish","serves":4,"items":[{"name":"duck breast","plural":"duck breasts","qty":2,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Score the skin of the duck breasts without cutting into the meat.","timer":null},{"text":"Cook them skin-side down for 8 minutes over a medium heat, pouring off the fat as you go.","timer":{"label":"Pan","min":8}},{"text":"Turn them over for 4 minutes, then rest for 5 minutes under foil.","timer":{"label":"Pan","min":4}},{"text":"Sauté the diced potatoes in the fat for 20 minutes.","timer":{"label":"Pan","min":20}},{"text":"Add the chopped garlic and parsley, and serve with the sliced duck.","timer":null}],"variant":"The classic","change":""},{"title":"Honey duck breast","intro":"The sweet and savoury duck breast, glazed with honey.","minutes":30,"calories":600,"difficulty":"Moyen","imageSearch":"honey glazed duck breast","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"duck breast","plural":"duck breasts","qty":2,"unit":"","have":false},{"name":"honey","plural":"honey","qty":3,"unit":"tbsp","have":false},{"name":"balsamic vinegar","plural":"balsamic vinegar","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Score the skin and cook skin-side down for 8 minutes, pouring off the fat as you go.","timer":{"label":"Pan","min":8}},{"text":"Turn over and cook for 4 minutes.","timer":{"label":"Pan","min":4}},{"text":"Pour off the fat, add the honey and vinegar and glaze the duck for 1 minute.","timer":null},{"text":"Rest for 5 minutes, slice and spoon over the sauce.","timer":null}],"variant":"With honey","change":"Glazed with a honey and vinegar sauce."},{"title":"Orange duck breast","intro":"The great classic duck à l'orange, made with duck breast.","minutes":35,"calories":600,"difficulty":"Moyen","imageSearch":"duck breast orange sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"duck breast","plural":"duck breasts","qty":2,"unit":"","have":false},{"name":"orange","plural":"oranges","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tbsp","have":false},{"name":"vinegar","plural":"vinegar","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the duck breasts for 8 minutes skin-side down and 4 minutes meat-side down, then rest.","timer":{"label":"Pan","min":12}},{"text":"Caramelise the sugar with the vinegar.","timer":null},{"text":"Add the juice of 2 oranges and the zest of one, and reduce for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Serve the sliced duck with the sauce and wedges of the last orange.","timer":null}],"variant":"With orange","change":"With an orange sauce."}]$r$::jsonb, 'claude')
