insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poulet au citron', 'Lemon chicken', array['en:lemon chicken', 'en:chicken with lemon', 'en:lemon and thyme chicken']::text[], 'dish', $r$[{"title":"Lemon and thyme chicken","intro":"Chicken thighs roasted with lemon, garlic and thyme.","minutes":60,"calories":450,"difficulty":"Facile","imageSearch":"lemon chicken thighs","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":4,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":4,"unit":"clove","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"potato","plural":"potatoes","qty":600,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Cut the potatoes into wedges and one lemon into slices.","timer":null},{"text":"Put everything in a dish with the chicken, garlic, thyme, oil and the juice of the other lemon.","timer":null},{"text":"Bake for 45 minutes, basting from time to time.","timer":{"label":"Oven","min":45}}],"variant":"The classic","change":""},{"title":"Chinese-style lemon chicken","intro":"The lemon chicken from the Chinese takeaway, crispy and glazed.","minutes":30,"calories":480,"difficulty":"Moyen","imageSearch":"chinese lemon chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Chinese-inspired","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"cornflour","plural":"cornflour","qty":4,"unit":"tbsp","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":3,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":1,"unit":"tbsp","have":false},{"name":"oil","plural":"oil","qty":5,"unit":"tbsp","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Cut the chicken into pieces, dip them in the beaten egg, then in 3 tbsp of cornflour.","timer":null},{"text":"Fry them for 6 minutes in hot oil until golden.","timer":{"label":"Pan","min":6}},{"text":"Heat the lemon juice, sugar, soy sauce and the rest of the cornflour mixed with 10 cl of water until thickened.","timer":null},{"text":"Coat the chicken in the sauce and serve with the rice.","timer":null}],"variant":"Chinese-style","change":"Fried chicken pieces in a lemon sauce."},{"title":"Chicken tagine with preserved lemon","intro":"Moroccan-style chicken, tender and fragrant.","minutes":70,"calories":430,"difficulty":"Facile","imageSearch":"chicken preserved lemon olives","veg":false,"oven":false,"cold":false,"missing":"","origin":"Moroccan-inspired","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":4,"unit":"","have":false},{"name":"preserved lemon","plural":"preserved lemons","qty":2,"unit":"","have":false},{"name":"green olive","plural":"green olives","qty":100,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"turmeric","plural":"turmeric","qty":1,"unit":"tsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken in an oiled casserole dish.","timer":{"label":"Cooking","min":8}},{"text":"Add the sliced onions, ginger and turmeric.","timer":null},{"text":"Add 30 cl of water, cover and simmer for 40 minutes.","timer":{"label":"Cooking","min":40}},{"text":"Add the preserved lemons, cut into quarters, and the olives, and cook for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Sprinkle with coriander.","timer":null}],"variant":"Preserved lemon","change":"Simmered with olives and preserved lemon."}]$r$::jsonb, 'claude')
