insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:aile de poulet', 'Chicken wings', array['en:chicken wing', 'en:wing', 'en:baked chicken wing', 'en:marinated chicken wing']::text[], 'dish', $r$[{"title":"Baked marinated chicken wings","intro":"Chicken wings marinated in paprika and honey, roasted until sticky.","minutes":60,"calories":420,"difficulty":"Facile","imageSearch":"baked chicken wings","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken wing","plural":"chicken wings","qty":1000,"unit":"g","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"paprika","plural":"paprika","qty":2,"unit":"tsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"oil","plural":"oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Mix the honey, soy sauce, paprika, crushed garlic and oil.","timer":null},{"text":"Coat the wings in this marinade and leave in the fridge for 30 minutes.","timer":{"label":"Rest","min":30}},{"text":"Preheat the oven to 220 °C.","timer":null},{"text":"Spread the wings out on a baking tray and bake for 35 minutes, turning them over halfway.","timer":{"label":"Oven","min":35}}],"kids":true,"makes":{"n":20,"one":"wing","many":"wings"},"variant":"The classic","change":""},{"title":"Buffalo chicken wings","intro":"The American chicken wings in hot sauce.","minutes":50,"calories":450,"difficulty":"Facile","imageSearch":"buffalo wings","veg":false,"oven":true,"cold":false,"missing":"","origin":"American recipe","serves":4,"items":[{"name":"chicken wing","plural":"chicken wings","qty":1000,"unit":"g","have":false},{"name":"hot sauce","plural":"hot sauce","qty":8,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"garlic powder","plural":"garlic powder","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 220 °C.","timer":null},{"text":"Season the wings with the paprika, garlic powder and salt.","timer":null},{"text":"Bake for 40 minutes, turning them over halfway.","timer":{"label":"Oven","min":40}},{"text":"Melt the butter with the hot sauce and toss the hot wings in it.","timer":null}],"makes":{"n":20,"one":"wing","many":"wings"},"variant":"Buffalo","change":"With a hot butter sauce."},{"title":"Caramel chicken wings","intro":"Sweet and savoury Vietnamese-style chicken wings.","minutes":45,"calories":430,"difficulty":"Facile","imageSearch":"caramel chicken wings","veg":false,"oven":false,"cold":false,"missing":"","origin":"Vietnamese-inspired","serves":4,"items":[{"name":"chicken wing","plural":"chicken wings","qty":1000,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":4,"unit":"tbsp","have":false},{"name":"fish sauce","plural":"fish sauce","qty":3,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false}],"steps":[{"text":"Make a brown caramel with the sugar and 2 tbsp of water.","timer":null},{"text":"Off the heat, add the fish sauce and 10 cl of water.","timer":null},{"text":"Add the wings, garlic and ginger, and simmer for 30 minutes, stirring.","timer":{"label":"Cooking","min":30}},{"text":"Reduce until the wings are glazed, then sprinkle with spring onion.","timer":null}],"makes":{"n":20,"one":"wing","many":"wings"},"variant":"Vietnamese-style","change":"Glazed with caramel and fish sauce."}]$r$::jsonb, 'claude')
