insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:rougail saucisse', 'Rougail saucisse', array['en:rougail', 'en:sausage rougail', 'en:reunion sausage stew']::text[], 'dish', $r$[{"title":"Sausage rougail","intro":"The dish from Réunion: smoked sausages simmered in a tomato sauce with ginger and chilli.","minutes":50,"calories":620,"difficulty":"Facile","imageSearch":"rougail saucisse","veg":false,"oven":false,"cold":false,"missing":"","origin":"Réunion recipe","serves":4,"items":[{"name":"smoked sausage","plural":"smoked sausages","qty":6,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":6,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"turmeric","plural":"turmeric","qty":1,"unit":"tsp","have":false},{"name":"chilli","plural":"chillies","qty":1,"unit":"","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Blanch the sausages in boiling water for 5 minutes, then slice them.","timer":{"label":"Cooking","min":5}},{"text":"Brown them in a casserole dish.","timer":null},{"text":"Add the sliced onions, garlic, ginger, turmeric and chilli.","timer":null},{"text":"Add the diced tomatoes and simmer for 25 minutes.","timer":{"label":"Simmer","min":25}},{"text":"Serve with white rice.","timer":null}],"variant":"The classic","change":""},{"title":"Prawn rougail","intro":"A lighter rougail, with prawns.","minutes":30,"calories":400,"difficulty":"Facile","imageSearch":"shrimp rougail","veg":false,"oven":false,"cold":false,"missing":"","origin":"Réunion recipe","serves":4,"items":[{"name":"peeled prawn","plural":"peeled prawns","qty":500,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":5,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"turmeric","plural":"turmeric","qty":1,"unit":"tsp","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Fry the onions, garlic, ginger and turmeric.","timer":null},{"text":"Add the diced tomatoes and simmer for 15 minutes.","timer":{"label":"Simmer","min":15}},{"text":"Add the prawns and cook for 4 minutes.","timer":{"label":"Cooking","min":4}}],"variant":"Prawns","change":"Prawns replace the sausages."},{"title":"Lentil rougail","intro":"A spicy, filling vegetarian rougail.","minutes":45,"calories":380,"difficulty":"Facile","imageSearch":"lentil tomato curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"red lentil","plural":"red lentils","qty":250,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"turmeric","plural":"turmeric","qty":1,"unit":"tsp","have":false},{"name":"rice","plural":"rice","qty":200,"unit":"g","have":false}],"steps":[{"text":"Fry the onions, garlic, ginger and turmeric.","timer":null},{"text":"Add the diced tomatoes, lentils and 50 cl of water.","timer":null},{"text":"Simmer for 20 minutes.","timer":{"label":"Simmer","min":20}},{"text":"Serve with rice.","timer":null}],"variant":"Vegetarian","change":"Lentils in a rougail sauce, with no meat."}]$r$::jsonb, 'claude')
