insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:colombo de poulet', 'Chicken colombo', array['en:chicken colombo', 'en:colombo', 'en:colombo curry', 'en:caribbean chicken curry']::text[], 'dish', $r$[{"title":"Chicken colombo","intro":"The Caribbean chicken curry, with potatoes and vegetables, flavoured with colombo spice mix.","minutes":60,"calories":480,"difficulty":"Facile","imageSearch":"chicken colombo curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"Caribbean recipe","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":4,"unit":"","have":false},{"name":"colombo spice mix","plural":"colombo spice mix","qty":2,"unit":"tbsp","have":false},{"name":"potato","plural":"potatoes","qty":3,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false}],"steps":[{"text":"Rub the chicken with the lime juice, the garlic and 1 tbsp of colombo.","timer":null},{"text":"Brown it in a casserole dish with the onions.","timer":{"label":"Cooking","min":8}},{"text":"Add the rest of the colombo, the potatoes and courgette in pieces, and 40 cl of water.","timer":null},{"text":"Cover and simmer for 40 minutes.","timer":{"label":"Simmer","min":40}}],"variant":"The classic","change":""},{"title":"Pork colombo","intro":"The Caribbean pork colombo, slowly simmered.","minutes":90,"calories":560,"difficulty":"Facile","imageSearch":"pork colombo","veg":false,"oven":false,"cold":false,"missing":"","origin":"Caribbean recipe","serves":4,"items":[{"name":"pork shoulder","plural":"pork shoulders","qty":800,"unit":"g","have":false},{"name":"colombo spice mix","plural":"colombo spice mix","qty":2,"unit":"tbsp","have":false},{"name":"potato","plural":"potatoes","qty":3,"unit":"","have":false},{"name":"aubergine","plural":"aubergines","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false}],"steps":[{"text":"Cut the pork into cubes and brown it with the onions.","timer":{"label":"Cooking","min":8}},{"text":"Add the garlic, the colombo, then 50 cl of water.","timer":null},{"text":"Simmer for 45 minutes.","timer":{"label":"Simmer","min":45}},{"text":"Add the potatoes and aubergine in pieces and cook for 25 minutes.","timer":{"label":"Cooking","min":25}}],"variant":"With pork","change":"With pork shoulder."},{"title":"Vegetable colombo","intro":"A vegetarian colombo with vegetables and chickpeas.","minutes":45,"calories":380,"difficulty":"Facile","imageSearch":"vegetable colombo curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":400,"unit":"g","have":false},{"name":"sweet potato","plural":"sweet potatoes","qty":1,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"aubergine","plural":"aubergines","qty":1,"unit":"","have":false},{"name":"colombo spice mix","plural":"colombo spice mix","qty":2,"unit":"tbsp","have":false},{"name":"coconut milk","plural":"coconut milk","qty":20,"unit":"cl","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false}],"steps":[{"text":"Fry the onion with the colombo.","timer":null},{"text":"Add the diced sweet potato, courgette and aubergine.","timer":null},{"text":"Add the coconut milk and 20 cl of water, and simmer for 25 minutes.","timer":{"label":"Simmer","min":25}},{"text":"Add the chickpeas and cook for 5 minutes.","timer":{"label":"Cooking","min":5}}],"variant":"Vegetarian","change":"Chickpeas and vegetables instead of meat."}]$r$::jsonb, 'claude')
