insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:navarin d agneau', 'Lamb navarin', array['en:lamb navarin', 'en:navarin']::text[], 'dish', $r$[{"title":"Spring lamb navarin","intro":"The lamb stew with baby spring vegetables: carrots, turnips and peas.","minutes":120,"calories":550,"difficulty":"Moyen","imageSearch":"lamb navarin stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"French dish","serves":4,"items":[{"name":"lamb shoulder","plural":"lamb shoulders","qty":1000,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":4,"unit":"","have":false},{"name":"turnip","plural":"turnips","qty":4,"unit":"","have":false},{"name":"frozen pea","plural":"frozen peas","qty":200,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":200,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":1,"unit":"tbsp","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false}],"steps":[{"text":"Cut the lamb into pieces and brown it in a casserole dish.","timer":{"label":"Cooking","min":8}},{"text":"Add the onions, sprinkle with flour and stir.","timer":null},{"text":"Add the tomatoes, bouquet garni and 50 cl of water, and simmer for 1 hour.","timer":{"label":"Simmer","min":60}},{"text":"Add the carrots and turnips in pieces, and cook for 30 minutes.","timer":{"label":"Cooking","min":30}},{"text":"Add the peas 10 minutes before the end.","timer":{"label":"Cooking","min":10}}],"variant":"The classic","change":""},{"title":"Lamb navarin with potatoes","intro":"A more family-friendly navarin, with potatoes.","minutes":120,"calories":580,"difficulty":"Moyen","imageSearch":"lamb potato stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"lamb shoulder","plural":"lamb shoulders","qty":1000,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":600,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":200,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":1,"unit":"tbsp","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the lamb pieces in a casserole dish.","timer":{"label":"Cooking","min":8}},{"text":"Add the onions, flour, tomatoes, thyme and 50 cl of water.","timer":null},{"text":"Simmer for 1 hour.","timer":{"label":"Simmer","min":60}},{"text":"Add the potatoes and carrots and cook for 30 minutes.","timer":{"label":"Cooking","min":30}}],"variant":"With potatoes","change":"With potatoes instead of turnips."},{"title":"Pressure cooker lamb navarin","intro":"The navarin made quickly for a weeknight.","minutes":50,"calories":550,"difficulty":"Facile","imageSearch":"lamb stew pressure cooker","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"lamb shoulder","plural":"lamb shoulders","qty":1000,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":4,"unit":"","have":false},{"name":"turnip","plural":"turnips","qty":3,"unit":"","have":false},{"name":"frozen pea","plural":"frozen peas","qty":200,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":200,"unit":"g","have":false}],"steps":[{"text":"Brown the lamb in the pressure cooker with the onions.","timer":{"label":"Cooking","min":8}},{"text":"Add the tomatoes, carrots, turnips and 30 cl of water.","timer":null},{"text":"Close the lid and cook for 25 minutes once it starts to hiss.","timer":{"label":"Cooking","min":25}},{"text":"Add the peas and cook for 5 minutes with the lid off.","timer":{"label":"Cooking","min":5}}],"variant":"Quick","change":"Cooked in a pressure cooker, in less time."}]$r$::jsonb, 'claude')
