insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:veau marengo', 'Veal Marengo', array['en:veal marengo', 'en:marengo', 'en:veal stew', 'en:saute de veau marengo']::text[], 'dish', $r$[{"title":"Veal Marengo","intro":"Veal stew simmered in tomato and white wine, with mushrooms.","minutes":105,"calories":450,"difficulty":"Facile","imageSearch":"veal marengo stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"French dish","serves":4,"items":[{"name":"stewing veal","plural":"stewing veal","qty":1000,"unit":"g","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":20,"unit":"cl","have":false},{"name":"flour","plural":"flour","qty":1,"unit":"tbsp","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false}],"steps":[{"text":"Brown the veal pieces in an oiled casserole dish.","timer":{"label":"Cooking","min":8}},{"text":"Add the onions, sprinkle with flour and stir.","timer":null},{"text":"Add the wine, tomatoes, bouquet garni and 20 cl of water.","timer":null},{"text":"Simmer for 1 hour 15 minutes.","timer":{"label":"Simmer","min":75}},{"text":"Add the sliced mushrooms and cook for 15 minutes.","timer":{"label":"Cooking","min":15}}],"variant":"The classic","change":""},{"title":"Chicken Marengo","intro":"The original Marengo recipe, made with chicken.","minutes":60,"calories":420,"difficulty":"Facile","imageSearch":"chicken marengo","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":4,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":15,"unit":"cl","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false}],"steps":[{"text":"Brown the chicken in a casserole dish.","timer":{"label":"Cooking","min":8}},{"text":"Add the onions and garlic, then the wine and tomatoes.","timer":null},{"text":"Simmer for 30 minutes.","timer":{"label":"Simmer","min":30}},{"text":"Add the mushrooms and cook for 15 minutes.","timer":{"label":"Cooking","min":15}}],"variant":"With chicken","change":"Chicken replaces the veal, for a quicker dish."},{"title":"Turkey Marengo","intro":"A light, budget-friendly Marengo, made with turkey.","minutes":55,"calories":350,"difficulty":"Facile","imageSearch":"turkey tomato stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"diced turkey","plural":"diced turkey","qty":800,"unit":"g","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Brown the turkey in a casserole dish.","timer":{"label":"Cooking","min":6}},{"text":"Add the onions, wine and tomatoes.","timer":null},{"text":"Simmer for 30 minutes.","timer":{"label":"Simmer","min":30}},{"text":"Add the mushrooms and cook for 15 minutes.","timer":{"label":"Cooking","min":15}}],"variant":"With turkey","change":"With diced turkey, which is lighter."}]$r$::jsonb, 'claude')
