insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:jambalaya', 'Jambalaya', array['en:chicken and chorizo jambalaya', 'en:cajun rice']::text[], 'dish', $r$[{"title":"Jambalaya","intro":"The Louisiana Cajun rice with chicken, chorizo and prawns, cooked in a single pot.","minutes":50,"calories":580,"difficulty":"Moyen","imageSearch":"jambalaya","veg":false,"oven":false,"cold":false,"missing":"","origin":"Louisiana recipe","serves":4,"items":[{"name":"rice","plural":"rice","qty":300,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"chorizo","plural":"chorizo","qty":100,"unit":"g","have":false},{"name":"peeled prawn","plural":"peeled prawns","qty":200,"unit":"g","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"paprika","plural":"paprika","qty":2,"unit":"tsp","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":1,"unit":"","have":false}],"steps":[{"text":"Brown the diced chicken and the sliced chorizo in a casserole dish.","timer":{"label":"Cooking","min":6}},{"text":"Add the diced onion and pepper, and the paprika.","timer":null},{"text":"Add the rice, tomatoes, stock cube and 50 cl of water.","timer":null},{"text":"Cover and cook gently for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Add the prawns and cook for 5 minutes.","timer":{"label":"Cooking","min":5}}],"variant":"The classic","change":""},{"title":"Prawn jambalaya","intro":"The seafood jambalaya, with prawns.","minutes":40,"calories":450,"difficulty":"Moyen","imageSearch":"shrimp jambalaya","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rice","plural":"rice","qty":300,"unit":"g","have":false},{"name":"peeled prawn","plural":"peeled prawns","qty":400,"unit":"g","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"paprika","plural":"paprika","qty":2,"unit":"tsp","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false}],"steps":[{"text":"Fry the onion and pepper with the paprika.","timer":null},{"text":"Add the rice, tomatoes, stock cube and 50 cl of water.","timer":null},{"text":"Cover and cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Add the prawns and cook for 5 minutes.","timer":{"label":"Cooking","min":5}}],"variant":"Prawns","change":"Just prawns, with no meat."},{"title":"Vegetarian jambalaya","intro":"A vegetarian jambalaya, with kidney beans and vegetables.","minutes":40,"calories":420,"difficulty":"Facile","imageSearch":"vegetarian jambalaya","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rice","plural":"rice","qty":300,"unit":"g","have":false},{"name":"kidney bean","plural":"kidney beans","qty":400,"unit":"g","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"paprika","plural":"paprika","qty":2,"unit":"tsp","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false}],"steps":[{"text":"Fry the onion and peppers with the paprika.","timer":null},{"text":"Add the rice, tomatoes, stock cube and 50 cl of water.","timer":null},{"text":"Cover and cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Add the drained kidney beans and cook for 5 minutes.","timer":{"label":"Cooking","min":5}}],"variant":"Vegetarian","change":"With kidney beans instead of meat."}]$r$::jsonb, 'claude')
