insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:frite maison', 'French fries', array['en:french frie', 'en:chip', 'en:homemade chip', 'en:frite']::text[], 'dish', $r$[{"title":"Homemade chips","intro":"Crispy chips, cooked twice like in a restaurant.","minutes":50,"calories":380,"difficulty":"Moyen","imageSearch":"homemade french fries","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Peel the potatoes and cut them into 1 cm sticks.","timer":null},{"text":"Rinse them and dry them well in a tea towel.","timer":null},{"text":"Cook them for 6 minutes in oil at 160 °C, then drain.","timer":{"label":"Frying","min":6}},{"text":"Fry them again for 3 minutes in oil at 180 °C until golden.","timer":{"label":"Frying","min":3}},{"text":"Drain on kitchen paper and add salt.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Oven chips","intro":"Lighter, crispy chips with no deep fryer.","minutes":45,"calories":220,"difficulty":"Facile","imageSearch":"oven baked fries","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 220 °C.","timer":null},{"text":"Cut the potatoes into sticks, rinse them and dry them.","timer":null},{"text":"Toss them with the oil, paprika and salt, and spread them on a baking tray.","timer":null},{"text":"Bake for 35 minutes, turning them over halfway.","timer":{"label":"Oven","min":35}}],"kids":true,"variant":"No frying","change":"Baked in the oven with a little oil."},{"title":"Sweet potato fries","intro":"Orange, sweet and crispy fries.","minutes":40,"calories":230,"difficulty":"Facile","imageSearch":"sweet potato fries","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sweet potato","plural":"sweet potatoes","qty":3,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tbsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 220 °C.","timer":null},{"text":"Cut the sweet potatoes into sticks and coat them in the cornflour, oil and paprika.","timer":null},{"text":"Spread them out on a baking tray so they do not touch.","timer":null},{"text":"Bake for 30 minutes, turning them over halfway.","timer":{"label":"Oven","min":30}}],"kids":true,"variant":"Sweet potato","change":"Made with sweet potatoes, baked."}]$r$::jsonb, 'claude')
