insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pomme de terre sautee', 'Sautéed potatoes', array['en:sauteed potatoe', 'en:pan fried potatoe', 'en:fried potatoe', 'en:sarladaise potatoe', 'en:sarladaise']::text[], 'dish', $r$[{"title":"Sautéed potatoes","intro":"Potatoes browned in a pan, with garlic and parsley.","minutes":35,"calories":280,"difficulty":"Facile","imageSearch":"pan fried potatoes","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"oil","plural":"oil","qty":3,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Peel the potatoes and cut them into cubes.","timer":null},{"text":"Brown them for 25 minutes in the oil and butter over a medium heat, stirring often.","timer":{"label":"Pan","min":25}},{"text":"Add the chopped garlic and parsley at the end of cooking.","timer":null},{"text":"Season with salt and pepper.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Sarladaise potatoes","intro":"The potatoes of Périgord, cooked in duck fat with garlic.","minutes":40,"calories":380,"difficulty":"Facile","imageSearch":"sarladaise potatoes duck fat","veg":false,"oven":false,"cold":false,"missing":"","origin":"Périgord speciality","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"duck fat","plural":"duck fat","qty":3,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Peel the potatoes and cut them into slices.","timer":null},{"text":"Brown them for 30 minutes in the duck fat, turning them over.","timer":{"label":"Pan","min":30}},{"text":"Add the chopped garlic and parsley 5 minutes before the end.","timer":null},{"text":"Season with salt and pepper.","timer":null}],"kids":true,"variant":"Sarladaise","change":"Sautéed in duck fat."},{"title":"Sautéed potatoes with bacon","intro":"A hearty fry-up of potatoes with bacon.","minutes":35,"calories":420,"difficulty":"Facile","imageSearch":"potatoes bacon onions skillet","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":200,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"oil","plural":"oil","qty":2,"unit":"tbsp","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the potatoes into cubes.","timer":null},{"text":"Brown them for 20 minutes in the oil.","timer":{"label":"Pan","min":20}},{"text":"Add the bacon lardons and sliced onions and cook for 10 minutes.","timer":{"label":"Pan","min":10}},{"text":"Sprinkle with parsley.","timer":null}],"kids":true,"variant":"With bacon","change":"With bacon lardons and onions."}]$r$::jsonb, 'claude')
