insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pomme de terre au four', 'Roast potatoes', array['en:roast potatoe', 'en:oven baked potatoe', 'en:baked potatoe', 'en:smashed potatoe', 'en:jacket potatoe']::text[], 'dish', $r$[{"title":"Roast potato wedges","intro":"Potato wedges roasted with thyme and garlic, crispy on the outside.","minutes":50,"calories":250,"difficulty":"Facile","imageSearch":"roasted potato wedges","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":4,"unit":"clove","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 210 °C.","timer":null},{"text":"Cut the potatoes into wedges without peeling them.","timer":null},{"text":"Toss them with the oil, thyme, unpeeled garlic and salt.","timer":null},{"text":"Bake for 40 minutes, stirring halfway.","timer":{"label":"Oven","min":40}}],"kids":true,"variant":"The classic","change":""},{"title":"Smashed potatoes","intro":"The crispy smashed potatoes that are so popular right now.","minutes":55,"calories":260,"difficulty":"Facile","imageSearch":"smashed potatoes","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"baby potato","plural":"baby potatoes","qty":800,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"parmesan","plural":"parmesan","qty":30,"unit":"g","have":false},{"name":"garlic powder","plural":"garlic powder","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes in salted water for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Preheat the oven to 220 °C. Put them on a baking tray and smash them with a glass.","timer":null},{"text":"Drizzle with oil and sprinkle with garlic powder and Parmesan.","timer":null},{"text":"Bake for 25 minutes.","timer":{"label":"Oven","min":25}}],"kids":true,"variant":"Smashed","change":"Baby potatoes boiled, smashed and then roasted."},{"title":"Baked potatoes","intro":"Baked potatoes with chive cream.","minutes":70,"calories":300,"difficulty":"Facile","imageSearch":"baked potato sour cream chives","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":4,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"chives","plural":"chives","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Prick the potatoes and wrap them in foil.","timer":null},{"text":"Bake for 1 hour.","timer":{"label":"Oven","min":60}},{"text":"Mix the crème fraîche with the chives, salt and pepper.","timer":null},{"text":"Split the potatoes open and fill them with the cream.","timer":null}],"kids":true,"variant":"Stuffed","change":"Baked whole, with a chive cream filling."}]$r$::jsonb, 'claude')
