insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:aligot', 'Aligot', array['en:aligot aubrac', 'en:cheesy mashed potatoe', 'en:truffade']::text[], 'dish', $r$[{"title":"Aligot","intro":"The stretchy mash from Aubrac, made with fresh tomme and garlic.","minutes":45,"calories":580,"difficulty":"Moyen","imageSearch":"aligot cheesy mashed potatoes","veg":true,"oven":false,"cold":false,"missing":"","origin":"Aubrac speciality","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"fresh tomme cheese","plural":"fresh tomme cheese","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":50,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes in salted water for 25 minutes.","timer":{"label":"Cooking","min":25}},{"text":"Mash them with the butter, cream and crushed garlic over a low heat.","timer":null},{"text":"Add the sliced tomme a little at a time.","timer":null},{"text":"Stir vigorously, lifting the mash, until the aligot is stretchy.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Aligot with sausage","intro":"The aligot as a full meal, with sausages.","minutes":50,"calories":820,"difficulty":"Moyen","imageSearch":"aligot sausage","veg":false,"oven":false,"cold":false,"missing":"","origin":"Aubrac speciality","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"fresh tomme cheese","plural":"fresh tomme cheese","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":50,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"toulouse sausage","plural":"toulouse sausages","qty":4,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes for 25 minutes.","timer":{"label":"Cooking","min":25}},{"text":"Meanwhile, fry the sausages in a pan for 15 minutes.","timer":{"label":"Pan","min":15}},{"text":"Mash the potatoes with the butter, cream and garlic over a low heat.","timer":null},{"text":"Add the tomme and stir until stretchy.","timer":null}],"kids":true,"variant":"With sausage","change":"Served with grilled Toulouse sausages."},{"title":"Truffade","intro":"The Auvergne dish: sautéed potatoes with melted tomme.","minutes":45,"calories":620,"difficulty":"Facile","imageSearch":"truffade potatoes cheese","veg":false,"oven":false,"cold":false,"missing":"","origin":"Auvergne speciality","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"fresh tomme cheese","plural":"fresh tomme cheese","qty":300,"unit":"g","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":100,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the potatoes into thin slices.","timer":null},{"text":"Brown them for 25 minutes with the bacon lardons.","timer":{"label":"Pan","min":25}},{"text":"Add the chopped garlic and the sliced tomme.","timer":null},{"text":"Stir until the cheese melts and sprinkle with parsley.","timer":null}],"variant":"Truffade","change":"Sautéed potatoes with tomme, rather than mash."}]$r$::jsonb, 'claude')
