insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gratin de pate', 'Pasta bake', array['en:pasta bake', 'en:baked pasta', 'en:macaroni cheese', 'en:mac and cheese', 'en:pasta gratin']::text[], 'dish', $r$[{"title":"Ham and cheese pasta bake","intro":"Pasta in a white sauce with ham, baked with a topping of emmental.","minutes":45,"calories":580,"difficulty":"Facile","imageSearch":"pasta bake ham cheese","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"short pasta","plural":"short pasta","qty":400,"unit":"g","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":40,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":120,"unit":"g","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cook the pasta for 2 minutes less than the packet says.","timer":{"label":"Cooking","min":8}},{"text":"Melt the butter, add the flour, then whisk in the milk until thickened.","timer":null},{"text":"Season with salt and pepper and add a little nutmeg.","timer":null},{"text":"Mix the pasta, diced ham and white sauce in a dish.","timer":null},{"text":"Cover with emmental and bake for 20 minutes.","timer":{"label":"Oven","min":20}}],"kids":true,"variant":"The classic","change":""},{"title":"Mac and cheese","intro":"The ultra-melting American dish, with cheddar.","minutes":40,"calories":620,"difficulty":"Facile","imageSearch":"mac and cheese","veg":true,"oven":true,"cold":false,"missing":"","origin":"American recipe","serves":4,"items":[{"name":"macaroni","plural":"macaroni","qty":400,"unit":"g","have":false},{"name":"grated cheddar","plural":"grated cheddar","qty":200,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":40,"unit":"g","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cook the macaroni.","timer":{"label":"Cooking","min":8}},{"text":"Make a white sauce with the butter, flour and milk.","timer":null},{"text":"Add three quarters of the cheddar and stir until melted.","timer":null},{"text":"Mix with the pasta, pour into a dish and cover with the rest of the cheddar and the breadcrumbs.","timer":null},{"text":"Bake for 15 minutes.","timer":{"label":"Oven","min":15}}],"kids":true,"variant":"Mac and cheese","change":"Macaroni in a cheddar sauce."},{"title":"Vegetable pasta bake","intro":"A vegetarian pasta bake, full of vegetables.","minutes":45,"calories":480,"difficulty":"Facile","imageSearch":"vegetable pasta bake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"short pasta","plural":"short pasta","qty":350,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cook the pasta.","timer":{"label":"Cooking","min":8}},{"text":"Fry the diced courgette and pepper for 8 minutes, then add the tomatoes.","timer":{"label":"Pan","min":8}},{"text":"Mix with the pasta in a dish.","timer":null},{"text":"Cover with mozzarella and emmental, and bake for 20 minutes.","timer":{"label":"Oven","min":20}}],"kids":true,"variant":"Vegetarian","change":"With courgette, pepper and tomatoes."}]$r$::jsonb, 'claude')
