insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:rosti', 'Rösti', array['en:potato pancake', 'en:potato fritter']::text[], 'dish', $r$[{"title":"Rösti","intro":"Grated potato cakes, golden and crispy.","minutes":35,"calories":250,"difficulty":"Facile","imageSearch":"rosti potato pancakes","veg":true,"oven":false,"cold":false,"missing":"","origin":"Swiss speciality","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"flour","plural":"flour","qty":2,"unit":"tbsp","have":false},{"name":"oil","plural":"oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Grate the potatoes and onion, and squeeze them in a tea towel to remove the water.","timer":null},{"text":"Mix with the egg, flour, salt and pepper.","timer":null},{"text":"Shape into cakes and brown for 5 minutes on each side in hot oil.","timer":{"label":"Pan","min":10}},{"text":"Drain on kitchen paper.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Cheese rösti","intro":"Melting cheese rösti that kids love.","minutes":35,"calories":320,"difficulty":"Facile","imageSearch":"cheese potato rosti","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"flour","plural":"flour","qty":2,"unit":"tbsp","have":false},{"name":"oil","plural":"oil","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Grate the potatoes and squeeze out the water.","timer":null},{"text":"Mix with the emmental, egg and flour, then season with salt and pepper.","timer":null},{"text":"Brown the cakes for 5 minutes on each side.","timer":{"label":"Pan","min":10}},{"text":"Serve with a green salad.","timer":null}],"kids":true,"variant":"With cheese","change":"With grated cheese in the cakes."},{"title":"Courgette fritters","intro":"Light vegetable fritters, with courgette and feta.","minutes":30,"calories":200,"difficulty":"Facile","imageSearch":"zucchini fritters","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":3,"unit":"","have":false},{"name":"feta","plural":"feta","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"flour","plural":"flour","qty":4,"unit":"tbsp","have":false},{"name":"fresh mint","plural":"fresh mint","qty":null,"unit":"","have":false},{"name":"oil","plural":"oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Grate the courgettes, salt them and squeeze out the water.","timer":null},{"text":"Mix with the crumbled feta, eggs, flour and mint.","timer":null},{"text":"Brown small fritters for 3 minutes on each side.","timer":{"label":"Pan","min":6}},{"text":"Serve with lemony yoghurt.","timer":null}],"variant":"Courgette","change":"With grated courgette and feta."}]$r$::jsonb, 'claude')
