insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:patate douce rotie', 'Roast sweet potatoes', array['en:roast sweet potatoe', 'en:baked sweet potatoe', 'en:oven baked sweet potatoe']::text[], 'dish', $r$[{"title":"Roast sweet potatoes","intro":"Sweet potatoes roasted with paprika and cumin, soft and caramelised.","minutes":45,"calories":220,"difficulty":"Facile","imageSearch":"roasted sweet potatoes","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sweet potato","plural":"sweet potatoes","qty":3,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 210 °C.","timer":null},{"text":"Cut the sweet potatoes into cubes without peeling them.","timer":null},{"text":"Toss them with the oil, paprika, cumin and salt.","timer":null},{"text":"Bake for 35 minutes, stirring halfway.","timer":{"label":"Oven","min":35}}],"kids":true,"variant":"The classic","change":""},{"title":"Stuffed sweet potatoes","intro":"Baked sweet potatoes as a full vegetarian meal.","minutes":60,"calories":400,"difficulty":"Facile","imageSearch":"stuffed sweet potatoes","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sweet potato","plural":"sweet potatoes","qty":4,"unit":"","have":false},{"name":"kidney bean","plural":"kidney beans","qty":250,"unit":"g","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"soft cheese","plural":"soft cheese","qty":100,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Prick the sweet potatoes and bake them for 50 minutes.","timer":{"label":"Oven","min":50}},{"text":"Warm the drained kidney beans.","timer":null},{"text":"Dice the avocado and sprinkle with lime juice.","timer":null},{"text":"Split the sweet potatoes open and top with the beans, avocado, soft cheese and coriander.","timer":null}],"variant":"Stuffed","change":"Baked whole and topped with beans, avocado and soft cheese."},{"title":"Sweet potato mash","intro":"A soft, smooth orange mash.","minutes":30,"calories":240,"difficulty":"Facile","imageSearch":"sweet potato mash","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sweet potato","plural":"sweet potatoes","qty":4,"unit":"","have":false},{"name":"coconut milk","plural":"coconut milk","qty":10,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Peel the sweet potatoes and cut them into pieces.","timer":null},{"text":"Boil them in salted water for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Drain and mash with the coconut milk and butter.","timer":null},{"text":"Season with salt and nutmeg.","timer":null}],"kids":true,"variant":"Mash","change":"Mashed, with coconut milk."}]$r$::jsonb, 'claude')
