insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gratin de legume', 'Vegetable gratin', array['en:vegetable gratin', 'en:baked vegetable', 'en:gratinated vegetable']::text[], 'dish', $r$[{"title":"Vegetable gratin","intro":"Courgettes, peppers and potatoes in a light white sauce, baked with cheese.","minutes":60,"calories":320,"difficulty":"Facile","imageSearch":"vegetable gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":3,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"milk","plural":"milk","qty":40,"unit":"cl","have":false},{"name":"flour","plural":"flour","qty":30,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":100,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Slice the vegetables and boil the potatoes for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Make a white sauce with the butter, flour and milk.","timer":null},{"text":"Arrange the vegetables in a dish, cover with the sauce and sprinkle with emmental.","timer":null},{"text":"Bake for 35 minutes.","timer":{"label":"Oven","min":35}}],"kids":true,"variant":"The classic","change":""},{"title":"Leek gratin","intro":"A mild, creamy gratin made entirely with leeks.","minutes":50,"calories":300,"difficulty":"Facile","imageSearch":"leek gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"leek","plural":"leeks","qty":5,"unit":"","have":false},{"name":"milk","plural":"milk","qty":40,"unit":"cl","have":false},{"name":"flour","plural":"flour","qty":30,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":100,"unit":"g","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Cut the leeks into chunks and soften them for 10 minutes in a pan with a little butter.","timer":{"label":"Pan","min":10}},{"text":"Make a white sauce with the rest of the butter, the flour and milk, then add the nutmeg.","timer":null},{"text":"Put the leeks in a dish, cover with the sauce and sprinkle with emmental.","timer":null},{"text":"Bake for 25 minutes.","timer":{"label":"Oven","min":25}}],"kids":true,"variant":"Leeks","change":"With leeks softened in a white sauce."},{"title":"Winter vegetable gratin","intro":"A comforting gratin of winter vegetables.","minutes":60,"calories":330,"difficulty":"Facile","imageSearch":"winter vegetable gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pumpkin","plural":"pumpkin","qty":600,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"grated emmental","plural":"grated emmental","qty":100,"unit":"g","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Dice the pumpkin, slice the carrots and cut the leeks into chunks.","timer":null},{"text":"Steam them for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Arrange them in a dish with the cream, nutmeg, salt and pepper, then add the emmental.","timer":null},{"text":"Bake for 30 minutes.","timer":{"label":"Oven","min":30}}],"kids":true,"variant":"Winter","change":"With pumpkin, carrots and leeks."}]$r$::jsonb, 'claude')
