insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poelee de legume', 'Sautéed vegetables', array['en:sauteed vegetable', 'en:vegetable stir fry', 'en:pan fried vegetable', 'en:vegetable wok']::text[], 'dish', $r$[{"title":"Sautéed vegetables","intro":"Seasonal vegetables fried in a pan, still crunchy, with garlic and herbs.","minutes":25,"calories":150,"difficulty":"Facile","imageSearch":"sauteed vegetables","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":200,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"mixed herbs","plural":"mixed herbs","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Cut all the vegetables into pieces of the same size.","timer":null},{"text":"Fry the onion and carrots for 5 minutes in the oil.","timer":{"label":"Pan","min":5}},{"text":"Add the pepper, courgette and mushrooms and cook for 10 minutes over a high heat.","timer":{"label":"Pan","min":10}},{"text":"Season with the herbs, salt and pepper.","timer":null}],"variant":"The classic","change":""},{"title":"Vegetable stir-fry","intro":"An Asian-style vegetable stir-fry, quick and crunchy.","minutes":20,"calories":160,"difficulty":"Facile","imageSearch":"vegetable stir fry","veg":true,"oven":false,"cold":false,"missing":"","origin":"Asian-inspired","serves":4,"items":[{"name":"broccoli","plural":"broccolis","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"mangetout","plural":"mangetout","qty":150,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"sesame oil","plural":"sesame oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Cut the vegetables into thin strips and the broccoli into small florets.","timer":null},{"text":"Stir-fry the carrots and broccoli for 4 minutes over a very high heat.","timer":{"label":"Pan","min":4}},{"text":"Add the pepper, mangetout and ginger, and cook for 3 minutes.","timer":{"label":"Pan","min":3}},{"text":"Drizzle with the soy sauce and sesame oil.","timer":null}],"variant":"Stir-fried","change":"Stir-fried with soy sauce and ginger."},{"title":"Vegetable and egg skillet","intro":"A hearty skillet, topped with fried eggs.","minutes":25,"calories":260,"difficulty":"Facile","imageSearch":"vegetable skillet eggs","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the onion, pepper and courgette for 10 minutes.","timer":{"label":"Pan","min":10}},{"text":"Add the diced tomatoes and cook for 5 minutes.","timer":{"label":"Pan","min":5}},{"text":"Make 4 wells and crack an egg into each.","timer":null},{"text":"Cover and cook for 5 minutes.","timer":{"label":"Pan","min":5}}],"variant":"With eggs","change":"With eggs cooked in the middle of the vegetables."}]$r$::jsonb, 'claude')
